function isoFromFlag(flagEmoji){
  const codePoints = [...flagEmoji].map(c => c.codePointAt(0) - 0x1F1E6 + 97);
  if(codePoints.length !== 2 || codePoints.some(c => c < 97 || c > 122)) return null;
  return String.fromCharCode(...codePoints);
}
let legalMapRendered = false;
function renderLegalMap(){
  const holder = document.getElementById('legalMapSvgHolder');
  if(!holder) return;
  if(!legalMapRendered){
    holder.innerHTML = worldMapSvg;
    legalMapRendered = true;
  }
  const svgEl = holder.querySelector('svg');
  if(!svgEl) return;
  svgEl.style.width = '100%';
  svgEl.style.height = 'auto';
  svgEl.style.display = 'block';
  const isoToCountry = {};
  countries.forEach(c => { const iso = isoFromFlag(c.flag); if(iso) isoToCountry[iso] = c; });
  const applyStyle = (path, c) => {
    if(c){
      path.style.fill = c.color;
      path.style.cursor = 'pointer';
      path.style.stroke = 'var(--paper)';
      path.style.strokeWidth = '0.5';
      path.onclick = () => { setLegalView('list'); showDetail(c); };
    } else {
      path.style.fill = 'var(--line-strong)';
      path.style.stroke = 'var(--paper)';
      path.style.strokeWidth = '0.5';
      path.onclick = null;
      path.style.cursor = 'default';
    }
  };
  // Elementos <path> con id directo (países de forma simple)
  const allPaths = svgEl.getElementsByTagNameNS('http://www.w3.org/2000/svg', 'path');
  Array.prototype.forEach.call(allPaths, path => {
    if(path.closest('g[id]')) return; // se maneja abajo, vía el grupo padre
    const iso = path.getAttribute('id');
    const c = iso ? isoToCountry[iso] : null;
    applyStyle(path, c);
  });
  // Elementos <g id="xx"> con múltiples <path> internos (países con islas/territorios)
  const allGroups = svgEl.getElementsByTagNameNS('http://www.w3.org/2000/svg', 'g');
  Array.prototype.forEach.call(allGroups, g => {
    const iso = g.getAttribute('id');
    const c = iso ? isoToCountry[iso] : null;
    const innerPaths = g.getElementsByTagNameNS('http://www.w3.org/2000/svg', 'path');
    Array.prototype.forEach.call(innerPaths, path => applyStyle(path, c));
  });
}
function setLegalView(mode){
  const mapC = document.getElementById('legalMapContainer');
  const listC = document.getElementById('countryGrid');
  const mapBtn = document.getElementById('legalViewMapBtn');
  const listBtn = document.getElementById('legalViewListBtn');
  if(!mapC || !listC) return;
  if(mode === 'map'){
    mapC.style.display = 'block';
    listC.style.display = 'none';
    mapBtn.style.background = 'var(--ink)'; mapBtn.style.color = 'var(--paper)'; mapBtn.style.border = '1px solid var(--ink)';
    listBtn.style.background = 'transparent'; listBtn.style.color = 'var(--ink-soft)'; listBtn.style.border = '1px solid var(--line-strong)';
    renderLegalMap();
  } else {
    mapC.style.display = 'none';
    listC.style.display = '';
    listBtn.style.background = 'var(--ink)'; listBtn.style.color = 'var(--paper)'; listBtn.style.border = '1px solid var(--ink)';
    mapBtn.style.background = 'transparent'; mapBtn.style.color = 'var(--ink-soft)'; mapBtn.style.border = '1px solid var(--line-strong)';
  }
}
function flagFallback(imgEl, iso){
  const span = document.createElement('span');
  span.textContent = iso.toUpperCase();
  span.style.cssText = 'display:inline-block; background:var(--line-strong); color:var(--ink-soft); font-family:\'IBM Plex Mono\',monospace; font-size:10px; font-weight:600; padding:1px 4px; border-radius:2px; letter-spacing:0.03em; vertical-align:middle;';
  imgEl.replaceWith(span);
}
function flagImg(flagEmoji, size){
  if(!flagEmoji) return '';
  size = size || 16;
  const codePoints = [...flagEmoji].map(c => c.codePointAt(0) - 0x1F1E6 + 97);
  if(codePoints.length !== 2 || codePoints.some(c => c < 97 || c > 122)) return flagEmoji;
  const iso = String.fromCharCode(...codePoints);
  const w = Math.round(size * 1.33);
  const svg = flagSvgs[iso];
  if(!svg){
    return `<span style="display:inline-block; background:var(--line-strong); color:var(--ink-soft); font-family:'IBM Plex Mono',monospace; font-size:${Math.round(size*0.6)}px; font-weight:600; padding:1px 4px; border-radius:2px; letter-spacing:0.03em; vertical-align:middle;">${iso.toUpperCase()}</span>`;
  }
  return `<span style="display:inline-block; width:${w}px; height:${size}px; vertical-align:middle; border-radius:2px; overflow:hidden; line-height:0;">${svg}</span>`;
}

const glossary = [
  {term:{es:'Absorción de nutrientes', en:'Nutrient uptake', de:'Nährstoffaufnahme', fr:'Absorption des nutriments'}, def:{es:'El proceso mediante el cual las raíces captan los nutrientes disueltos para su transporte y uso dentro de la planta.', en:'The process by which roots take up dissolved nutrients for transport and use within the plant.', de:'Der Prozess, durch den die Wurzeln gelöste Nährstoffe aufnehmen, um sie innerhalb der Pflanze zu transportieren und zu nutzen.', fr:'Le processus par lequel les racines captent les nutriments dissous pour leur transport et leur utilisation au sein de la plante.'}},
  {term:{es:'Ácaro (Spider mite)', en:'Spider mite', de:'Spinnmilbe', fr:'Tétranyque (Spider mite)'}, def:{es:'Ácaro que perfora células de las hojas causando punteado amarillento y telarañas — problemático por su rápida reproducción y resistencia a pesticidas.', en:'A mite that punctures leaf cells causing yellowish stippling and webbing — problematic due to its rapid reproduction and pesticide resistance.', de:'Eine Milbe, die Blattzellen durchsticht und dabei gelbliche Sprenkelungen und Gespinste verursacht — problematisch wegen ihrer schnellen Vermehrung und Pestizidresistenz.', fr:'Acarien qui perce les cellules foliaires, causant un maculage jaunâtre et des toiles — problématique en raison de sa reproduction rapide et de sa résistance aux pesticides.'}},
  {term:{es:'Ácaro ancho (Broad mite)', en:'Broad mite', de:'Breitmilbe', fr:'Acarien large (Broad mite)'}, def:{es:'Ácaro microscópico que ataca tejido nuevo, causando deformación y rizado — a menudo confundido con fitotoxicidad.', en:'A microscopic mite that attacks new tissue, causing deformation and curling — often mistaken for phytotoxicity.', de:'Eine mikroskopisch kleine Milbe, die neues Gewebe befällt und Deformationen sowie Kräuselungen verursacht — wird oft mit Phytotoxizität verwechselt.', fr:'Acarien microscopique qui attaque les tissus nouveaux, causant déformation et enroulement — souvent confondu avec une phytotoxicité.'}},
  {term:{es:'Ácaro russet', en:'Russet mite', de:'Russetmilbe (Bronzemilbe)', fr:'Acarien russet'}, def:{es:'Ácaro microscópico (requiere lupa 30x+) que causa bronceado/curvado de hojas — detección tardía por su tamaño.', en:'A microscopic mite (requires a 30x+ loupe) that causes bronzing/curling of leaves — often detected late due to its size.', de:'Eine mikroskopisch kleine Milbe (erfordert eine Lupe mit 30x+ Vergrößerung), die Blätter bronzefarben verfärbt/kräuselt — wird aufgrund ihrer Größe oft erst spät erkannt.', fr:'Acarien microscopique (nécessite une loupe 30x ou plus) causant un bronzage/enroulement des feuilles — détection tardive en raison de sa taille.'}},
  {term:{es:'Aclimatación (Hardening off)', en:'Hardening off', de:'Abhärten', fr:'Acclimatation (Hardening off)'}, def:{es:'Exponer gradualmente una planta a condiciones ambientales más duras antes de un cambio de entorno definitivo.', en:'Gradually exposing a plant to harsher environmental conditions before a permanent change of environment.', de:'Eine Pflanze schrittweise raueren Umweltbedingungen aussetzen, bevor ein endgültiger Umgebungswechsel erfolgt.', fr:'Exposer progressivement une plante à des conditions environnementales plus rudes avant un changement d’environnement définitif.'}},
  {term:{es:'Actividad de agua (aw)', en:'Water activity (aw)', de:'Wasseraktivität (aw)', fr:'Activité de l’eau (aw)'}, def:{es:'Medida de la disponibilidad de agua "libre" en un material, en escala 0-1 — el indicador más preciso del riesgo microbiológico. El estándar oficial ASTM D8197 establece 0.55-0.65 aw como rango ideal para cannabis — el mismo rango que el estudio de Riley Kirk (ver Elaboración → Procesos) identificó como óptimo también para sabor y calidad de fumado.', en:'A measure of the "free" water available in a material, on a 0-1 scale — the most precise indicator of microbiological risk. The official ASTM D8197 standard sets 0.55-0.65 aw as the ideal range for cannabis — the same range that Riley Kirk’s study (see Making → Processes) identified as optimal for flavor and smoke quality too.', de:'Ein Maß für das "freie" Wasser, das in einem Material verfügbar ist, auf einer Skala von 0-1 — der genaueste Indikator für das mikrobiologische Risiko. Der offizielle Standard ASTM D8197 legt 0,55-0,65 aw als idealen Bereich für Cannabis fest — denselben Bereich, den die Studie von Riley Kirk (siehe Verarbeitung → Prozesse) auch als optimal für Geschmack und Rauchqualität ermittelte.', fr:'Mesure de l’eau « libre » disponible dans un matériau, sur une échelle de 0 à 1 — l’indicateur le plus précis du risque microbiologique. La norme officielle ASTM D8197 fixe 0,55-0,65 aw comme plage idéale pour le cannabis — la même plage que l’étude de Riley Kirk (voir Élaboration → Procédés) a identifiée comme optimale également pour la saveur et la qualité de combustion.'}},
  {term:{es:'Aeroponía', en:'Aeroponics', de:'Aeroponik', fr:'Aéroponie'}, def:{es:'Método de cultivo sin sustrato donde las raíces quedan suspendidas en el aire dentro de una cámara cerrada y se nebulizan periódicamente con solución nutritiva en forma de gotas finas.', en:'A substrate-less growing method where roots hang suspended in the air inside a closed chamber and are periodically misted with nutrient solution as fine droplets.', de:'Eine substratlose Anbaumethode, bei der die Wurzeln in der Luft innerhalb einer geschlossenen Kammer hängen und periodisch mit Nährlösung in Form feiner Tröpfchen vernebelt werden.', fr:'Méthode de culture sans substrat où les racines restent suspendues dans l’air à l’intérieur d’une chambre fermée et sont périodiquement brumisées avec une solution nutritive sous forme de fines gouttelettes.'}},
  {term:{es:'Áfido/Pulgón', en:'Aphid', de:'Blattlaus', fr:'Puceron'}, def:{es:'Insecto chupador de savia que puede transmitir virus y produce melaza que favorece el moho.', en:'A sap-sucking insect that can transmit viruses and produces honeydew that promotes mold.', de:'Ein saugendes Insekt, das Viren übertragen kann und Honigtau produziert, der Schimmelbildung begünstigt.', fr:'Insecte piqueur-suceur de sève pouvant transmettre des virus et produisant du miellat qui favorise la moisissure.'}},
  {term:{es:'Agricultura vertical (Vertical farming)', en:'Vertical farming', de:'Vertikale Landwirtschaft', fr:'Agriculture verticale'}, def:{es:'Cultivo en niveles apilados superpuestos, maximizando producción por metro cuadrado.', en:'Cultivation in stacked, overlapping levels, maximizing production per square meter.', de:'Anbau in gestapelten, übereinanderliegenden Ebenen, um die Produktion pro Quadratmeter zu maximieren.', fr:'Culture sur des niveaux superposés empilés, maximisant la production par mètre carré.'}},
  {term:{es:'Aislado (isolate)', en:'Isolate', de:'Isolate', fr:'Isolat'}, def:{es:'Un solo cannabinoide puro, sin terpenos ni otros compuestos.', en:'A single pure cannabinoid, with no terpenes or other compounds.', de:'Ein einzelnes reines Cannabinoid, ohne Terpene oder andere Verbindungen.', fr:'Un seul cannabinoïde pur, sans terpènes ni autres composés.'}},
  {term:{es:'Alfa-pineno', en:'Alpha-pinene', de:'Alpha-Pinen', fr:'Alpha-pinène'}, def:{es:'Aroma a pino. Estudiado por posibles propiedades antiinflamatorias, broncodilatadoras y neuroprotectoras — no se une directamente a CB1/CB2, a diferencia del cariofileno.', en:'Pine aroma. Studied for possible anti-inflammatory, bronchodilatory, and neuroprotective properties — does not bind directly to CB1/CB2, unlike caryophyllene.', de:'Kieferartiges Aroma. Untersucht auf mögliche entzündungshemmende, bronchienerweiternde und neuroprotektive Eigenschaften — bindet im Gegensatz zu Caryophyllen nicht direkt an CB1/CB2.', fr:'Arôme de pin. Étudié pour ses propriétés anti-inflammatoires, bronchodilatatrices et neuroprotectrices potentielles — ne se lie pas directement au CB1/CB2, contrairement au caryophyllène.'}},
  {term:{es:'Amortiguación (Buffering)', en:'Buffering', de:'Pufferung (Buffering)', fr:'Effet tampon (Buffering)'}, def:{es:'La capacidad de una solución o sustrato de resistir cambios bruscos de pH.', en:'The ability of a solution or substrate to resist sudden changes in pH.', de:'Die Fähigkeit einer Lösung oder eines Substrats, plötzlichen pH-Wert-Änderungen zu widerstehen.', fr:'La capacité d’une solution ou d’un substrat à résister aux changements brusques de pH.'}},
  {term:{es:'Anandamida', en:'Anandamide', de:'Anandamid', fr:'Anandamide'}, def:{es:'El primer endocannabinoide identificado en el cuerpo humano, descubierto por el Dr. Vincenzo Di Marzo en 1992 — el equivalente natural del THC que produce el propio cuerpo.', en:'The first endocannabinoid identified in the human body, discovered by Dr. Vincenzo Di Marzo in 1992 — the body’s own natural equivalent of THC.', de:'Das erste im menschlichen Körper identifizierte Endocannabinoid, entdeckt von Dr. Vincenzo Di Marzo 1992 — das körpereigene natürliche Äquivalent von THC.', fr:'Le premier endocannabinoïde identifié dans le corps humain, découvert par le Dr Vincenzo Di Marzo en 1992 — l’équivalent naturel du THC produit par le corps lui-même.'}},
  {term:{es:'Autofecundación (Selfing/S1)', en:'Selfing (S1)', de:'Selfing (S1)', fr:'Autofécondation (Selfing/S1)'}, def:{es:'El proceso de polinizar una planta hembra con su propio polen inducido (ya que el cannabis es naturalmente dioico) — produce semillas genéticamente muy similares a la madre. Requiere inducir producción de polen en una hembra genética, vía estrés o tratamiento con plata coloidal/STS — una práctica común mal entendida por cultivadores nuevos.', en:'The process of pollinating a female plant with its own induced pollen (since cannabis is naturally dioecious) — produces seeds genetically very similar to the mother. Requires inducing pollen production in a genetic female, via stress or colloidal silver/STS treatment — a common practice often misunderstood by new growers.', de:'Der Prozess, eine weibliche Pflanze mit ihrem eigenen, induzierten Pollen zu bestäuben (da Cannabis natürlicherweise zweihäusig ist) — erzeugt Samen, die genetisch der Mutter sehr ähnlich sind. Erfordert die Induktion der Pollenproduktion bei einem genetischen Weibchen, durch Stress oder eine Behandlung mit kolloidalem Silber/STS — eine gängige, von neuen Growern oft missverstandene Praxis.', fr:'Le processus consistant à polliniser une plante femelle avec son propre pollen induit (le cannabis étant naturellement dioïque) — produit des graines génétiquement très proches de la mère. Nécessite d’induire la production de pollen chez une femelle génétique, par stress ou traitement à l’argent colloïdal/STS — une pratique courante souvent mal comprise par les nouveaux cultivateurs.'}},
  {term:{es:'Autofloración', en:'Autoflowering', de:'Autoflowering', fr:'Autofloraison'}, def:{es:'Genética que florece por edad, no por cambio de fotoperiodo.', en:'Genetics that flower by age, not by a change in photoperiod.', de:'Genetik, die nach Alter blüht, nicht durch eine Änderung der Photoperiode.', fr:'Génétique qui fleurit selon l’âge, pas selon un changement de photopériode.'}},
  {term:{es:'Auxina', en:'Auxin', de:'Auxin', fr:'Auxine'}, def:{es:'Hormona vegetal producida principalmente en el meristemo apical, responsable de la dominancia apical: inhibe el crecimiento de yemas laterales mientras la punta principal se mantiene activa.', en:'A plant hormone produced mainly in the apical meristem, responsible for apical dominance: it inhibits lateral bud growth while the main tip stays active.', de:'Ein Pflanzenhormon, das hauptsächlich im apikalen Meristem gebildet wird und für die apikale Dominanz verantwortlich ist: Es hemmt das Wachstum seitlicher Knospen, während die Haupttriebspitze aktiv bleibt.', fr:'Hormone végétale produite principalement dans le méristème apical, responsable de la dominance apicale : elle inhibe la croissance des bourgeons latéraux tant que la pointe principale reste active.'}},
  {term:{es:'Azufre (S)', en:'Sulfur (S)', de:'Schwefel (S)', fr:'Soufre (S)'}, def:{es:'Macronutriente secundario necesario para síntesis de aminoácidos, proteínas y compuestos aromáticos.', en:'A secondary macronutrient needed for the synthesis of amino acids, proteins, and aromatic compounds.', de:'Ein sekundärer Makronährstoff, der für die Synthese von Aminosäuren, Proteinen und Aromastoffen notwendig ist.', fr:'Macronutriment secondaire nécessaire à la synthèse des acides aminés, des protéines et des composés aromatiques.'}},
  {term:{es:'Banco de clones (Clone bank)', en:'Clone bank', de:'Klonbank', fr:'Banque de clones'}, def:{es:'Una colección de plantas madre mantenida para preservar y producir clones.', en:'A collection of mother plants kept to preserve and produce clones.', de:'Eine Sammlung von Mutterpflanzen, die zur Erhaltung und Produktion von Klonen gepflegt wird.', fr:'Une collection de plantes mères entretenue pour préserver et produire des clones.'}},
  {term:{es:'Banco de semillas (Seed bank)', en:'Seed bank', de:'Samenbank', fr:'Banque de graines'}, def:{es:'Una colección organizada de semillas, con fines de conservación genética o comerciales.', en:'An organized collection of seeds, kept for genetic conservation or commercial purposes.', de:'Eine organisierte Sammlung von Samen zu Zwecken der genetischen Erhaltung oder für kommerzielle Zwecke.', fr:'Une collection organisée de graines, à des fins de conservation génétique ou commerciales.'}},
  {term:{es:'Beta-pineno', en:'Beta-pinene', de:'Beta-Pinen', fr:'Bêta-pinène'}, def:{es:'El segundo isómero del pineno, comparte gran parte del perfil de propiedades del alfa-pineno.', en:'The second pinene isomer, sharing much of alpha-pinene’s property profile.', de:'Das zweite Pinen-Isomer, das einen Großteil des Eigenschaftsprofils von Alpha-Pinen teilt.', fr:'Le second isomère du pinène, partageant une grande partie du profil de propriétés de l’alpha-pinène.'}},
  {term:{es:'BHO', en:'BHO', de:'BHO', fr:'BHO'}, def:{es:'Extracto de hidrocarburo hecho con butano.', en:'A hydrocarbon extract made with butane.', de:'Ein Kohlenwasserstoffextrakt, hergestellt mit Butan.', fr:'Extrait d’hydrocarbure fabriqué avec du butane.'}},
  {term:{es:'Bioacumulador', en:'Bioaccumulator', de:'Bioakkumulator', fr:'Bioaccumulateur'}, def:{es:'Un organismo (como el cannabis) que absorbe y concentra sustancias del ambiente donde crece.', en:'An organism (like cannabis) that absorbs and concentrates substances from the environment it grows in.', de:'Ein Organismus (wie Cannabis), der Substanzen aus seiner Wachstumsumgebung aufnimmt und konzentriert.', fr:'Un organisme (comme le cannabis) qui absorbe et concentre des substances de son environnement de culture.'}},
  {term:{es:'Bioseguridad', en:'Biosecurity', de:'Biosicherheit', fr:'Biosécurité'}, def:{es:'Prácticas y protocolos para prevenir la introducción y propagación de patógenos y plagas en una instalación.', en:'Practices and protocols to prevent the introduction and spread of pathogens and pests within a facility.', de:'Praktiken und Protokolle zur Verhinderung der Einschleppung und Ausbreitung von Krankheitserregern und Schädlingen in einer Anlage.', fr:'Pratiques et protocoles visant à prévenir l’introduction et la propagation de pathogènes et de nuisibles dans une installation.'}},
  {term:{es:'Bisabolol', en:'Bisabolol', de:'Bisabolol', fr:'Bisabolol'}, def:{es:'Aroma floral suave (también en manzanilla). Conocido por propiedades antiinflamatorias y calmantes para la piel — muy usado en tópicos.', en:'Mild floral aroma (also found in chamomile). Known for anti-inflammatory and skin-soothing properties — widely used in topicals.', de:'Mild-blumiges Aroma (auch in Kamille enthalten). Bekannt für entzündungshemmende und hautberuhigende Eigenschaften — häufig in Topika verwendet.', fr:'Arôme floral doux (également présent dans la camomille). Connu pour ses propriétés anti-inflammatoires et apaisantes pour la peau — très utilisé dans les topiques.'}},
  {term:{es:'Bloqueo de nutrientes (Nutrient lockout)', en:'Nutrient lockout', de:'Nährstoffblockade (Nutrient lockout)', fr:'Blocage nutritionnel (Nutrient lockout)'}, def:{es:'Cuando los nutrientes están presentes pero la planta no puede absorberlos — generalmente por pH fuera de rango, acumulación de sales, o desequilibrios entre nutrientes.', en:'When nutrients are present but the plant cannot absorb them — usually due to pH being out of range, salt buildup, or imbalances between nutrients.', de:'Wenn Nährstoffe vorhanden sind, die Pflanze sie aber nicht aufnehmen kann — meist aufgrund eines pH-Werts außerhalb des optimalen Bereichs, Salzansammlung oder Ungleichgewichten zwischen Nährstoffen.', fr:'Lorsque les nutriments sont présents mais que la plante ne peut pas les absorber — généralement à cause d’un pH hors plage, d’une accumulation de sels ou de déséquilibres entre nutriments.'}},
  {term:{es:'Boro (B)', en:'Boron (B)', de:'Bor (B)', fr:'Bore (B)'}, def:{es:'Micronutriente esencial para desarrollo de pared celular y transporte de azúcares.', en:'A micronutrient essential for cell wall development and sugar transport.', de:'Ein Mikronährstoff, der für die Zellwandentwicklung und den Zuckertransport essenziell ist.', fr:'Micronutriment essentiel au développement de la paroi cellulaire et au transport des sucres.'}},
  {term:{es:'Botrytis (Moho gris)', en:'Botrytis (Gray mold)', de:'Botrytis (Grauschimmel)', fr:'Botrytis (Moisissure grise)'}, def:{es:'Enfermedad fúngica que ataca el interior de flores densas donde la humedad queda atrapada — pudrición grisácea que avanza internamente antes de ser visible.', en:'A fungal disease that attacks the interior of dense flowers where moisture gets trapped — a grayish rot that progresses internally before becoming visible.', de:'Eine Pilzkrankheit, die das Innere dichter Blüten befällt, in denen sich Feuchtigkeit staut — eine gräuliche Fäulnis, die sich innen ausbreitet, bevor sie sichtbar wird.', fr:'Maladie fongique qui attaque l’intérieur des fleurs denses où l’humidité reste piégée — pourriture grisâtre qui progresse à l’intérieur avant de devenir visible.'}},
  {term:{es:'Bráctea', en:'Bract', de:'Braktee', fr:'Bractée'}, def:{es:'Hoja modificada y pequeña que rodea y protege la estructura floral. En cannabis suele confundirse con el cáliz por su cercanía visual, pero son estructuras distintas.', en:'A small, modified leaf that surrounds and protects the floral structure. In cannabis it’s often confused with the calyx due to their visual closeness, but they are distinct structures.', de:'Ein kleines, modifiziertes Blatt, das die Blütenstruktur umgibt und schützt. Bei Cannabis wird es wegen der visuellen Nähe oft mit dem Kelch verwechselt, obwohl es sich um unterschiedliche Strukturen handelt.', fr:'Feuille modifiée, petite, qui entoure et protège la structure florale. Chez le cannabis, on la confond souvent avec le calice en raison de leur proximité visuelle, bien que ce soient des structures distinctes.'}},
  {term:{es:'Broad spectrum', en:'Broad spectrum', de:'Broad Spectrum', fr:'Broad spectrum'}, def:{es:'Extracto que conserva la mayoría de los compuestos, pero sin THC.', en:'An extract that keeps most compounds, but without THC.', de:'Ein Extrakt, der die meisten Verbindungen bewahrt, aber ohne THC.', fr:'Extrait conservant la plupart des composés, mais sans THC.'}},
  {term:{es:'Bucking', en:'Bucking', de:'Bucking', fr:'Bucking'}, def:{es:'Remover las flores de las ramas y tallos principales, antes (bucking húmedo) o después (bucking seco) del secado.', en:'Removing the flowers from the branches and main stems, either before (wet bucking) or after (dry bucking) drying.', de:'Das Entfernen der Blüten von den Zweigen und Haupttrieben, entweder vor (Wet Bucking) oder nach (Dry Bucking) der Trocknung.', fr:'Retirer les fleurs des branches et des tiges principales, avant (bucking humide) ou après (bucking sec) le séchage.'}},
  {term:{es:'Burping', en:'Burping', de:'Burping (Lüften der Gläser)', fr:'Burping (aération des bocaux)'}, def:{es:'Abrir periódicamente los frascos de curado para liberar exceso de humedad y renovar el aire — reduce riesgo de moho.', en:'Periodically opening curing jars to release excess moisture and refresh the air — reduces mold risk.', de:'Das regelmäßige Öffnen der Reifungsgläser, um überschüssige Feuchtigkeit abzulassen und die Luft zu erneuern — verringert das Schimmelrisiko.', fr:'Ouvrir périodiquement les bocaux d’affinage pour libérer l’excès d’humidité et renouveler l’air — réduit le risque de moisissure.'}},
  {term:{es:'Búsqueda de fenotipos (Pheno hunting)', en:'Pheno hunting', de:'Pheno Hunting', fr:'Chasse aux phénotypes'}, def:{es:'Germinar muchas semillas de una misma cruza y evaluar sus fenotipos individuales para identificar los más deseables.', en:'Germinating many seeds from the same cross and evaluating their individual phenotypes to identify the most desirable ones.', de:'Das Keimen vieler Samen derselben Kreuzung und die Bewertung ihrer individuellen Phänotypen, um die begehrtesten zu identifizieren.', fr:'Faire germer de nombreuses graines issues d’un même croisement et évaluer leurs phénotypes individuels pour identifier les plus intéressants.'}},
  {term:{es:'Calcio (Ca)', en:'Calcium (Ca)', de:'Calcium (Ca)', fr:'Calcium (Ca)'}, def:{es:'Macronutriente secundario esencial para paredes celulares y tejidos nuevos — poca movilidad, afecta primero el crecimiento nuevo.', en:'A secondary macronutrient essential for cell walls and new tissue — has low mobility, affecting new growth first.', de:'Ein sekundärer Makronährstoff, der für Zellwände und neues Gewebe essenziell ist — er ist wenig mobil und betrifft zuerst das neue Wachstum.', fr:'Macronutriment secondaire essentiel aux parois cellulaires et aux nouveaux tissus — peu mobile, il affecte d’abord la nouvelle croissance.'}},
  {term:{es:'Cáliz', en:'Calyx', de:'Kelch', fr:'Calice'}, def:{es:'La estructura floral en forma de gota que rodea al óvulo — ahí se concentra la mayor densidad de tricomas y, por tanto, de cannabinoides y terpenos.', en:'The teardrop-shaped floral structure that surrounds the ovule — where the highest density of trichomes, and therefore cannabinoids and terpenes, is concentrated.', de:'Die tropfenförmige Blütenstruktur, die die Samenanlage umgibt — hier konzentriert sich die höchste Dichte an Trichomen und damit an Cannabinoiden und Terpenen.', fr:'La structure florale en forme de goutte qui entoure l’ovule — c’est là que se concentre la plus grande densité de trichomes, et donc de cannabinoïdes et de terpènes.'}},
  {term:{es:'Cáñamo vs. marihuana', en:'Hemp vs. marijuana', de:'Hanf vs. Marihuana', fr:'Chanvre vs. marijuana'}, def:{es:'Ambos son Cannabis sativa; la diferencia legal está en el contenido de THC, generalmente bajo un umbral como 0.3%.', en:'Both are Cannabis sativa; the legal difference is in THC content, usually under a threshold like 0.3%.', de:'Beide sind Cannabis sativa; der rechtliche Unterschied liegt im THC-Gehalt, meist unter einem Schwellenwert wie 0,3 %.', fr:'Les deux sont du Cannabis sativa ; la différence légale réside dans la teneur en THC, généralement sous un seuil comme 0,3 %.'}},
  {term:{es:'Cannabinoide', en:'Cannabinoid', de:'Cannabinoid', fr:'Cannabinoïde'}, def:{es:'Compuesto químico de la planta que interactúa con el sistema endocannabinoide del cuerpo.', en:'A chemical compound from the plant that interacts with the body’s endocannabinoid system.', de:'Eine chemische Verbindung der Pflanze, die mit dem körpereigenen Endocannabinoid-System interagiert.', fr:'Composé chimique de la plante qui interagit avec le système endocannabinoïde du corps.'}},
  {term:{es:'Cannabinoide sintético', en:'Synthetic cannabinoid', de:'Synthetisches Cannabinoid', fr:'Cannabinoïde de synthèse'}, def:{es:'Compuesto creado en laboratorio que imita la acción de cannabinoides naturales — desde fármacos aprobados (dronabinol) hasta sustancias peligrosas no reguladas (Spice/K2), con afinidad receptorial más fuerte e impredecible que el THC natural.', en:'A lab-created compound that mimics the action of natural cannabinoids — ranging from approved pharmaceuticals (dronabinol) to dangerous unregulated substances (Spice/K2), with stronger and less predictable receptor affinity than natural THC.', de:'Eine im Labor hergestellte Verbindung, die die Wirkung natürlicher Cannabinoide nachahmt — von zugelassenen Arzneimitteln (Dronabinol) bis zu gefährlichen, unregulierten Substanzen (Spice/K2), mit stärkerer und unvorhersehbarerer Rezeptoraffinität als natürliches THC.', fr:'Composé créé en laboratoire qui imite l’action des cannabinoïdes naturels — allant des médicaments approuvés (dronabinol) à des substances dangereuses non réglementées (Spice/K2), avec une affinité réceptorielle plus forte et moins prévisible que le THC naturel.'}},
  {term:{es:'Cannabis', en:'Cannabis', de:'Cannabis', fr:'Cannabis'}, def:{es:'Género botánico monotípico (una sola especie reconocida científicamente, Cannabis sativa L.) que incluye numerosas variedades cultivadas. Las divisiones "sativa/indica/ruderalis" son subespecies o clasificaciones informales, no especies separadas.', en:'A monotypic botanical genus (a single scientifically recognized species, Cannabis sativa L.) that includes numerous cultivated varieties. The "sativa/indica/ruderalis" divisions are subspecies or informal classifications, not separate species.', de:'Eine monotypische botanische Gattung (eine einzige wissenschaftlich anerkannte Art, Cannabis sativa L.), die zahlreiche Kultursorten umfasst. Die Einteilung "Sativa/Indica/Ruderalis" sind Unterarten bzw. informelle Klassifizierungen, keine eigenständigen Arten.', fr:'Genre botanique monotypique (une seule espèce reconnue scientifiquement, Cannabis sativa L.) comprenant de nombreuses variétés cultivées. Les divisions « sativa/indica/ruderalis » sont des sous-espèces ou des classifications informelles, pas des espèces distinctes.'}},
  {term:{es:'Cannabis artesanal (Craft cannabis)', en:'Craft cannabis', de:'Craft-Cannabis (handwerklich)', fr:'Cannabis artisanal (Craft cannabis)'}, def:{es:'Cultivo en pequeña escala con énfasis en calidad y técnica manual.', en:'Small-scale cultivation with an emphasis on quality and hands-on technique.', de:'Anbau im kleinen Maßstab mit Schwerpunkt auf Qualität und handwerklicher Technik.', fr:'Culture à petite échelle mettant l’accent sur la qualité et la technique manuelle.'}},
  {term:{es:'Capacidad de intercambio catiónico (CEC)', en:'Cation exchange capacity (CEC)', de:'Kationenaustauschkapazität (CEC)', fr:'Capacité d’échange cationique (CEC)'}, def:{es:'La capacidad de un sustrato para retener y liberar cationes (calcio, magnesio, potasio) — actúa como reserva de nutrientes.', en:'The capacity of a substrate to hold and release cations (calcium, magnesium, potassium) — it acts as a nutrient reserve.', de:'Die Fähigkeit eines Substrats, Kationen (Calcium, Magnesium, Kalium) zu binden und wieder abzugeben — es fungiert als Nährstoffreserve.', fr:'La capacité d’un substrat à retenir et libérer des cations (calcium, magnésium, potassium) — elle agit comme une réserve de nutriments.'}},
  {term:{es:'Cariofileno', en:'Caryophyllene', de:'Caryophyllen', fr:'Caryophyllène'}, def:{es:'El único terpeno confirmado en unirse directamente al receptor CB2, sin necesidad de descarboxilación — actúa casi como un cannabinoide.', en:'The only terpene confirmed to bind directly to the CB2 receptor, no decarboxylation needed — it behaves almost like a cannabinoid.', de:'Das einzige Terpen, das nachweislich direkt an den CB2-Rezeptor bindet, ohne Decarboxylierung nötig — es verhält sich fast wie ein Cannabinoid.', fr:'Le seul terpène confirmé se liant directement au récepteur CB2, sans décarboxylation nécessaire — il se comporte presque comme un cannabinoïde.'}},
  {term:{es:'Casa de sombra (Shade house)', en:'Shade house', de:'Schattenhaus', fr:'Ombrière (Shade house)'}, def:{es:'Estructura con malla que reduce intensidad de luz solar directa y protege del viento.', en:'A mesh-covered structure that reduces direct sunlight intensity and protects against wind.', de:'Eine mit Netzgewebe versehene Struktur, die die Intensität des direkten Sonnenlichts reduziert und vor Wind schützt.', fr:'Structure recouverte d’un filet qui réduit l’intensité de la lumière solaire directe et protège du vent.'}},
  {term:{es:'CB1 / CB2', en:'CB1 / CB2', de:'CB1 / CB2', fr:'CB1 / CB2'}, def:{es:'Los dos receptores principales del sistema endocannabinoide, en el cerebro y el sistema inmune respectivamente.', en:'The two main receptors of the endocannabinoid system, in the brain and the immune system respectively.', de:'Die beiden Hauptrezeptoren des Endocannabinoid-Systems, im Gehirn bzw. im Immunsystem.', fr:'Les deux principaux récepteurs du système endocannabinoïde, dans le cerveau et le système immunitaire respectivement.'}},
  {term:{es:'CBC (Cannabichromeno)', en:'CBC (Cannabichromene)', de:'CBC (Cannabichromen)', fr:'CBC (Cannabichromène)'}, def:{es:'Cannabinoide no psicoactivo que, a diferencia de la mayoría, no se une a los receptores CB1/CB2 — actúa vía canales TRP.', en:'Non-psychoactive cannabinoid that, unlike most others, does not bind to CB1/CB2 receptors — it acts via TRP channels.', de:'Nicht-psychoaktives Cannabinoid, das im Gegensatz zu den meisten anderen nicht an CB1/CB2-Rezeptoren bindet — es wirkt über TRP-Kanäle.', fr:'Cannabinoïde non psychoactif qui, contrairement à la plupart des autres, ne se lie pas aux récepteurs CB1/CB2 — il agit via les canaux TRP.'}},
  {term:{es:'CBCA (Ácido cannabicroménico)', en:'CBCA (Cannabichromenic acid)', de:'CBCA (Cannabichromensäure)', fr:'CBCA (Acide cannabichromique)'}, def:{es:'La forma ácida y no psicoactiva del CBC, sintetizada directamente desde CBGA por la enzima CBCA-sintasa.', en:'The acidic, non-psychoactive form of CBC, synthesized directly from CBGA by the CBCA synthase enzyme.', de:'Die saure, nicht-psychoaktive Form von CBC, die direkt aus CBGA durch das Enzym CBCA-Synthase synthetisiert wird.', fr:'La forme acide et non psychoactive du CBC, synthétisée directement à partir du CBGA par l’enzyme CBCA-synthase.'}},
  {term:{es:'CBD (Cannabidiol)', en:'CBD (Cannabidiol)', de:'CBD (Cannabidiol)', fr:'CBD (Cannabidiol)'}, def:{es:'Cannabinoide no psicoactivo, el segundo más abundante después del THC.', en:'Non-psychoactive cannabinoid, the second most abundant after THC.', de:'Nicht-psychoaktives Cannabinoid, das zweithäufigste nach THC.', fr:'Cannabinoïde non psychoactif, le deuxième plus abondant après le THC.'}},
  {term:{es:'CBDB (Cannabidibutol)', en:'CBDB (Cannabidibutol)', de:'CBDB (Cannabidibutol)', fr:'CBDB (Cannabidibutol)'}, def:{es:'Homólogo de CBD con cadena de 4 carbonos, intermedio entre CBDV (3) y CBD estándar (5). Descubierto por el mismo equipo italiano como impureza natural en extractos comerciales de CBD. Su análogo de THC es el THCB.', en:'A CBD homolog with a 4-carbon chain, intermediate between CBDV (3) and standard CBD (5). Discovered by the same Italian team as a natural impurity in commercial CBD extracts. Its THC analog is THCB.', de:'Ein CBD-Homolog mit einer 4-Kohlenstoff-Kette, das zwischen CBDV (3) und Standard-CBD (5) liegt. Vom selben italienischen Team als natürliche Verunreinigung in kommerziellen CBD-Extrakten entdeckt. Sein THC-Analog ist THCB.', fr:'Homologue du CBD à chaîne de 4 carbones, intermédiaire entre le CBDV (3) et le CBD standard (5). Découvert par la même équipe italienne comme impureté naturelle dans des extraits commerciaux de CBD. Son analogue en THC est le THCB.'}},
  {term:{es:'CBDP (Cannabidiforol)', en:'CBDP (Cannabidiphorol)', de:'CBDP (Cannabidiphorol)', fr:'CBDP (Cannabidiphorol)'}, def:{es:'El homólogo de CBD correspondiente al THCP, mismo estudio de 2019 — comparte la cadena de 7 carbonos, no psicoactivo, actividad biológica poco estudiada.', en:'The CBD homolog corresponding to THCP, from the same 2019 study — shares the 7-carbon chain, non-psychoactive, with poorly studied biological activity.', de:'Das CBD-Homolog, das dem THCP entspricht, aus derselben Studie von 2019 — teilt die 7-Kohlenstoff-Kette, nicht psychoaktiv, mit wenig erforschter biologischer Aktivität.', fr:'L’homologue du CBD correspondant au THCP, issu de la même étude de 2019 — partage la chaîne de 7 carbones, non psychoactif, activité biologique peu étudiée.'}},
  {term:{es:'CBDV (Cannabidivarín)', en:'CBDV (Cannabidivarin)', de:'CBDV (Cannabidivarin)', fr:'CBDV (Cannabidivarine)'}, def:{es:'Homólogo del CBD con cadena lateral más corta (propilo, 3 carbonos vs. 5 del CBD) — no psicoactivo, investigado por su potencial actividad anticonvulsivante.', en:'A CBD homolog with a shorter side chain (propyl, 3 carbons vs. CBD’s 5) — non-psychoactive, studied for its potential anticonvulsant activity.', de:'Ein CBD-Homolog mit kürzerer Seitenkette (Propyl, 3 Kohlenstoffatome gegenüber 5 bei CBD) — nicht psychoaktiv, untersucht wegen seiner potenziellen antikonvulsiven Wirkung.', fr:'Homologue du CBD à chaîne latérale plus courte (propyle, 3 carbones contre 5 pour le CBD) — non psychoactif, étudié pour son activité anticonvulsivante potentielle.'}},
  {term:{es:'CBE (Cannabielsoin)', en:'CBE (Cannabielsoin)', de:'CBE (Cannabielsoin)', fr:'CBE (Cannabielsoïne)'}, def:{es:'Se forma principalmente como producto de oxidación del CBD, no biosíntesis primaria de la planta — también identificado como metabolito menor en mamíferos. Estudios de 2024 sugieren que actúa como agonista sesgado del receptor CB1, aunque su farmacología sigue poco explorada.', en:'Forms mainly as an oxidation product of CBD, not through the plant’s primary biosynthesis — also identified as a minor metabolite in mammals. 2024 studies suggest it acts as a biased agonist at the CB1 receptor, though its pharmacology remains poorly explored.', de:'Entsteht hauptsächlich als Oxidationsprodukt von CBD, nicht durch die primäre Biosynthese der Pflanze — wurde auch als geringfügiger Metabolit bei Säugetieren identifiziert. Studien aus 2024 legen nahe, dass es als verzerrter (biased) Agonist am CB1-Rezeptor wirkt, obwohl seine Pharmakologie weiterhin wenig erforscht ist.', fr:'Se forme principalement comme produit d’oxydation du CBD, et non par biosynthèse primaire de la plante — également identifié comme métabolite mineur chez les mammifères. Des études de 2024 suggèrent qu’il agit comme agoniste biaisé du récepteur CB1, bien que sa pharmacologie reste peu explorée.'}},
  {term:{es:'CBG (Cannabigerol)', en:'CBG (Cannabigerol)', de:'CBG (Cannabigerol)', fr:'CBG (Cannabigérol)'}, def:{es:'Cannabinoide no psicoactivo, resultado de la decarboxilación del CBGA que no fue convertido en otros cannabinoides — el verdadero precursor bioquímico directo es el CBGA, no el CBG; el apodo "molécula madre" aplica más precisamente a ese ácido.', en:'A non-psychoactive cannabinoid, formed by the decarboxylation of CBGA that was not converted into other cannabinoids — the true direct biochemical precursor is CBGA, not CBG itself; the "mother molecule" nickname applies more precisely to that acid.', de:'Nicht-psychoaktives Cannabinoid, das durch Decarboxylierung von nicht umgewandeltem CBGA entsteht — die eigentliche direkte biochemische Vorstufe ist CBGA, nicht CBG selbst; der Beiname "Mutter-Molekül" trifft genauer auf diese Säure zu.', fr:'Cannabinoïde non psychoactif, formé par la décarboxylation du CBGA non converti en d’autres cannabinoïdes — le véritable précurseur biochimique direct est le CBGA, et non le CBG lui-même ; le surnom de « molécule mère » s’applique plus précisément à cet acide.'}},
  {term:{es:'CBGA (Ácido cannabigerólico)', en:'CBGA (Cannabigerolic acid)', de:'CBGA (Cannabigerolsäure)', fr:'CBGA (Acide cannabigérolique)'}, def:{es:'El verdadero precursor bioquímico central de la planta: las enzimas sintasas (THCA-sintasa, CBDA-sintasa, CBCA-sintasa) convierten el CBGA directamente en THCA, CBDA o CBCA, según la enzima presente. El CBGA no convertido se decarboxila a CBG con calor/luz/tiempo — por eso es escaso en plantas maduras y más abundante en floración temprana.', en:'The plant’s true central biochemical precursor: synthase enzymes (THCA synthase, CBDA synthase, CBCA synthase) convert CBGA directly into THCA, CBDA, or CBCA, depending on which enzyme is present. Unconverted CBGA decarboxylates into CBG with heat/light/time — which is why it’s scarce in mature plants and more abundant in early flowering.', de:'Die eigentliche zentrale biochemische Vorstufe der Pflanze: Synthase-Enzyme (THCA-Synthase, CBDA-Synthase, CBCA-Synthase) wandeln CBGA je nach vorhandenem Enzym direkt in THCA, CBDA oder CBCA um. Nicht umgewandeltes CBGA decarboxyliert durch Hitze/Licht/Zeit zu CBG — deshalb ist es in ausgereiften Pflanzen selten und in der frühen Blüte häufiger.', fr:'Le véritable précurseur biochimique central de la plante : les enzymes synthases (THCA-synthase, CBDA-synthase, CBCA-synthase) convertissent directement le CBGA en THCA, CBDA ou CBCA, selon l’enzyme présente. Le CBGA non converti se décarboxyle en CBG avec la chaleur/lumière/temps — d’où sa rareté dans les plantes matures et son abondance plus importante en début de floraison.'}},
  {term:{es:'CBN (Cannabinol)', en:'CBN (Cannabinol)', de:'CBN (Cannabinol)', fr:'CBN (Cannabinol)'}, def:{es:'Se forma cuando el THC se degrada con luz y oxígeno con el tiempo — leve psicoactividad, unas 10 veces menos potente que el THC.', en:'Forms when THC degrades from light and oxygen over time — mildly psychoactive, about 10 times less potent than THC.', de:'Entsteht, wenn THC im Laufe der Zeit durch Licht und Sauerstoff abgebaut wird — leicht psychoaktiv, etwa 10-mal schwächer als THC.', fr:'Se forme quand le THC se dégrade avec la lumière et l’oxygène au fil du temps — légèrement psychoactif, environ 10 fois moins puissant que le THC.'}},
  {term:{es:'CBNA (Ácido cannabinólico)', en:'CBNA (Cannabinolic acid)', de:'CBNA (Cannabinolsäure)', fr:'CBNA (Acide cannabinolique)'}, def:{es:'La forma ácida del CBN — a diferencia de otros ácidos (directos desde CBGA), se forma indirectamente: THCA se degrada con el tiempo hacia CBNA, que luego se decarboxila a CBN.', en:'The acidic form of CBN — unlike other acids (formed directly from CBGA), it forms indirectly: THCA degrades over time into CBNA, which then decarboxylates into CBN.', de:'Die saure Form von CBN — im Gegensatz zu anderen Säuren (die direkt aus CBGA entstehen), bildet sie sich indirekt: THCA baut sich mit der Zeit zu CBNA ab, das anschließend zu CBN decarboxyliert.', fr:'La forme acide du CBN — contrairement aux autres acides (formés directement à partir du CBGA), elle se forme indirectement : le THCA se dégrade avec le temps en CBNA, qui se décarboxyle ensuite en CBN.'}},
  {term:{es:'CBT (Cannabicitran)', en:'CBT (Cannabicitran)', de:'CBT (Cannabicitran)', fr:'CBT (Cannabicitran)'}, def:{es:'Existe ambigüedad real en la nomenclatura: algunas fuentes usan "CBT" como abreviatura general de cannabitriol (grupo de al menos 9 cannabinoides relacionados, formados por oxidación del THC), mientras que "cannabicitran" técnicamente es solo uno de esos compuestos específicos (a veces escrito CBT-C). En la práctica comercial ambos se usan indistintamente, sin ser estrictamente sinónimos exactos. No psicoactivo, sin unión significativa a CB1 — se le atribuye posible capacidad de atenuar parcialmente efectos del THC al competir por el receptor, aunque esto necesita más estudio.', en:'There is real ambiguity in the nomenclature: some sources use "CBT" as a general abbreviation for cannabitriol (a group of at least 9 related cannabinoids formed by THC oxidation), while "cannabicitran" technically refers to just one of those specific compounds (sometimes written CBT-C). In commercial practice both are used interchangeably, without being strictly exact synonyms. Non-psychoactive, with no significant CB1 binding — it is credited with a possible ability to partially blunt THC’s effects by competing for the receptor, though this needs further study.', de:'Es besteht eine reale Uneindeutigkeit in der Nomenklatur: Manche Quellen verwenden "CBT" als allgemeine Abkürzung für Cannabitriol (eine Gruppe von mindestens 9 verwandten Cannabinoiden, die durch Oxidation von THC entstehen), während "Cannabicitran" technisch nur eine dieser spezifischen Verbindungen bezeichnet (manchmal als CBT-C geschrieben). In der kommerziellen Praxis werden beide Begriffe synonym verwendet, ohne exakte Synonyme im strengen Sinne zu sein. Nicht psychoaktiv, ohne signifikante CB1-Bindung — es wird ihm eine mögliche Fähigkeit zugeschrieben, die Wirkungen von THC durch Konkurrenz um den Rezeptor teilweise abzuschwächen, was jedoch weiterer Forschung bedarf.', fr:'Il existe une réelle ambiguïté dans la nomenclature : certaines sources utilisent « CBT » comme abréviation générale du cannabitriol (groupe d’au moins 9 cannabinoïdes apparentés, formés par oxydation du THC), tandis que « cannabicitran » désigne techniquement un seul de ces composés spécifiques (parfois noté CBT-C). Dans la pratique commerciale, les deux sont utilisés indifféremment, sans être des synonymes strictement exacts. Non psychoactif, sans liaison significative au CB1 — on lui attribue une capacité possible à atténuer partiellement les effets du THC en entrant en compétition pour le récepteur, bien que cela nécessite davantage d’études.'}},
  {term:{es:'CEA (Agricultura de Ambiente Controlado)', en:'CEA (Controlled Environment Agriculture)', de:'CEA (Landwirtschaft mit kontrollierter Umgebung)', fr:'CEA (Agriculture en environnement contrôlé)'}, def:{es:'Sistema de producción donde se controlan activamente las variables ambientales, independientemente del clima externo.', en:'A production system in which environmental variables are actively controlled, independent of outside weather.', de:'Ein Produktionssystem, bei dem Umweltvariablen aktiv gesteuert werden, unabhängig vom Außenklima.', fr:'Système de production dans lequel les variables environnementales sont contrôlées activement, indépendamment du climat extérieur.'}},
  {term:{es:'Cepa (Strain)', en:'Strain', de:'Strain', fr:'Strain'}, def:{es:'Término tomado de la microbiología, adoptado coloquialmente en la industria del cannabis para referirse a una variedad específica. Científicamente es impreciso: "cultivar" es el término botánico correcto.', en:'A term borrowed from microbiology, adopted colloquially in the cannabis industry to refer to a specific variety. Scientifically imprecise — "cultivar" is the correct botanical term.', de:'Ein aus der Mikrobiologie entlehnter Begriff, der in der Cannabisbranche umgangssprachlich für eine bestimmte Sorte verwendet wird. Wissenschaftlich ungenau — "Kultivar" ist der korrekte botanische Begriff.', fr:'Terme emprunté à la microbiologie, adopté familièrement dans l’industrie du cannabis pour désigner une variété spécifique. Scientifiquement imprécis — « cultivar » est le terme botanique correct.'}},
  {term:{es:'Cepellón (Root ball)', en:'Root ball', de:'Wurzelballen', fr:'Motte racinaire'}, def:{es:'La masa formada por las raíces junto con el sustrato que las rodea, tal como se extrae al trasplantar.', en:'The mass formed by the roots together with the surrounding substrate, as it comes out when transplanting.', de:'Die Masse aus Wurzeln und dem sie umgebenden Substrat, so wie sie beim Umtopfen herauskommt.', fr:'La masse formée par les racines et le substrat qui les entoure, telle qu’elle est extraite lors du repiquage.'}},
  {term:{es:'Ciclo de luz', en:'Light cycle', de:'Lichtzyklus', fr:'Cycle de lumière'}, def:{es:'La proporción de horas de luz/oscuridad en 24 horas — el mecanismo práctico del fotoperiodo.', en:'The ratio of light/dark hours within 24 hours — the practical mechanism behind the photoperiod.', de:'Das Verhältnis von Licht-/Dunkelstunden innerhalb von 24 Stunden — der praktische Mechanismus hinter der Photoperiode.', fr:'Le rapport entre les heures de lumière et d’obscurité sur 24 heures — le mécanisme pratique de la photopériode.'}},
  {term:{es:'Circulación de aire', en:'Air circulation', de:'Luftzirkulation', fr:'Circulation d’air'}, def:{es:'El movimiento del aire dentro del espacio (vía ventiladores internos), sin necesariamente intercambiarlo con el exterior.', en:'The movement of air within the space (via internal fans), without necessarily exchanging it with the outside.', de:'Die Bewegung der Luft innerhalb des Raums (mittels interner Ventilatoren), ohne dass sie notwendigerweise mit der Außenluft ausgetauscht wird.', fr:'Le mouvement de l’air à l’intérieur de l’espace (via des ventilateurs internes), sans nécessairement l’échanger avec l’extérieur.'}},
  {term:{es:'Citoquinina', en:'Cytokinin', de:'Cytokinin', fr:'Cytokinine'}, def:{es:'Hormona vegetal que promueve la división celular y el crecimiento de brotes laterales — actúa en balance opuesto a la auxina.', en:'A plant hormone that promotes cell division and lateral shoot growth — it works in balance opposite to auxin.', de:'Ein Pflanzenhormon, das die Zellteilung und das Wachstum seitlicher Triebe fördert — es wirkt im Gegengewicht zum Auxin.', fr:'Hormone végétale qui favorise la division cellulaire et la croissance des pousses latérales — elle agit en équilibre opposé à l’auxine.'}},
  {term:{es:'Clon', en:'Clone', de:'Klon', fr:'Clone'}, def:{es:'Planta genéticamente idéntica a su planta madre, producida por propagación vegetativa (asexual), no por semilla.', en:'A plant genetically identical to its mother plant, produced through vegetative (asexual) propagation, not from seed.', de:'Eine Pflanze, die genetisch identisch mit ihrer Mutterpflanze ist und durch vegetative (ungeschlechtliche) Vermehrung entstanden ist, nicht aus Samen.', fr:'Plante génétiquement identique à sa plante mère, produite par propagation végétative (asexuée), et non par graine.'}},
  {term:{es:'Clon élite (Elite clone)', en:'Elite clone', de:'Elite-Klon', fr:'Clone d’élite'}, def:{es:'Un clon de un fenotipo excepcional que se distribuye por sus cualidades comprobadas.', en:'A clone of an exceptional phenotype that gets distributed for its proven qualities.', de:'Ein Klon eines außergewöhnlichen Phänotyps, der wegen seiner nachgewiesenen Qualitäten verbreitet wird.', fr:'Clone d’un phénotype exceptionnel, distribué pour ses qualités éprouvées.'}},
  {term:{es:'CMH (Halogenuro metálico cerámico)', en:'CMH (Ceramic Metal Halide)', de:'CMH (Keramik-Halogen-Metalldampflampe)', fr:'CMH (Halogénure métallique céramique)'}, def:{es:'Evolución del MH con tubo de arco cerámico, espectro más completo y estable, mayor eficiencia.', en:'An evolution of MH with a ceramic arc tube, a more complete and stable spectrum, and higher efficiency.', de:'Eine Weiterentwicklung des MH mit Keramik-Brennerrohr, vollständigerem und stabilerem Spektrum sowie höherer Effizienz.', fr:'Évolution du MH avec tube à arc céramique, spectre plus complet et stable, meilleure efficacité.'}},
  {term:{es:'COA (Certificado de Análisis)', en:'COA (Certificate of Analysis)', de:'COA (Analysezertifikat)', fr:'COA (Certificat d’Analyse)'}, def:{es:'El informe de un laboratorio independiente que confirma potencia y ausencia de contaminantes.', en:'The report from an independent lab confirming potency and the absence of contaminants.', de:'Der Bericht eines unabhängigen Labors, der Potenz und die Abwesenheit von Kontaminanten bestätigt.', fr:'Le rapport d’un laboratoire indépendant confirmant la puissance et l’absence de contaminants.'}},
  {term:{es:'Cobre (Cu)', en:'Copper (Cu)', de:'Kupfer (Cu)', fr:'Cuivre (Cu)'}, def:{es:'Micronutriente involucrado en procesos enzimáticos y síntesis de lignina.', en:'A micronutrient involved in enzymatic processes and lignin synthesis.', de:'Ein Mikronährstoff, der an enzymatischen Prozessen und der Ligninsynthese beteiligt ist.', fr:'Micronutriment impliqué dans les processus enzymatiques et la synthèse de la lignine.'}},
  {term:{es:'Cola', en:'Cola', de:'Cola', fr:'Cola'}, def:{es:'Agrupación de múltiples flores pequeñas fusionadas a lo largo de una rama, formando una estructura floral alargada y densa.', en:'A cluster of multiple small flowers fused along a branch, forming an elongated, dense floral structure.', de:'Eine Gruppierung mehrerer kleiner, entlang eines Astes verschmolzener Blüten, die eine längliche, dichte Blütenstruktur bildet.', fr:'Regroupement de plusieurs petites fleurs fusionnées le long d’une branche, formant une structure florale allongée et dense.'}},
  {term:{es:'Concentración de CO2 (ppm)', en:'CO2 concentration (ppm)', de:'CO2-Konzentration (ppm)', fr:'Concentration de CO2 (ppm)'}, def:{es:'La cantidad de CO2 en el aire — niveles por encima de ~1500-2000 ppm pueden ser contraproducentes o peligrosos para las personas.', en:'The amount of CO2 in the air — levels above ~1500-2000 ppm can be counterproductive or dangerous for people.', de:'Die CO2-Menge in der Luft — Werte über ~1500-2000 ppm können kontraproduktiv oder für Menschen gefährlich sein.', fr:'La quantité de CO2 dans l’air — des niveaux supérieurs à ~1500-2000 ppm peuvent être contre-productifs ou dangereux pour les personnes.'}},
  {term:{es:'Conductividad eléctrica (EC)', en:'Electrical conductivity (EC)', de:'Elektrische Leitfähigkeit (EC)', fr:'Conductivité électrique (EC)'}, def:{es:'Medida de la concentración total de sales en una solución, en mS/cm — el estándar más usado para dosificar fertirriego.', en:'A measure of the total salt concentration in a solution, in mS/cm — the most widely used standard for dosing fertigation.', de:'Ein Maß für die gesamte Salzkonzentration in einer Lösung, in mS/cm — der am häufigsten verwendete Standard zur Dosierung der Fertigation.', fr:'Mesure de la concentration totale en sels d’une solution, en mS/cm — la norme la plus utilisée pour doser la fertirrigation.'}},
  {term:{es:'Conservación genética', en:'Genetic conservation', de:'Genetische Erhaltung', fr:'Conservation génétique'}, def:{es:'Prácticas dirigidas a preservar material genético a largo plazo.', en:'Practices aimed at preserving genetic material over the long term.', de:'Praktiken, die darauf abzielen, genetisches Material langfristig zu erhalten.', fr:'Pratiques visant à préserver du matériel génétique à long terme.'}},
  {term:{es:'Contaminación', en:'Contamination', de:'Kontamination', fr:'Contamination'}, def:{es:'Presencia no deseada de cualquier agente biológico, químico o físico que compromete la seguridad o calidad del cultivo/producto.', en:'The unwanted presence of any biological, chemical, or physical agent that compromises the safety or quality of the crop/product.', de:'Das unerwünschte Vorhandensein eines biologischen, chemischen oder physikalischen Agens, das die Sicherheit oder Qualität der Kultur/des Produkts beeinträchtigt.', fr:'Présence indésirable de tout agent biologique, chimique ou physique compromettant la sécurité ou la qualité de la culture/du produit.'}},
  {term:{es:'Contaminación cruzada', en:'Cross-contamination', de:'Kreuzkontamination', fr:'Contamination croisée'}, def:{es:'La transferencia no intencional de contaminantes de una fuente a otra, vía herramientas, manos o equipo compartido.', en:'The unintentional transfer of contaminants from one source to another, via tools, hands, or shared equipment.', de:'Die unbeabsichtigte Übertragung von Kontaminanten von einer Quelle auf eine andere, über Werkzeuge, Hände oder gemeinsam genutzte Ausrüstung.', fr:'Transfert involontaire de contaminants d’une source à une autre, via des outils, des mains ou du matériel partagé.'}},
  {term:{es:'Contenido de humedad (Moisture content)', en:'Moisture content', de:'Feuchtigkeitsgehalt (Moisture content)', fr:'Teneur en humidité (Moisture content)'}, def:{es:'El porcentaje de agua en la flor seca — rango objetivo típico post-secado: 10-15%.', en:'The percentage of water in dried flower — typical target range post-drying: 10-15%.', de:'Der Wasseranteil in der getrockneten Blüte — typischer Zielbereich nach der Trocknung: 10-15%.', fr:'Le pourcentage d’eau dans la fleur séchée — plage cible typique après séchage : 10-15 %.'}},
  {term:{es:'Control biológico', en:'Biological control', de:'Biologische Bekämpfung', fr:'Lutte biologique'}, def:{es:'Uso de organismos vivos (depredadores, parasitoides, patógenos de insectos) para reducir plagas, en vez de químicos sintéticos.', en:'The use of living organisms (predators, parasitoids, insect pathogens) to reduce pests, instead of synthetic chemicals.', de:'Der Einsatz lebender Organismen (Räuber, Parasitoide, Insektenpathogene) zur Schädlingsreduzierung anstelle synthetischer Chemikalien.', fr:'Utilisation d’organismes vivants (prédateurs, parasitoïdes, pathogènes d’insectes) pour réduire les nuisibles, à la place de produits chimiques de synthèse.'}},
  {term:{es:'Control climático', en:'Climate control', de:'Klimasteuerung', fr:'Contrôle climatique'}, def:{es:'Término general para sistemas y prácticas que mantienen las condiciones ambientales dentro de rangos deseados.', en:'A general term for systems and practices that keep environmental conditions within desired ranges.', de:'Ein allgemeiner Begriff für Systeme und Praktiken, die Umweltbedingungen innerhalb gewünschter Bereiche halten.', fr:'Terme général désignant les systèmes et pratiques qui maintiennent les conditions environnementales dans des plages souhaitées.'}},
  {term:{es:'Controlador ambiental', en:'Environmental controller', de:'Umweltcontroller', fr:'Contrôleur environnemental'}, def:{es:'Dispositivo que integra sensores y actuadores para automatizar el ajuste de temperatura, humedad, CO2 e iluminación.', en:'A device that integrates sensors and actuators to automate the adjustment of temperature, humidity, CO2, and lighting.', de:'Ein Gerät, das Sensoren und Aktoren integriert, um die Anpassung von Temperatur, Luftfeuchtigkeit, CO2 und Beleuchtung zu automatisieren.', fr:'Dispositif intégrant capteurs et actionneurs pour automatiser l’ajustement de la température, de l’humidité, du CO2 et de l’éclairage.'}},
  {term:{es:'Corte apical (Topping)', en:'Topping', de:'Topping (Spitzenschnitt)', fr:'Topping (étêtage)'}, def:{es:'Técnica de alto estrés (HST) que corta la punta de crecimiento principal, eliminando la dominancia apical y estimulando dos o más ramas nuevas.', en:'A high-stress training (HST) technique that cuts off the main growth tip, removing apical dominance and stimulating two or more new branches.', de:'Eine High-Stress-Training-Technik (HST), bei der die Haupttriebspitze abgeschnitten wird, wodurch die apikale Dominanz aufgehoben wird und zwei oder mehr neue Zweige angeregt werden.', fr:'Technique d’entraînement à haut stress (HST) qui coupe la pointe de croissance principale, supprimant la dominance apicale et stimulant deux branches nouvelles ou plus.'}},
  {term:{es:'Cosecha (Harvest)', en:'Harvest', de:'Ernte', fr:'Récolte'}, def:{es:'El momento y proceso de cortar/recolectar las plantas o flores cuando alcanzan su punto óptimo de madurez.', en:'The moment and process of cutting/collecting the plants or flowers when they reach their optimal point of maturity.', de:'Der Zeitpunkt und Prozess des Schneidens/Sammelns der Pflanzen oder Blüten, wenn sie ihren optimalen Reifepunkt erreichen.', fr:'Le moment et le processus de couper/récolter les plantes ou les fleurs lorsqu’elles atteignent leur point optimal de maturité.'}},
  {term:{es:'Cosecha húmeda (Wet harvest)', en:'Wet harvest', de:'Nassernte (Wet harvest)', fr:'Récolte humide (Wet harvest)'}, def:{es:'El estado de la planta inmediatamente después de cortarla, antes de cualquier secado.', en:'The state of the plant immediately after cutting it, before any drying.', de:'Der Zustand der Pflanze unmittelbar nach dem Schneiden, vor jeglicher Trocknung.', fr:'L’état de la plante immédiatement après la coupe, avant tout séchage.'}},
  {term:{es:'Cosechar (Harvesting)', en:'Harvesting', de:'Ernten', fr:'Récolter'}, def:{es:'El acto de realizar la cosecha.', en:'The act of carrying out the harvest.', de:'Die Handlung, die Ernte durchzuführen.', fr:'L’acte de réaliser la récolte.'}},
  {term:{es:'Criador (Breeder)', en:'Breeder', de:'Züchter', fr:'Sélectionneur'}, def:{es:'La persona que realiza el trabajo de mejoramiento genético — selecciona plantas parentales, ejecuta cruces y estabiliza nuevas variedades.', en:'The person who does the breeding work — selects parent plants, performs crosses, and stabilizes new varieties.', de:'Die Person, die die Züchtungsarbeit durchführt — wählt Elternpflanzen aus, führt Kreuzungen durch und stabilisiert neue Sorten.', fr:'La personne qui réalise le travail de sélection — choisit les plantes parentales, effectue les croisements et stabilise de nouvelles variétés.'}},
  {term:{es:'Cruce (Cross)', en:'Cross', de:'Kreuzung', fr:'Croisement'}, def:{es:'El apareamiento controlado entre dos plantas parentales genéticamente distintas.', en:'The controlled mating between two genetically distinct parent plants.', de:'Die kontrollierte Paarung zweier genetisch unterschiedlicher Elternpflanzen.', fr:'L’accouplement contrôlé entre deux plantes parentales génétiquement distinctes.'}},
  {term:{es:'Cruzamiento externo (Outcrossing)', en:'Outcrossing', de:'Auskreuzung', fr:'Croisement extérieur'}, def:{es:'Cruce entre plantas genéticamente no emparentadas — introduce diversidad genética nueva.', en:'A cross between genetically unrelated plants — introduces new genetic diversity.', de:'Eine Kreuzung zwischen genetisch nicht verwandten Pflanzen — führt neue genetische Vielfalt ein.', fr:'Croisement entre plantes génétiquement non apparentées — introduit une nouvelle diversité génétique.'}},
  {term:{es:'Cuarentena', en:'Quarantine', de:'Quarantäne', fr:'Quarantaine'}, def:{es:'Aislamiento temporal de material vegetal nuevo, durante un período de observación, para detectar plagas o enfermedades antes de introducirlo al resto del cultivo.', en:'Temporary isolation of new plant material during an observation period, to detect pests or diseases before introducing it to the rest of the crop.', de:'Vorübergehende Isolierung neuen Pflanzenmaterials während einer Beobachtungsphase, um Schädlinge oder Krankheiten zu erkennen, bevor es in den übrigen Bestand eingeführt wird.', fr:'Isolement temporaire d’un nouveau matériel végétal pendant une période d’observation, afin de détecter des nuisibles ou des maladies avant de l’introduire dans le reste de la culture.'}},
  {term:{es:'Cultivado bajo sol (Sun-grown)', en:'Sun-grown', de:'Sonnengewachsen', fr:'Cultivé au soleil (Sun-grown)'}, def:{es:'Cultivo exclusivamente con luz solar natural, sin suplementación artificial.', en:'Cultivation using exclusively natural sunlight, with no artificial supplementation.', de:'Anbau ausschließlich mit natürlichem Sonnenlicht, ohne künstliche Zusatzbeleuchtung.', fr:'Culture utilisant exclusivement la lumière solaire naturelle, sans supplémentation artificielle.'}},
  {term:{es:'Cultivar', en:'Cultivar', de:'Kultivar', fr:'Cultivar'}, def:{es:'Una variedad desarrollada intencionalmente por un breeder mediante cruces.', en:'A variety intentionally developed by a breeder through crossing.', de:'Eine Sorte, die absichtlich von einem Züchter durch Kreuzung entwickelt wurde.', fr:'Une variété développée intentionnellement par un breeder par croisement.'}},
  {term:{es:'Cultivar mantenido mediante clones (Clone-only cultivar)', en:'Clone-only cultivar', de:'Nur-Klon-Kultivar', fr:'Cultivar maintenu par clonage'}, def:{es:'Una variedad preservada exclusivamente por clonación, porque por semilla no garantizaría las mismas características.', en:'A variety preserved exclusively through cloning, because growing it from seed would not guarantee the same characteristics.', de:'Eine Sorte, die ausschließlich durch Klonen erhalten wird, weil eine Vermehrung aus Samen dieselben Eigenschaften nicht garantieren würde.', fr:'Une variété préservée exclusivement par clonage, car sa reproduction par graine ne garantirait pas les mêmes caractéristiques.'}},
  {term:{es:'Cultivo a gran escala (Large-scale cultivation)', en:'Large-scale cultivation', de:'Großflächiger Anbau', fr:'Culture à grande échelle'}, def:{es:'Operación de alto volumen, con automatización y estructura industrial.', en:'A high-volume operation, with automation and industrial structure.', de:'Ein Betrieb mit hohem Volumen, Automatisierung und industrieller Struktur.', fr:'Opération à fort volume, avec automatisation et structure industrielle.'}},
  {term:{es:'Cultivo comercial (Commercial cultivation)', en:'Commercial cultivation', de:'Kommerzieller Anbau', fr:'Culture commerciale'}, def:{es:'Operación orientada a producción y venta a escala de negocio.', en:'An operation oriented toward production and sale at a business scale.', de:'Ein auf Produktion und Verkauf im geschäftlichen Maßstab ausgerichteter Betrieb.', fr:'Opération orientée vers la production et la vente à l’échelle d’une entreprise.'}},
  {term:{es:'Cultivo de meristemos (Meristem culture)', en:'Meristem culture', de:'Meristemkultur', fr:'Culture de méristèmes'}, def:{es:'Variante del cultivo de tejidos usando tejido de crecimiento activo — se usa comúnmente para "limpiar" genética de virus/viroides como HLVd, ya que ese tejido suele tener baja o nula concentración viral.', en:'A variant of tissue culture that uses actively growing tissue — commonly used to "clean" genetics of viruses/viroids like HLVd, since that tissue usually has low or no viral concentration.', de:'Eine Variante der Gewebekultur, die aktiv wachsendes Gewebe verwendet — wird häufig eingesetzt, um Genetik von Viren/Viroiden wie HLVd zu "reinigen", da dieses Gewebe meist eine geringe oder keine virale Konzentration aufweist.', fr:'Variante de la culture de tissus utilisant du tissu en croissance active — couramment utilisée pour « nettoyer » la génétique de virus/viroïdes comme le HLVd, ce tissu ayant généralement une concentration virale faible ou nulle.'}},
  {term:{es:'Cultivo de tejidos (Tissue culture)', en:'Tissue culture', de:'Gewebekultur', fr:'Culture de tissus'}, def:{es:'Técnica de laboratorio para propagar plantas desde fragmentos de tejido en medio estéril, con menor riesgo de patógenos.', en:'A laboratory technique for propagating plants from tissue fragments in a sterile medium, with lower risk of pathogens.', de:'Eine Labortechnik zur Vermehrung von Pflanzen aus Gewebefragmenten in sterilem Nährmedium, mit geringerem Krankheitserregerrisiko.', fr:'Technique de laboratoire consistant à propager des plantes à partir de fragments de tissu sur milieu stérile, avec un risque réduit de pathogènes.'}},
  {term:{es:'Cultivo en agua profunda (DWC)', en:'Deep Water Culture (DWC)', de:'Deep Water Culture (DWC)', fr:'Culture en eau profonde (DWC)'}, def:{es:'Sistema hidropónico donde las raíces de la planta permanecen suspendidas y sumergidas directamente en una solución nutritiva oxigenada (mediante una bomba de aire), sin sustrato sólido.', en:'A hydroponic system where the plant’s roots hang suspended and submerged directly in an oxygenated nutrient solution (via an air pump), with no solid substrate.', de:'Ein hydroponisches System, bei dem die Pflanzenwurzeln direkt in einer sauerstoffangereicherten Nährlösung (mittels einer Luftpumpe) hängen und untergetaucht sind, ohne festes Substrat.', fr:'Système hydroponique dans lequel les racines de la plante restent suspendues et immergées directement dans une solution nutritive oxygénée (via une pompe à air), sans substrat solide.'}},
  {term:{es:'Cultivo en almacén (Warehouse cultivation)', en:'Warehouse cultivation', de:'Anbau in Lagerhallen', fr:'Culture en entrepôt'}, def:{es:'Cultivo indoor a gran escala dentro de naves industriales reacondicionadas.', en:'Large-scale indoor cultivation inside repurposed industrial buildings.', de:'Großflächiger Indoor-Anbau in umgebauten Industriehallen.', fr:'Culture en intérieur à grande échelle dans des bâtiments industriels réaménagés.'}},
  {term:{es:'Curado', en:'Curing', de:'Reifung', fr:'Affinage'}, def:{es:'El proceso de maduración lenta después del secado, que mejora sabor y suavidad.', en:'The slow maturation process after drying, which improves flavor and smoothness.', de:'Der langsame Reifungsprozess nach dem Trocknen, der Geschmack und Milde verbessert.', fr:'Le processus de maturation lente après le séchage, qui améliore la saveur et la douceur.'}},
  {term:{es:'Curado en frasco (Jar cure)', en:'Jar cure', de:'Glasreifung (Jar cure)', fr:'Affinage en bocal (Jar cure)'}, def:{es:'La flor seca se almacena en recipientes herméticos, permitiendo que la humedad interna se equilibre lentamente.', en:'Dry flower is stored in airtight containers, allowing internal moisture to equalize slowly.', de:'Die getrocknete Blüte wird in luftdichten Behältern gelagert, sodass sich die innere Feuchtigkeit langsam ausgleichen kann.', fr:'La fleur sèche est stockée dans des récipients hermétiques, permettant à l’humidité interne de s’équilibrer lentement.'}},
  {term:{es:'Decarboxilación', en:'Decarboxylation', de:'Decarboxylierung', fr:'Décarboxylation'}, def:{es:'El proceso con calor que convierte THCA/CBDA en THC/CBD activos.', en:'The heat process that converts THCA/CBDA into active THC/CBD.', de:'Der Hitzeprozess, der THCA/CBDA in aktives THC/CBD umwandelt.', fr:'Le procédé thermique qui convertit le THCA/CBDA en THC/CBD actifs.'}},
  {term:{es:'Deficiencia', en:'Deficiency', de:'Mangel (Nährstoffmangel)', fr:'Carence'}, def:{es:'Cuando la planta no dispone de suficiente cantidad de un nutriente específico, con síntomas visuales característicos.', en:'When a plant does not have enough of a specific nutrient available, producing characteristic visual symptoms.', de:'Wenn einer Pflanze nicht genügend eines bestimmten Nährstoffs zur Verfügung steht, mit charakteristischen sichtbaren Symptomen.', fr:'Lorsque la plante ne dispose pas d’une quantité suffisante d’un nutriment spécifique, avec des symptômes visuels caractéristiques.'}},
  {term:{es:'Defoliación', en:'Defoliation', de:'Defoliation (Entlaubung)', fr:'Défoliation'}, def:{es:'Remover selectivamente hojas abanico para mejorar penetración de luz y circulación de aire dentro del dosel.', en:'Selectively removing fan leaves to improve light penetration and air circulation within the canopy.', de:'Das selektive Entfernen von Fächerblättern, um die Lichtdurchdringung und Luftzirkulation innerhalb des Blätterdachs zu verbessern.', fr:'Retirer sélectivement les feuilles en éventail pour améliorer la pénétration de la lumière et la circulation de l’air dans la canopée.'}},
  {term:{es:'Δ8-THC (Delta-8-THC)', en:'Δ8-THC (Delta-8-THC)', de:'Δ8-THC (Delta-8-THC)', fr:'Δ8-THC (Delta-8-THC)'}, def:{es:'Isómero presente naturalmente solo en trazas — la mayoría disponible comercialmente se produce sintéticamente desde CBD de cáñamo, generando controversia regulatoria por operar en un vacío legal. Generalmente menos potente que el Δ9-THC.', en:'An isomer naturally present only in trace amounts — most of what’s commercially available is synthetically produced from hemp-derived CBD, generating regulatory controversy for operating in a legal gray area. Generally less potent than Δ9-THC.', de:'Ein Isomer, das natürlich nur in Spuren vorkommt — das meiste kommerziell erhältliche Produkt wird synthetisch aus hanfbasiertem CBD hergestellt, was aufgrund seiner Existenz in einer rechtlichen Grauzone regulatorische Kontroversen auslöst. In der Regel weniger potent als Δ9-THC.', fr:'Isomère présent naturellement seulement à l’état de traces — la majeure partie de ce qui est disponible dans le commerce est produite synthétiquement à partir de CBD issu du chanvre, générant une controverse réglementaire du fait d’opérer dans un vide juridique. Généralement moins puissant que le Δ9-THC.'}},
  {term:{es:'Δ9-THC (Delta-9-THC)', en:'Δ9-THC (Delta-9-THC)', de:'Δ9-THC (Delta-9-THC)', fr:'Δ9-THC (Delta-9-THC)'}, def:{es:'El isómero responsable de la mayoría de los efectos psicoactivos — cuando se habla de "THC" sin especificar, generalmente se refiere a esta forma, la más abundante en la planta.', en:'The isomer responsible for most psychoactive effects — when "THC" is mentioned without specifying, it generally refers to this form, the most abundant in the plant.', de:'Das Isomer, das für die meisten psychoaktiven Wirkungen verantwortlich ist — wenn ohne nähere Angabe von "THC" die Rede ist, ist in der Regel diese Form gemeint, die in der Pflanze am häufigsten vorkommt.', fr:'L’isomère responsable de la plupart des effets psychoactifs — lorsqu’on parle de « THC » sans préciser, il s’agit généralement de cette forme, la plus abondante dans la plante.'}},
  {term:{es:'Δ10-THC (Delta-10-THC)', en:'Δ10-THC (Delta-10-THC)', de:'Δ10-THC (Delta-10-THC)', fr:'Δ10-THC (Delta-10-THC)'}, def:{es:'Isómero aún menos abundante que el Δ8, también mayormente sintético — perfil de efectos y estatus regulatorio menos estudiados.', en:'An isomer even less abundant than Δ8, also mostly synthetic — its effect profile and regulatory status are less studied.', de:'Ein Isomer, das noch seltener vorkommt als Δ8 und ebenfalls größtenteils synthetisch ist — Wirkprofil und regulatorischer Status sind weniger erforscht.', fr:'Isomère encore moins abondant que le Δ8, également majoritairement synthétique — profil d’effets et statut réglementaire moins étudiés.'}},
  {term:{es:'Depredador', en:'Predator', de:'Räuber (Prädator)', fr:'Prédateur'}, def:{es:'Organismo que caza y consume activamente a otros organismos como parte de su ciclo de vida normal.', en:'An organism that actively hunts and consumes other organisms as part of its normal life cycle.', de:'Ein Organismus, der aktiv andere Organismen jagt und verzehrt, als normalen Teil seines Lebenszyklus.', fr:'Organisme qui chasse et consomme activement d’autres organismes dans le cadre normal de son cycle de vie.'}},
  {term:{es:'Deriva genética (Genetic drift)', en:'Genetic drift', de:'Gendrift', fr:'Dérive génétique'}, def:{es:'Cambio aleatorio en la frecuencia de rasgos genéticos dentro de una población pequeña, generación tras generación.', en:'A random change in the frequency of genetic traits within a small population, generation after generation.', de:'Eine zufällige Veränderung der Häufigkeit genetischer Merkmale innerhalb einer kleinen Population, Generation für Generation.', fr:'Changement aléatoire de la fréquence des caractères génétiques au sein d’une petite population, génération après génération.'}},
  {term:{es:'Desarrollo floral (Bud development)', en:'Bud development', de:'Blütenentwicklung (Bud development)', fr:'Développement floral (Bud development)'}, def:{es:'La fase de crecimiento y engrosamiento activo de las flores, donde se acumula la mayor parte de la masa floral final.', en:'The phase of active flower growth and thickening, where most of the final bud mass accumulates.', de:'Die Phase des aktiven Wachstums und der Verdickung der Blüten, in der sich der Großteil der endgültigen Blütenmasse ansammelt.', fr:'La phase de croissance et d’épaississement actif des fleurs, où s’accumule la majeure partie de la masse florale finale.'}},
  {term:{es:'Deshumidificador', en:'Dehumidifier', de:'Luftentfeuchter', fr:'Déshumidificateur'}, def:{es:'Equipo que extrae el exceso de humedad del aire, condensándola y removiéndola del espacio.', en:'Equipment that removes excess moisture from the air by condensing it and removing it from the space.', de:'Ein Gerät, das überschüssige Feuchtigkeit aus der Luft entfernt, indem es sie kondensiert und aus dem Raum abführt.', fr:'Équipement qui extrait l’excès d’humidité de l’air en la condensant et en l’évacuant de l’espace.'}},
  {term:{es:'Desinfección', en:'Disinfection', de:'Desinfektion', fr:'Désinfection'}, def:{es:'Reduce significativamente (sin eliminar por completo) la carga de patógenos, generalmente con productos químicos — menos riguroso que la esterilización.', en:'Significantly reduces (without fully eliminating) the pathogen load, generally using chemical products — less rigorous than sterilization.', de:'Reduziert die Erregerlast deutlich (ohne sie vollständig zu beseitigen), in der Regel mit chemischen Mitteln — weniger streng als die Sterilisation.', fr:'Réduit significativement (sans l’éliminer totalement) la charge en pathogènes, généralement avec des produits chimiques — moins rigoureuse que la stérilisation.'}},
  {term:{es:'Distancia internodal', en:'Internodal distance', de:'Internodienabstand', fr:'Distance internodale'}, def:{es:'La distancia entre nudos consecutivos — espaciado corto indica buena luz; largo puede indicar estiramiento por falta de luz.', en:'The distance between consecutive nodes — short spacing indicates good light; long spacing can indicate stretching from insufficient light.', de:'Der Abstand zwischen aufeinanderfolgenden Knoten — kurzer Abstand deutet auf gutes Licht hin; großer Abstand kann auf Streckung durch Lichtmangel hinweisen.', fr:'La distance entre nœuds consécutifs — un espacement court indique une bonne lumière ; un espacement long peut indiquer un étirement dû à un manque de lumière.'}},
  {term:{es:'Diversidad genética', en:'Genetic diversity', de:'Genetische Vielfalt', fr:'Diversité génétique'}, def:{es:'La variedad de genes distintos presentes dentro de una población o línea genética.', en:'The variety of distinct genes present within a population or genetic line.', de:'Die Vielfalt unterschiedlicher Gene innerhalb einer Population oder genetischen Linie.', fr:'La variété de gènes distincts présents au sein d’une population ou d’une lignée génétique.'}},
  {term:{es:'DLI (integral de luz diaria)', en:'DLI (daily light integral)', de:'DLI (Tageslichtintegral)', fr:'DLI (intégrale de lumière journalière)'}, def:{es:'La cantidad total de luz que recibe una planta en 24 horas.', en:'The total amount of light a plant receives in 24 hours.', de:'Die Gesamtlichtmenge, die eine Pflanze in 24 Stunden erhält.', fr:'La quantité totale de lumière reçue par une plante en 24 heures.'}},
  {term:{es:'Dominancia apical', en:'Apical dominance', de:'Apikale Dominanz', fr:'Dominance apicale'}, def:{es:'Fenómeno hormonal donde la punta de crecimiento suprime el desarrollo de yemas laterales — la base científica de por qué técnicas como el topping funcionan.', en:'A hormonal phenomenon where the growth tip suppresses lateral bud development — the scientific basis for why techniques like topping work.', de:'Ein hormonelles Phänomen, bei dem die Wachstumsspitze die Entwicklung seitlicher Knospen unterdrückt — die wissenschaftliche Grundlage dafür, warum Techniken wie Topping funktionieren.', fr:'Un phénomène hormonal où la pointe de croissance supprime le développement des bourgeons latéraux — la base scientifique du fonctionnement de techniques comme le topping.'}},
  {term:{es:'Domo de propagación (Humidity dome)', en:'Humidity dome', de:'Feuchtigkeitshaube', fr:'Dôme d’humidité'}, def:{es:'Cubierta transparente que mantiene alta humedad alrededor del follaje mientras las raíces se desarrollan.', en:'A transparent cover that keeps humidity high around the foliage while the roots develop.', de:'Eine transparente Abdeckung, die eine hohe Luftfeuchtigkeit um das Laub aufrechterhält, während sich die Wurzeln entwickeln.', fr:'Couvercle transparent qui maintient une humidité élevée autour du feuillage pendant que les racines se développent.'}},
  {term:{es:'Dosel vegetal (Canopy)', en:'Canopy', de:'Canopy', fr:'Canopée'}, def:{es:'La superficie ocupada por la parte superior de las plantas, donde incide la mayor parte de la luz — variable clave en técnicas como ScrOG o SOG.', en:'The surface occupied by the upper part of the plants, where most of the light lands — a key variable in techniques like ScrOG or SOG.', de:'Die Fläche, die vom oberen Teil der Pflanzen eingenommen wird und auf die der Großteil des Lichts trifft — eine Schlüsselvariable bei Techniken wie ScrOG oder SOG.', fr:'La surface occupée par la partie supérieure des plantes, où arrive la majeure partie de la lumière — variable clé dans des techniques comme le ScrOG ou le SOG.'}},
  {term:{es:'Drenaje', en:'Drainage', de:'Drainage', fr:'Drainage'}, def:{es:'La capacidad de un sustrato o sistema de permitir el flujo y salida del exceso de agua, evitando la saturación y falta de oxígeno en la zona radicular.', en:'The ability of a substrate or system to allow excess water to flow out, preventing saturation and lack of oxygen in the root zone.', de:'Die Fähigkeit eines Substrats oder Systems, überschüssiges Wasser abfließen zu lassen und so Sättigung und Sauerstoffmangel in der Wurzelzone zu vermeiden.', fr:'La capacité d’un substrat ou d’un système à permettre l’écoulement et l’évacuation de l’excès d’eau, évitant la saturation et le manque d’oxygène dans la zone racinaire.'}},
  {term:{es:'DWC recirculante (RDWC)', en:'Recirculating DWC (RDWC)', de:'Rezirkulierendes DWC (RDWC)', fr:'DWC recirculant (RDWC)'}, def:{es:'Variante de DWC donde múltiples baldes/contenedores están conectados entre sí y comparten una solución nutritiva que circula continuamente entre ellos desde un reservorio central.', en:'A variant of DWC where multiple buckets/containers are connected to each other and share a nutrient solution that circulates continuously between them from a central reservoir.', de:'Eine Variante von DWC, bei der mehrere Eimer/Behälter miteinander verbunden sind und sich eine Nährlösung teilen, die kontinuierlich zwischen ihnen von einem zentralen Reservoir aus zirkuliert.', fr:'Variante du DWC où plusieurs seaux/conteneurs sont connectés entre eux et partagent une solution nutritive qui circule en continu entre eux depuis un réservoir central.'}},
  {term:{es:'Efecto séquito (entourage effect)', en:'Entourage effect', de:'Entourage-Effekt', fr:'Effet d’entourage'}, def:{es:'La teoría de que cannabinoides, terpenos y flavonoides actúan mejor juntos que aislados.', en:'The theory that cannabinoids, terpenes, and flavonoids work better together than in isolation.', de:'Die Theorie, dass Cannabinoide, Terpene und Flavonoide zusammen besser wirken als isoliert.', fr:'La théorie selon laquelle cannabinoïdes, terpènes et flavonoïdes agissent mieux ensemble qu’isolés.'}},
  {term:{es:'Eliminación de tallos (Destemming)', en:'Destemming', de:'Entstielen (Destemming)', fr:'Éraflage (Destemming)'}, def:{es:'Remover tallos y ramas pequeñas del material floral, para procesamiento posterior.', en:'Removing stems and small branches from the floral material, for further processing.', de:'Das Entfernen von Stielen und kleinen Ästen aus dem Blütenmaterial, zur weiteren Verarbeitung.', fr:'Retirer les tiges et petites branches du matériel floral, en vue d’un traitement ultérieur.'}},
  {term:{es:'Endocannabinoide', en:'Endocannabinoid', de:'Endocannabinoid', fr:'Endocannabinoïde'}, def:{es:'Cannabinoide producido naturalmente por el cuerpo humano, que interactúa con el sistema endocannabinoide — los mejor caracterizados son la anandamida y el 2-AG.', en:'A cannabinoid naturally produced by the human body, which interacts with the endocannabinoid system — the best characterized are anandamide and 2-AG.', de:'Ein vom menschlichen Körper natürlich produziertes Cannabinoid, das mit dem Endocannabinoid-System interagiert — am besten charakterisiert sind Anandamid und 2-AG.', fr:'Cannabinoïde produit naturellement par le corps humain, qui interagit avec le système endocannabinoïde — les mieux caractérisés sont l’anandamide et le 2-AG.'}},
  {term:{es:'Endogamia (Inbreeding)', en:'Inbreeding', de:'Inzucht', fr:'Consanguinité'}, def:{es:'Cruce reiterado entre plantas genéticamente emparentadas — aumenta la homocigosis y fija rasgos, pero también incrementa el riesgo de rasgos recesivos indeseados (depresión endogámica).', en:'Repeated crossing between genetically related plants — increases homozygosity and fixes traits, but also raises the risk of unwanted recessive traits (inbreeding depression).', de:'Wiederholte Kreuzung zwischen genetisch verwandten Pflanzen — erhöht die Homozygotie und fixiert Merkmale, steigert aber auch das Risiko unerwünschter rezessiver Merkmale (Inzuchtdepression).', fr:'Croisement répété entre plantes génétiquement apparentées — augmente l’homozygotie et fixe des caractères, mais accroît aussi le risque de caractères récessifs indésirables (dépression de consanguinité).'}},
  {term:{es:'Enraizamiento (Rooting)', en:'Rooting', de:'Bewurzelung', fr:'Enracinement'}, def:{es:'El proceso por el cual un esqueje desarrolla su propio sistema radicular.', en:'The process by which a cutting develops its own root system.', de:'Der Prozess, bei dem ein Steckling sein eigenes Wurzelsystem entwickelt.', fr:'Le processus par lequel une bouture développe son propre système racinaire.'}},
  {term:{es:'Enriquecimiento con CO2', en:'CO2 enrichment', de:'CO2-Anreicherung', fr:'Enrichissement en CO2'}, def:{es:'Elevar artificialmente la concentración de CO2 por encima del nivel atmosférico (~420 ppm) para potencialmente aumentar la tasa fotosintética.', en:'Artificially raising CO2 concentration above the atmospheric level (~420 ppm) to potentially increase the photosynthetic rate.', de:'Das künstliche Anheben der CO2-Konzentration über das atmosphärische Niveau (~420 ppm), um die Photosyntheserate möglicherweise zu erhöhen.', fr:'Élever artificiellement la concentration de CO2 au-dessus du niveau atmosphérique (~420 ppm) pour potentiellement augmenter le taux photosynthétique.'}},
  {term:{es:'Entrenudo (Internode)', en:'Internode', de:'Internodium', fr:'Entre-nœud'}, def:{es:'La distancia entre dos nudos consecutivos. Un entrenudo corto suele asociarse a mejor manejo lumínico; el estiramiento excesivo puede indicar falta de luz.', en:'The distance between two consecutive nodes. A short internode is usually associated with better light management; excessive stretching can indicate insufficient light.', de:'Der Abstand zwischen zwei aufeinanderfolgenden Knoten. Ein kurzes Internodium wird meist mit besserem Lichtmanagement in Verbindung gebracht; übermäßige Streckung kann auf Lichtmangel hindeuten.', fr:'La distance entre deux nœuds consécutifs. Un entre-nœud court est généralement associé à une meilleure gestion de la lumière ; un étirement excessif peut indiquer un manque de lumière.'}},
  {term:{es:'Entutorado (Trellising)', en:'Trellising', de:'Rankhilfe (Trellising)', fr:'Tuteurage (Trellising)'}, def:{es:'Estructuras de soporte para sostener ramas y colas, especialmente en floración.', en:'Support structures used to hold up branches and colas, especially during flowering.', de:'Stützstrukturen zum Halten von Zweigen und Colas, besonders während der Blüte.', fr:'Structures de soutien pour maintenir les branches et les colas, en particulier pendant la floraison.'}},
  {term:{es:'Equipo de cosecha (Harvest crew)', en:'Harvest crew', de:'Erntemannschaft (Harvest crew)', fr:'Équipe de récolte (Harvest crew)'}, def:{es:'El grupo de personas asignado a las tareas de cosecha durante el período intensivo de recolección.', en:'The group of people assigned to harvest tasks during the intensive collection period.', de:'Die Gruppe von Personen, die während der intensiven Erntephase den Erntearbeiten zugeteilt ist.', fr:'Le groupe de personnes affecté aux tâches de récolte pendant la période intensive de collecte.'}},
  {term:{es:'Escorrentía (Runoff)', en:'Runoff', de:'Abfluss (Runoff)', fr:'Lixiviat (Runoff)'}, def:{es:'El agua/solución nutritiva sobrante que sale por la base de un contenedor después del riego — su volumen y composición (EC, pH) se mide comúnmente como indicador de la salud del sustrato y la absorción de nutrientes de la planta.', en:'The leftover water/nutrient solution that exits the base of a container after watering — its volume and composition (EC, pH) are commonly measured as an indicator of substrate health and the plant’s nutrient uptake.', de:'Die überschüssige Wasser-/Nährlösung, die nach der Bewässerung am Boden eines Behälters austritt — ihr Volumen und ihre Zusammensetzung (EC, pH) werden häufig als Indikator für die Substratgesundheit und die Nährstoffaufnahme der Pflanze gemessen.', fr:'L’eau/solution nutritive excédentaire qui s’écoule par le bas d’un contenant après l’arrosage — son volume et sa composition (EC, pH) sont couramment mesurés comme indicateur de la santé du substrat et de l’absorption des nutriments par la plante.'}},
  {term:{es:'Espectro', en:'Spectrum', de:'Spektrum', fr:'Spectre'}, def:{es:'El rango completo de longitudes de onda emitidas por una fuente lumínica, medido en nanómetros.', en:'The full range of wavelengths emitted by a light source, measured in nanometers.', de:'Der gesamte Bereich der von einer Lichtquelle emittierten Wellenlängen, gemessen in Nanometern.', fr:'La gamme complète des longueurs d’onde émises par une source lumineuse, mesurée en nanomètres.'}},
  {term:{es:'Esqueje (Cutting)', en:'Cutting', de:'Steckling', fr:'Bouture'}, def:{es:'El segmento de tallo o rama cortado de una planta madre que se usa para generar un clon nuevo mediante enraizamiento.', en:'The stem or branch segment cut from a mother plant, used to grow a new clone by rooting it.', de:'Der von einer Mutterpflanze abgeschnittene Stängel- oder Astabschnitt, der zur Bewurzelung eines neuen Klons verwendet wird.', fr:'Le segment de tige ou de branche coupé sur une plante mère, utilisé pour générer un nouveau clone par enracinement.'}},
  {term:{es:'Estabilización genética', en:'Genetic stabilization', de:'Genetische Stabilisierung', fr:'Stabilisation génétique'}, def:{es:'El proceso de fijar rasgos deseados a través de varias generaciones de selección y retrocruce/autofecundación.', en:'The process of fixing desired traits over several generations of selection and backcrossing/selfing.', de:'Der Prozess, gewünschte Merkmale über mehrere Generationen von Selektion und Rückkreuzung/Selfing zu fixieren.', fr:'Le processus consistant à fixer des caractères souhaités sur plusieurs générations de sélection et de rétrocroisement/autofécondation.'}},
  {term:{es:'Esterilización', en:'Sterilization', de:'Sterilisation', fr:'Stérilisation'}, def:{es:'Elimina completamente todos los microorganismos (incluidas esporas) — el nivel más riguroso, típicamente con calor, autoclave o químicos específicos.', en:'Completely eliminates all microorganisms (including spores) — the most rigorous level, typically achieved with heat, an autoclave, or specific chemicals.', de:'Beseitigt vollständig alle Mikroorganismen (einschließlich Sporen) — die strengste Stufe, typischerweise mittels Hitze, Autoklav oder spezifischer Chemikalien.', fr:'Élimine complètement tous les micro-organismes (y compris les spores) — le niveau le plus rigoureux, généralement obtenu par la chaleur, un autoclave ou des produits chimiques spécifiques.'}},
  {term:{es:'Estigma', en:'Stigma', de:'Narbe', fr:'Stigmate'}, def:{es:'El pelo filamentoso —blanco, luego naranja o rojo al madurar— que emerge del cáliz y capta el polen para la fertilización.', en:'The filament-like hair — white, later turning orange or red as it matures — that emerges from the calyx and catches pollen for fertilization.', de:'Das fadenförmige Haar — zunächst weiß, später orange oder rot bei Reife —, das aus dem Kelch hervortritt und Pollen zur Befruchtung einfängt.', fr:'Le poil filamenteux — blanc, puis orange ou rouge à maturité — qui émerge du calice et capte le pollen pour la fécondation.'}},
  {term:{es:'Estiramiento (Stretch)', en:'Stretch', de:'Streckwachstum (Stretch)', fr:'Étirement (Stretch)'}, def:{es:'Crecimiento vertical acelerado en las primeras 1-3 semanas de floración.', en:'Accelerated vertical growth during the first 1-3 weeks of flowering.', de:'Beschleunigtes vertikales Wachstum in den ersten 1-3 Wochen der Blüte.', fr:'Croissance verticale accélérée durant les 1 à 3 premières semaines de floraison.'}},
  {term:{es:'Estrés lumínico', en:'Light stress', de:'Lichtstress', fr:'Stress lumineux'}, def:{es:'Cuando la planta recibe más o menos luz de la que puede procesar — decoloración, hojas curvadas, o crecimiento reducido.', en:'When a plant receives more or less light than it can process — discoloration, curled leaves, or reduced growth.', de:'Wenn eine Pflanze mehr oder weniger Licht erhält, als sie verarbeiten kann — Verfärbung, gekräuselte Blätter oder vermindertes Wachstum.', fr:'Lorsque la plante reçoit plus ou moins de lumière qu’elle ne peut en traiter — décoloration, feuilles recroquevillées ou croissance réduite.'}},
  {term:{es:'Etapa de floración', en:'Flowering stage', de:'Blütephase', fr:'Stade de floraison'}, def:{es:'Fase donde la planta desarrolla flores/cogollos — inducida reduciendo el fotoperiodo a 12/12 o naturalmente en otoño.', en:'A phase where the plant develops flowers/buds — induced by reducing the photoperiod to 12/12 or naturally in autumn.', de:'Eine Phase, in der die Pflanze Blüten/Buds entwickelt — ausgelöst durch Reduzierung der Photoperiode auf 12/12 oder natürlich im Herbst.', fr:'Phase durant laquelle la plante développe des fleurs/têtes — induite en réduisant la photopériode à 12/12 ou naturellement en automne.'}},
  {term:{es:'Etapa vegetativa', en:'Vegetative stage', de:'Vegetative Phase', fr:'Stade végétatif'}, def:{es:'Fase donde la planta prioriza tallo, hojas y raíces, sin flores — se mantiene con 18+ horas de luz o durante días largos en exterior.', en:'A phase where the plant prioritizes stem, leaves, and roots, with no flowers — maintained with 18+ hours of light or during long days outdoors.', de:'Eine Phase, in der die Pflanze Stängel, Blätter und Wurzeln priorisiert, ohne Blüten — sie wird durch 18+ Lichtstunden oder lange Tage im Freien aufrechterhalten.', fr:'Phase durant laquelle la plante privilégie la tige, les feuilles et les racines, sans fleurs — maintenue avec 18 heures de lumière ou plus, ou pendant les longues journées en extérieur.'}},
  {term:{es:'Expresión genética', en:'Gene expression', de:'Genexpression', fr:'Expression génique'}, def:{es:'La manifestación observable (fenotípica) de la información del genotipo, influida también por el ambiente.', en:'The observable (phenotypic) manifestation of the genotype’s information, also influenced by the environment.', de:'Die beobachtbare (phänotypische) Manifestation der Genotyp-Information, die auch von der Umwelt beeinflusst wird.', fr:'La manifestation observable (phénotypique) de l’information du génotype, également influencée par l’environnement.'}},
  {term:{es:'Exterior (Outdoor)', en:'Outdoor', de:'Outdoor', fr:'Extérieur (Outdoor)'}, def:{es:'Cultivo a cielo abierto, dependiente por completo de las condiciones climáticas y el fotoperiodo natural.', en:'Cultivation in the open air, entirely dependent on weather conditions and the natural photoperiod.', de:'Anbau unter freiem Himmel, vollständig abhängig von den Witterungsbedingungen und der natürlichen Photoperiode.', fr:'Culture en plein air, entièrement dépendante des conditions climatiques et de la photopériode naturelle.'}},
  {term:{es:'F1 (Primera generación filial)', en:'F1 (First filial generation)', de:'F1 (Erste Filialgeneration)', fr:'F1 (Première génération filiale)'}, def:{es:'La primera generación de descendencia de un cruce entre dos líneas distintas — suele mostrar mayor uniformidad y vigor híbrido.', en:'The first generation of offspring from a cross between two distinct lines — usually shows greater uniformity and hybrid vigor.', de:'Die erste Nachkommengeneration aus einer Kreuzung zweier unterschiedlicher Linien — zeigt meist größere Einheitlichkeit und Heterosis (Hybridvigor).', fr:'La première génération de descendance issue d’un croisement entre deux lignées distinctes — présente généralement une plus grande uniformité et une vigueur hybride.'}},
  {term:{es:'F2 (Segunda generación filial)', en:'F2 (Second filial generation)', de:'F2 (Zweite Filialgeneration)', fr:'F2 (Deuxième génération filiale)'}, def:{es:'La descendencia de cruzar dos plantas F1 entre sí — muestra mayor variabilidad genética porque los rasgos empiezan a segregarse.', en:'The offspring from crossing two F1 plants with each other — shows greater genetic variability as traits begin to segregate.', de:'Die Nachkommen aus der Kreuzung zweier F1-Pflanzen untereinander — zeigen größere genetische Variabilität, da sich die Merkmale aufzuspalten beginnen.', fr:'La descendance issue du croisement de deux plantes F1 entre elles — présente une plus grande variabilité génétique car les caractères commencent à se ségréger.'}},
  {term:{es:'Fenotipo', en:'Phenotype', de:'Phänotyp', fr:'Phénotype'}, def:{es:'Conjunto de características observables de una planta (altura, color, aroma, producción), resultado de la interacción entre su genotipo y el ambiente de cultivo.', en:'The set of observable characteristics of a plant (height, color, aroma, yield) resulting from the interaction between its genotype and the growing environment.', de:'Die Gesamtheit der beobachtbaren Merkmale einer Pflanze (Höhe, Farbe, Aroma, Ertrag), die aus dem Zusammenspiel von Genotyp und Anbauumgebung entsteht.', fr:'Ensemble des caractéristiques observables d’une plante (hauteur, couleur, arôme, production) résultant de l’interaction entre son génotype et l’environnement de culture.'}},
  {term:{es:'Fertirrigación', en:'Fertigation', de:'Fertigation', fr:'Fertirrigation'}, def:{es:'Aplicar fertilizantes disueltos junto con el agua de riego, en el mismo evento — método estándar en hidroponía y sustrato.', en:'Applying dissolved fertilizers together with irrigation water, in the same event — the standard method in hydroponics and substrate growing.', de:'Das Ausbringen gelöster Düngemittel zusammen mit dem Bewässerungswasser in einem einzigen Vorgang — die Standardmethode in Hydroponik und Substratanbau.', fr:'Appliquer des engrais dissous en même temps que l’eau d’irrigation, lors du même événement — méthode standard en hydroponie et en substrat.'}},
  {term:{es:'Fibra de coco (Coco coir)', en:'Coco coir', de:'Kokosfaser (Coco coir)', fr:'Fibre de coco (Coco coir)'}, def:{es:'Sustrato orgánico derivado de la cáscara de coco procesada — retiene humedad de forma eficiente, tiene buena aireación y es considerado un medio semi-hidropónico por su bajo contenido nutricional propio (requiere fertirriego).', en:'An organic substrate derived from processed coconut husk — retains moisture efficiently, has good aeration, and is considered a semi-hydroponic medium due to its low inherent nutrient content (requires fertigation).', de:'Ein organisches Substrat aus verarbeiteter Kokosnussschale — speichert effizient Feuchtigkeit, bietet gute Belüftung und gilt aufgrund seines geringen Eigennährstoffgehalts als semi-hydroponisches Medium (erfordert Fertigation).', fr:'Substrat organique dérivé de la coque de coco transformée — retient efficacement l’humidité, offre une bonne aération et est considéré comme un milieu semi-hydroponique en raison de sa faible teneur nutritive propre (nécessite une fertigation).'}},
  {term:{es:'FIM/FIMing', en:'FIM/FIMing', de:'FIM/FIMing', fr:'FIM/FIMing'}, def:{es:'Variante del topping que corta ~75-80% de la punta en vez de removerla completa — genera más de dos brotes nuevos.', en:'A variant of topping that cuts ~75-80% of the tip instead of removing it entirely — produces more than two new shoots.', de:'Eine Variante des Toppings, bei der ~75-80% der Spitze abgeschnitten werden, statt sie vollständig zu entfernen — erzeugt mehr als zwei neue Triebe.', fr:'Variante du topping qui coupe environ 75-80 % de la pointe au lieu de la retirer entièrement — génère plus de deux nouvelles pousses.'}},
  {term:{es:'Fitocannabinoide', en:'Phytocannabinoid', de:'Phytocannabinoid', fr:'Phytocannabinoïde'}, def:{es:'Cannabinoide de origen vegetal, producido naturalmente por la planta — distingue de los endocannabinoides (cuerpo humano) y sintéticos (laboratorio).', en:'A plant-derived cannabinoid, naturally produced by the plant — distinct from endocannabinoids (human body) and synthetic ones (laboratory).', de:'Ein pflanzlicher Cannabinoid, natürlich von der Pflanze produziert — zu unterscheiden von Endocannabinoiden (menschlicher Körper) und synthetischen Cannabinoiden (Labor).', fr:'Cannabinoïde d’origine végétale, produit naturellement par la plante — se distingue des endocannabinoïdes (corps humain) et des cannabinoïdes de synthèse (laboratoire).'}},
  {term:{es:'Flavonoide', en:'Flavonoid', de:'Flavonoid', fr:'Flavonoïde'}, def:{es:'Pigmento vegetal, responsable del color de la planta y con propiedades bioactivas propias.', en:'A plant pigment, responsible for the plant’s color and with its own bioactive properties.', de:'Ein Pflanzenpigment, verantwortlich für die Farbe der Pflanze und mit eigenen bioaktiven Eigenschaften.', fr:'Pigment végétal, responsable de la couleur de la plante et doté de propriétés bioactives propres.'}},
  {term:{es:'Flujo de aire (Airflow)', en:'Airflow', de:'Luftstrom (Airflow)', fr:'Flux d’air (Airflow)'}, def:{es:'El movimiento del aire dentro y a través del espacio de cultivo — fortalece tallos, previene microclimas de humedad estancada.', en:'The movement of air within and through the grow space — strengthens stems, prevents stagnant-humidity microclimates.', de:'Die Bewegung der Luft innerhalb und durch den Anbauraum — stärkt die Stängel und verhindert Mikroklimata mit stehender Feuchtigkeit.', fr:'Le mouvement de l’air à l’intérieur et à travers l’espace de culture — renforce les tiges, prévient les microclimats d’humidité stagnante.'}},
  {term:{es:'Flujo y reflujo (Ebb and flow)', en:'Ebb and flow', de:'Ebbe und Flut (Ebb and flow)', fr:'Flux et reflux (Ebb and flow)'}, def:{es:'Sistema hidropónico donde la solución nutritiva inunda periódicamente la bandeja de cultivo (donde están las raíces/sustrato) y luego drena de vuelta a un reservorio, en ciclos programados.', en:'A hydroponic system where nutrient solution periodically floods the grow tray (where the roots/substrate sit) and then drains back into a reservoir, on programmed cycles.', de:'Ein hydroponisches System, bei dem die Nährlösung die Anzuchtschale (in der sich Wurzeln/Substrat befinden) periodisch flutet und dann in programmierten Zyklen wieder in ein Reservoir abläuft.', fr:'Système hydroponique où la solution nutritive inonde périodiquement le plateau de culture (où se trouvent les racines/le substrat) puis retourne par drainage dans un réservoir, selon des cycles programmés.'}},
  {term:{es:'Fluorescente', en:'Fluorescent', de:'Leuchtstofflampe (Fluoreszenzlampe)', fr:'Fluorescent'}, def:{es:'Tecnología de baja intensidad (T5, CFL), usada típicamente en propagación por su bajo calor.', en:'A low-intensity technology (T5, CFL), typically used in propagation for its low heat output.', de:'Eine Technologie mit geringer Intensität (T5, CFL), die aufgrund ihrer geringen Wärmeentwicklung typischerweise bei der Vermehrung eingesetzt wird.', fr:'Technologie de faible intensité (T5, CFL), typiquement utilisée en propagation pour sa faible production de chaleur.'}},
  {term:{es:'Fogponía (Fogponics)', en:'Fogponics', de:'Fogponik (Fogponics)', fr:'Fogponie (Fogponics)'}, def:{es:'Variante de la aeroponía donde la solución nutritiva se atomiza en partículas aún más finas (niebla/neblina, de tamaño submicrónico), permitiendo mayor absorción de oxígeno por parte de las raíces.', en:'A variant of aeroponics where the nutrient solution is atomized into even finer particles (fog/mist, submicron in size), allowing greater oxygen uptake by the roots.', de:'Eine Variante der Aeroponik, bei der die Nährlösung in noch feinere Partikel zerstäubt wird (Nebel, im Submikronbereich), was eine größere Sauerstoffaufnahme durch die Wurzeln ermöglicht.', fr:'Variante de l’aéroponie où la solution nutritive est atomisée en particules encore plus fines (brouillard/brume, de taille submicronique), permettant une meilleure absorption d’oxygène par les racines.'}},
  {term:{es:'Formación floral (Flower set)', en:'Flower set', de:'Blütenansatz (Flower set)', fr:'Formation florale (Flower set)'}, def:{es:'La etapa donde las estructuras florales se establecen consistentemente en los nudos, tras el estiramiento inicial.', en:'The stage where floral structures become consistently established at the nodes, following the initial stretch.', de:'Die Phase, in der sich Blütenstrukturen nach der anfänglichen Streckung konsequent an den Knoten ausbilden.', fr:'L’étape où les structures florales s’établissent de manière constante au niveau des nœuds, après l’étirement initial.'}},
  {term:{es:'Fósforo (P)', en:'Phosphorus (P)', de:'Phosphor (P)', fr:'Phosphore (P)'}, def:{es:'Macronutriente primario importante en transferencia de energía celular, desarrollo de raíces y floración.', en:'A primary macronutrient important for cellular energy transfer, root development, and flowering.', de:'Ein primärer Makronährstoff, der für den zellulären Energietransfer, die Wurzelentwicklung und die Blüte wichtig ist.', fr:'Macronutriment primaire important pour le transfert d’énergie cellulaire, le développement racinaire et la floraison.'}},
  {term:{es:'Fotoblanqueamiento', en:'Photobleaching', de:'Photobleichung', fr:'Photoblanchiment'}, def:{es:'Degradación de clorofila por exceso de luz, distinto de la quemadura porque es daño a nivel de pigmento, no necesariamente tejido muerto.', en:'Chlorophyll degradation from excess light, distinct from light burn because it is pigment-level damage, not necessarily dead tissue.', de:'Abbau von Chlorophyll durch übermäßiges Licht, zu unterscheiden von der Lichtverbrennung, da es sich um eine Schädigung auf Pigmentebene handelt, nicht zwangsläufig um abgestorbenes Gewebe.', fr:'Dégradation de la chlorophylle due à un excès de lumière, distincte de la brûlure lumineuse car il s’agit d’un dommage au niveau du pigment, pas nécessairement d’un tissu mort.'}},
  {term:{es:'Fotoperiodo', en:'Photoperiod', de:'Photoperiode', fr:'Photopériode'}, def:{es:'El ciclo de horas de luz y oscuridad que determina cuándo florece la planta.', en:'The cycle of light and dark hours that determines when the plant flowers.', de:'Der Zyklus von Licht- und Dunkelstunden, der bestimmt, wann die Pflanze blüht.', fr:'Le cycle d’heures de lumière et d’obscurité qui détermine quand la plante fleurit.'}},
  {term:{es:'Full spectrum', en:'Full spectrum', de:'Full Spectrum', fr:'Full spectrum'}, def:{es:'Extracto que conserva todos los compuestos originales de la planta, incluidas trazas de THC.', en:'An extract that keeps all the plant’s original compounds, including trace THC.', de:'Ein Extrakt, der alle ursprünglichen Verbindungen der Pflanze bewahrt, einschließlich THC-Spuren.', fr:'Extrait conservant tous les composés d’origine de la plante, y compris des traces de THC.'}},
  {term:{es:'Full spectrum (luz de cultivo)', en:'Full spectrum (grow light)', de:'Full Spectrum (Wachstumslicht)', fr:'Spectre complet (lampe de culture)'}, def:{es:'Fuente de luz de cultivo diseñada para emitir un rango amplio de longitudes de onda, replicando el espectro solar (incluyendo UV e infrarrojo en algunos modelos). Distinto del "Full spectrum" de extractos, que se refiere a conservar todos los compuestos originales de la planta.', en:'A grow light source designed to emit a wide range of wavelengths, replicating the solar spectrum (including UV and infrared in some models). Distinct from the extract sense of "Full spectrum," which refers to preserving all of the plant’s original compounds.', de:'Eine Wachstumslichtquelle, die ein breites Spektrum an Wellenlängen abgibt und das Sonnenspektrum nachbildet (bei manchen Modellen einschließlich UV und Infrarot). Zu unterscheiden vom "Full Spectrum"-Begriff bei Extrakten, der sich auf den Erhalt aller ursprünglichen Pflanzenverbindungen bezieht.', fr:'Source de lumière de culture conçue pour émettre une large gamme de longueurs d’onde, reproduisant le spectre solaire (y compris l’UV et l’infrarouge sur certains modèles). À distinguer du « Full spectrum » des extraits, qui désigne la conservation de tous les composés d’origine de la plante.'}},
  {term:{es:'Fusarium', en:'Fusarium', de:'Fusarium', fr:'Fusarium'}, def:{es:'Hongo patógeno del suelo que causa pudrición de raíces y marchitez vascular — de difícil erradicación una vez establecido.', en:'A soil-borne pathogenic fungus that causes root rot and vascular wilt — difficult to eradicate once established.', de:'Ein bodenbürtiger Pilzpathogen, der Wurzelfäule und Gefäßwelke verursacht — nach seiner Etablierung schwer auszurotten.', fr:'Champignon pathogène tellurique causant pourriture racinaire et flétrissement vasculaire — difficile à éradiquer une fois établi.'}},
  {term:{es:'GACP', en:'GACP', de:'GACP', fr:'GACP'}, def:{es:'Guías de buenas prácticas agrícolas, el estándar internacional para cultivo farmacéutico.', en:'Good agricultural and collection practice guidelines, the international standard for pharmaceutical-grade cultivation.', de:'Leitlinien für gute landwirtschaftliche Praxis, der internationale Standard für den pharmazeutischen Anbau.', fr:'Directives de bonnes pratiques agricoles, la norme internationale pour la culture à usage pharmaceutique.'}},
  {term:{es:'Genotipo', en:'Genotype', de:'Genotyp', fr:'Génotype'}, def:{es:'La composición genética completa de una planta, independiente de cómo se exprese visualmente.', en:'The complete genetic makeup of a plant, independent of how it visually expresses itself.', de:'Die vollständige genetische Ausstattung einer Pflanze, unabhängig davon, wie sie sich äußerlich zeigt.', fr:'La composition génétique complète d’une plante, indépendamment de la façon dont elle s’exprime visuellement.'}},
  {term:{es:'Germinación', en:'Germination', de:'Keimung', fr:'Germination'}, def:{es:'El proceso mediante el cual una semilla activa su desarrollo embrionario y emerge como plántula.', en:'The process by which a seed activates its embryonic development and emerges as a seedling.', de:'Der Prozess, bei dem ein Samen seine embryonale Entwicklung aktiviert und als Keimling hervortritt.', fr:'Le processus par lequel une graine active son développement embryonnaire et émerge sous forme de plantule.'}},
  {term:{es:'Hachís', en:'Hashish', de:'Haschisch', fr:'Hachich'}, def:{es:'Resina de cannabis concentrada, hecha con tricomas prensados.', en:'Concentrated cannabis resin, made from pressed trichomes.', de:'Konzentriertes Cannabisharz, hergestellt aus gepressten Trichomen.', fr:'Résine de cannabis concentrée, fabriquée à partir de trichomes pressés.'}},
  {term:{es:'Hembra', en:'Female plant', de:'Weibliche Pflanze', fr:'Plante femelle'}, def:{es:'Planta que produce las flores/cogollos de interés comercial y medicinal.', en:'The plant that produces the flowers/buds of commercial and medicinal interest.', de:'Die Pflanze, die die Blüten/Buds von kommerziellem und medizinischem Interesse produziert.', fr:'Plante qui produit les fleurs/bourgeons d’intérêt commercial et médicinal.'}},
  {term:{es:'Hermafrodita (Herm)', en:'Hermaphrodite (Herm)', de:'Hermaphrodit (Herm)', fr:'Hermaphrodite (Herm)'}, def:{es:'Planta que desarrolla estructuras reproductivas masculinas y femeninas simultáneamente, a menudo por estrés ambiental — riesgo importante porque puede autopolinizar el cultivo completo.', en:'A plant that develops male and female reproductive structures at the same time, often triggered by environmental stress — a significant risk because it can self-pollinate an entire crop.', de:'Eine Pflanze, die gleichzeitig männliche und weibliche Fortpflanzungsstrukturen entwickelt, oft ausgelöst durch Umweltstress — ein erhebliches Risiko, da sie den gesamten Anbau selbst bestäuben kann.', fr:'Plante qui développe simultanément des structures reproductives mâles et femelles, souvent déclenchées par un stress environnemental — risque important car elle peut autopolliniser toute la culture.'}},
  {term:{es:'Heterocigoto', en:'Heterozygous', de:'Heterozygot', fr:'Hétérozygote'}, def:{es:'Planta con dos copias diferentes de un gen en un locus determinado.', en:'A plant with two different copies of a gene at a given locus.', de:'Eine Pflanze mit zwei unterschiedlichen Kopien eines Gens an einem bestimmten Genort.', fr:'Plante possédant deux copies différentes d’un gène à un locus donné.'}},
  {term:{es:'Híbrido', en:'Hybrid', de:'Hybride', fr:'Hybride'}, def:{es:'Descendencia resultante del cruce entre dos variedades o líneas genéticamente diferentes.', en:'Offspring resulting from crossing two genetically different varieties or lines.', de:'Nachkommen, die aus der Kreuzung zweier genetisch unterschiedlicher Sorten oder Linien entstehen.', fr:'Descendance issue du croisement entre deux variétés ou lignées génétiquement différentes.'}},
  {term:{es:'Hidroponía', en:'Hydroponics', de:'Hydroponik', fr:'Hydroponie'}, def:{es:'Método de cultivo sin suelo en el que las raíces reciben nutrientes disueltos directamente en agua, ya sea con o sin un medio de soporte inerte.', en:'A soil-less growing method in which roots receive nutrients dissolved directly in water, either with or without an inert support medium.', de:'Eine bodenlose Anbaumethode, bei der die Wurzeln Nährstoffe erhalten, die direkt in Wasser gelöst sind, entweder mit oder ohne inertes Trägermedium.', fr:'Méthode de culture sans sol dans laquelle les racines reçoivent des nutriments dissous directement dans l’eau, avec ou sans support inerte.'}},
  {term:{es:'Hierro (Fe)', en:'Iron (Fe)', de:'Eisen (Fe)', fr:'Fer (Fe)'}, def:{es:'Micronutriente esencial para síntesis de clorofila — poca movilidad, produce clorosis en hojas nuevas con venas verdes.', en:'A micronutrient essential for chlorophyll synthesis — has low mobility, causing chlorosis in new leaves with green veins.', de:'Ein für die Chlorophyllsynthese essenzieller Mikronährstoff — wenig mobil, verursacht Chlorose in neuen Blättern mit grünen Blattadern.', fr:'Micronutriment essentiel à la synthèse de la chlorophylle — peu mobile, provoque une chlorose sur les feuilles nouvelles avec des nervures vertes.'}},
  {term:{es:'HLVd (Viroide latente del lúpulo)', en:'HLVd (Hop Latent Viroid)', de:'HLVd (Hopfen-Latent-Viroid)', fr:'HLVd (Viroïde latent du houblon)'}, def:{es:'Partícula de ARN infecciosa (más simple que un virus) que infecta cannabis de forma a menudo asintomática — transmitida por herramientas contaminadas. Ver "Cultivo de meristemos" como método de saneamiento genético.', en:'An infectious RNA particle (simpler than a virus) that infects cannabis, often asymptomatically — spread by contaminated tools. See "Meristem culture" for the genetic clean-up method.', de:'Ein infektiöses RNA-Partikel (einfacher als ein Virus), das Cannabis oft symptomlos infiziert — verbreitet durch kontaminierte Werkzeuge. Siehe "Meristemkultur" als Methode zur genetischen Sanierung.', fr:'Particule d’ARN infectieuse (plus simple qu’un virus) qui infecte le cannabis, souvent de façon asymptomatique — transmise par des outils contaminés. Voir « Culture de méristèmes » pour la méthode d’assainissement génétique.'}},
  {term:{es:'Hoja abanico (Fan leaf)', en:'Fan leaf', de:'Fächerblatt', fr:'Feuille en éventail'}, def:{es:'Hoja grande, de múltiples foliolos, ubicada lejos de las flores. Su función principal es la fotosíntesis; tiene pocos tricomas.', en:'A large, multi-fingered leaf located away from the flowers. Its main function is photosynthesis; it has few trichomes.', de:'Ein großes, mehrfingriges Blatt, das weit entfernt von den Blüten sitzt. Seine Hauptfunktion ist die Photosynthese; es besitzt wenige Trichome.', fr:'Grande feuille à plusieurs folioles, située loin des fleurs. Sa fonction principale est la photosynthèse ; elle possède peu de trichomes.'}},
  {term:{es:'Hoja de azúcar (Sugar leaf)', en:'Sugar leaf', de:'Zuckerblatt', fr:'Feuille sucrée'}, def:{es:'Hoja pequeña que crece intercalada dentro de las flores, cubierta de tricomas visibles.', en:'A small leaf that grows interspersed within the flowers, covered in visible trichomes.', de:'Ein kleines Blatt, das zwischen den Blüten wächst und mit sichtbaren Trichomen bedeckt ist.', fr:'Petite feuille qui pousse intercalée dans les fleurs, couverte de trichomes visibles.'}},
  {term:{es:'Homocigoto', en:'Homozygous', de:'Homozygot', fr:'Homozygote'}, def:{es:'Planta con dos copias idénticas de un gen en un locus determinado.', en:'A plant with two identical copies of a gene at a given locus.', de:'Eine Pflanze mit zwei identischen Kopien eines Gens an einem bestimmten Genort.', fr:'Plante possédant deux copies identiques d’un gène à un locus donné.'}},
  {term:{es:'Hormona de enraizamiento (Rooting hormone)', en:'Rooting hormone', de:'Bewurzelungshormon', fr:'Hormone d’enracinement'}, def:{es:'Producto con auxinas sintéticas o naturales para estimular el desarrollo de raíces.', en:'A product with synthetic or natural auxins used to stimulate root development.', de:'Ein Produkt mit synthetischen oder natürlichen Auxinen zur Förderung der Wurzelentwicklung.', fr:'Produit contenant des auxines synthétiques ou naturelles, utilisé pour stimuler le développement des racines.'}},
  {term:{es:'HPS (Sodio de alta presión)', en:'HPS (High-Pressure Sodium)', de:'HPS (Natriumdampflampe)', fr:'HPS (Sodium haute pression)'}, def:{es:'Tecnología de descarga de gas, tradicionalmente usada en floración por su espectro cálido; menos eficiente que LED, genera más calor.', en:'A gas-discharge technology, traditionally used during flowering for its warm spectrum; less efficient than LED, generates more heat.', de:'Eine Gasentladungstechnologie, traditionell in der Blüte wegen ihres warmen Spektrums eingesetzt; weniger effizient als LED und erzeugt mehr Wärme.', fr:'Technologie à décharge de gaz, traditionnellement utilisée en floraison pour son spectre chaud ; moins efficace que le LED, génère plus de chaleur.'}},
  {term:{es:'HST (Entrenamiento de alto estrés)', en:'HST (High-Stress Training)', de:'HST (High-Stress Training)', fr:'HST (Entraînement à haut stress)'}, def:{es:'Técnicas con cortes o daño controlado al tejido (topping, FIM, supercropping) que generan recuperación pero aumentan sitios de floración.', en:'Techniques involving cuts or controlled tissue damage (topping, FIM, supercropping) that trigger recovery but increase flowering sites.', de:'Techniken mit Schnitten oder kontrollierter Gewebeschädigung (Topping, FIM, Supercropping), die eine Erholungsreaktion auslösen, aber die Anzahl der Blütenstandorte erhöhen.', fr:'Techniques impliquant des coupes ou des dommages tissulaires contrôlés (topping, FIM, supercropping) qui déclenchent une récupération tout en augmentant les sites de floraison.'}},
  {term:{es:'Huella genética (DNA fingerprinting)', en:'DNA fingerprinting', de:'Genetischer Fingerabdruck', fr:'Empreinte génétique'}, def:{es:'Análisis de ADN que genera un perfil genético único para verificar identidad de variedad o detectar duplicados.', en:'A DNA analysis that generates a unique genetic profile to verify variety identity or detect duplicates.', de:'Eine DNA-Analyse, die ein einzigartiges genetisches Profil erstellt, um die Identität einer Sorte zu überprüfen oder Duplikate zu erkennen.', fr:'Analyse de l’ADN générant un profil génétique unique pour vérifier l’identité d’une variété ou détecter des doublons.'}},
  {term:{es:'Humedad relativa (RH)', en:'Relative humidity (RH)', de:'Relative Luftfeuchtigkeit (RH)', fr:'Humidité relative (RH)'}, def:{es:'Medida del contenido de vapor de agua en el aire como porcentaje del máximo a esa temperatura — clave junto con la temperatura para calcular el VPD.', en:'A measure of the water vapor content in the air as a percentage of the maximum possible at that temperature — key, together with temperature, for calculating VPD.', de:'Ein Maß für den Wasserdampfgehalt der Luft als Prozentsatz des bei dieser Temperatur maximal möglichen Werts — zusammen mit der Temperatur entscheidend für die Berechnung des VPD.', fr:'Mesure de la teneur en vapeur d’eau de l’air exprimée en pourcentage du maximum possible à cette température — essentielle, avec la température, pour calculer le VPD.'}},
  {term:{es:'Humidificador', en:'Humidifier', de:'Luftbefeuchter', fr:'Humidificateur'}, def:{es:'Equipo que añade humedad al aire, usado en etapas que requieren humedad relativa alta (propagación, clones, vegetativo temprano).', en:'Equipment that adds moisture to the air, used in stages that require high relative humidity (propagation, clones, early vegetative growth).', de:'Ein Gerät, das der Luft Feuchtigkeit zuführt, verwendet in Phasen, die eine hohe relative Luftfeuchtigkeit erfordern (Vermehrung, Klone, frühe vegetative Phase).', fr:'Équipement qui ajoute de l’humidité à l’air, utilisé aux stades nécessitant une humidité relative élevée (propagation, clones, début de la phase végétative).'}},
  {term:{es:'Humuleno', en:'Humulene', de:'Humulen', fr:'Humulène'}, def:{es:'Aroma terroso/leñoso (también en el lúpulo). Estudiado por posibles propiedades antiinflamatorias y como supresor de apetito — contrasta con el efecto "munchies" del THC.', en:'Earthy/woody aroma (also found in hops). Studied for possible anti-inflammatory properties and as an appetite suppressant — contrasting with THC’s "munchies" effect.', de:'Erdiges/holziges Aroma (auch in Hopfen enthalten). Untersucht auf mögliche entzündungshemmende Eigenschaften und als appetitzügelnd — im Gegensatz zum "Munchies"-Effekt von THC.', fr:'Arôme terreux/boisé (également présent dans le houblon). Étudié pour ses propriétés anti-inflammatoires potentielles et comme coupe-faim — contrastant avec l’effet « munchies » du THC.'}},
  {term:{es:'HVAC', en:'HVAC', de:'HVAC (Heizung, Lüftung, Klimatisierung)', fr:'CVC (HVAC)'}, def:{es:'Heating, Ventilation, and Air Conditioning — el sistema integral que regula temperatura, humedad y circulación de aire en un espacio cerrado.', en:'Heating, Ventilation, and Air Conditioning — the integrated system that regulates temperature, humidity, and air circulation in an enclosed space.', de:'Heating, Ventilation, and Air Conditioning (Heizung, Lüftung, Klimatisierung) — das integrierte System, das Temperatur, Luftfeuchtigkeit und Luftzirkulation in einem geschlossenen Raum reguliert.', fr:'Heating, Ventilation, and Air Conditioning (chauffage, ventilation, climatisation) — le système intégré qui régule la température, l’humidité et la circulation de l’air dans un espace fermé.'}},
  {term:{es:'HVACD', en:'HVACD', de:'HVACD', fr:'HVACD'}, def:{es:'HVAC con capacidad de deshumidificación integrada — término específico de cultivo indoor, donde el control de humedad es tan crítico como el de temperatura.', en:'HVAC with integrated dehumidification capacity — a term specific to indoor cultivation, where humidity control is as critical as temperature control.', de:'HVAC mit integrierter Entfeuchtungsfunktion — ein Begriff speziell für den Indoor-Anbau, bei dem die Feuchtigkeitskontrolle ebenso kritisch ist wie die Temperaturkontrolle.', fr:'HVAC avec capacité de déshumidification intégrée — terme spécifique à la culture indoor, où le contrôle de l’humidité est aussi critique que celui de la température.'}},
  {term:{es:'Inflorescencia', en:'Inflorescence', de:'Blütenstand', fr:'Inflorescence'}, def:{es:'Término botánico general para el conjunto de flores agrupadas; en cannabis, sinónimo técnico de "flor" o "cogollo".', en:'A general botanical term for a cluster of grouped flowers; in cannabis, the technical synonym for "flower" or "bud."', de:'Ein allgemeiner botanischer Begriff für eine Gruppe zusammengefasster Blüten; bei Cannabis das technische Synonym für "Blüte" oder "Bud".', fr:'Terme botanique général désignant un ensemble de fleurs regroupées ; chez le cannabis, synonyme technique de « fleur » ou « bourgeon ».'}},
  {term:{es:'Inicio floral (Flower initiation)', en:'Flower initiation', de:'Blüteninitiierung', fr:'Initiation florale'}, def:{es:'El punto donde la planta cambia de crecimiento vegetativo a producción de estructuras florales, desencadenado por el fotoperiodo.', en:'The point at which the plant switches from vegetative growth to producing floral structures, triggered by the photoperiod.', de:'Der Zeitpunkt, an dem die Pflanze vom vegetativen Wachstum zur Produktion von Blütenstrukturen wechselt, ausgelöst durch die Photoperiode.', fr:'Le moment où la plante passe de la croissance végétative à la production de structures florales, déclenché par la photopériode.'}},
  {term:{es:'Insectos benéficos', en:'Beneficial insects', de:'Nützlinge (Nützliche Insekten)', fr:'Insectes auxiliaires'}, def:{es:'Especies introducidas o favorecidas deliberadamente porque depredan o parasitan plagas.', en:'Species deliberately introduced or favored because they prey on or parasitize pests.', de:'Arten, die gezielt eingeführt oder gefördert werden, weil sie Schädlinge erbeuten oder parasitieren.', fr:'Espèces introduites ou favorisées délibérément parce qu’elles prédatent ou parasitent les nuisibles.'}},
  {term:{es:'Intensidad lumínica', en:'Light intensity', de:'Lichtintensität', fr:'Intensité lumineuse'}, def:{es:'La fuerza de luz que llega a la planta, medida vía PPFD.', en:'The strength of light reaching the plant, measured via PPFD.', de:'Die Stärke des Lichts, das die Pflanze erreicht, gemessen über PPFD.', fr:'La force de la lumière atteignant la plante, mesurée via le PPFD.'}},
  {term:{es:'Intercambio de aire', en:'Air exchange', de:'Luftaustausch', fr:'Échange d’air'}, def:{es:'Reemplazar el aire del espacio de cultivo con aire nuevo, renovando CO2 y regulando temperatura/humedad.', en:'Replacing the air in the grow space with fresh air, renewing CO2 and regulating temperature/humidity.', de:'Das Ersetzen der Luft im Anbauraum durch Frischluft, wodurch CO2 erneuert und Temperatur/Luftfeuchtigkeit reguliert werden.', fr:'Remplacer l’air de l’espace de culture par de l’air neuf, renouvelant le CO2 et régulant la température/l’humidité.'}},
  {term:{es:'Interior (Indoor)', en:'Indoor', de:'Indoor', fr:'Intérieur (Indoor)'}, def:{es:'Cultivo realizado completamente bajo techo, con control total del ambiente (luz artificial, temperatura, humedad, CO2).', en:'Cultivation carried out entirely indoors, with full control over the environment (artificial light, temperature, humidity, CO2).', de:'Anbau, der vollständig drinnen erfolgt, mit vollständiger Kontrolle über die Umgebung (Kunstlicht, Temperatur, Luftfeuchtigkeit, CO2).', fr:'Culture réalisée entièrement à l’intérieur, avec un contrôle total de l’environnement (lumière artificielle, température, humidité, CO2).'}},
  {term:{es:'Inundación y drenaje (Flood and drain)', en:'Flood and drain', de:'Flut- und Drainagesystem (Flood and drain)', fr:'Inondation et drainage (Flood and drain)'}, def:{es:'Sinónimo técnico de "Ebb and flow" — mismo principio de inundación periódica seguida de drenaje.', en:'A technical synonym for "Ebb and flow" — the same principle of periodic flooding followed by drainage.', de:'Ein technisches Synonym für "Ebb and flow" — dasselbe Prinzip der periodischen Flutung, gefolgt von Drainage.', fr:'Synonyme technique de « Ebb and flow » — même principe d’inondation périodique suivie d’un drainage.'}},
  {term:{es:'Invernadero (Greenhouse)', en:'Greenhouse', de:'Gewächshaus', fr:'Serre'}, def:{es:'Estructura con cobertura translúcida que aprovecha la luz solar natural mientras permite cierto control ambiental.', en:'A structure with a translucent covering that makes use of natural sunlight while allowing some environmental control.', de:'Eine Struktur mit lichtdurchlässiger Abdeckung, die natürliches Sonnenlicht nutzt und gleichzeitig eine gewisse Umweltkontrolle ermöglicht.', fr:'Structure à couverture translucide qui exploite la lumière solaire naturelle tout en permettant un certain contrôle environnemental.'}},
  {term:{es:'Invernadero de arco (Hoop greenhouse)', en:'Hoop greenhouse', de:'Bogen-Gewächshaus (Hoop greenhouse)', fr:'Serre en arceaux (Hoop greenhouse)'}, def:{es:'Variante del hoop house con mayor sellado, término usado indistintamente según la región.', en:'A variant of the hoop house with tighter sealing; the term is used interchangeably depending on the region.', de:'Eine Variante des Folientunnels mit stärkerer Abdichtung; der Begriff wird je nach Region synonym verwendet.', fr:'Variante de la serre tunnel avec une meilleure étanchéité ; le terme est utilisé indifféremment selon la région.'}},
  {term:{es:'Invernadero tipo túnel (Hoop house)', en:'Hoop house', de:'Folientunnel (Hoop house)', fr:'Serre tunnel (Hoop house)'}, def:{es:'Estructura de bajo costo con arcos cubiertos con plástico, protección climática básica.', en:'A low-cost structure of plastic-covered arches, providing basic weather protection.', de:'Eine kostengünstige Struktur aus mit Folie bedeckten Bögen, die grundlegenden Witterungsschutz bietet.', fr:'Structure à faible coût composée d’arceaux recouverts de plastique, offrant une protection climatique basique.'}},
  {term:{es:'IPM (Manejo Integrado de Plagas)', en:'IPM (Integrated Pest Management)', de:'IPM (Integriertes Schädlingsmanagement)', fr:'IPM (Lutte intégrée contre les nuisibles)'}, def:{es:'Estrategia que combina métodos biológicos, culturales, físicos y químicos (como último recurso), priorizando prevención y monitoreo continuo.', en:'A strategy that combines biological, cultural, physical, and chemical methods (as a last resort), prioritizing prevention and continuous monitoring.', de:'Eine Strategie, die biologische, kulturelle, physikalische und chemische Methoden (als letztes Mittel) kombiniert und Prävention sowie kontinuierliches Monitoring priorisiert.', fr:'Stratégie combinant des méthodes biologiques, culturales, physiques et chimiques (en dernier recours), donnant la priorité à la prévention et à la surveillance continue.'}},
  {term:{es:'Keeper', en:'Keeper', de:'Keeper', fr:'Keeper'}, def:{es:'El fenotipo seleccionado en una búsqueda de fenotipos, para conservarse como planta madre.', en:'The phenotype selected from a pheno hunt to be kept as a mother plant.', de:'Der beim Pheno Hunting ausgewählte Phänotyp, der als Mutterpflanze erhalten wird.', fr:'Le phénotype sélectionné lors d’une chasse aux phénotypes, destiné à être conservé comme plante mère.'}},
  {term:{es:'Kief', en:'Kief', de:'Kief', fr:'Kief'}, def:{es:'Los tricomas sueltos, tamizados en seco de la flor.', en:'Loose trichomes, dry-sifted from the flower.', de:'Lose Trichome, trocken aus der Blüte gesiebt.', fr:'Trichomes détachés, tamisés à sec depuis la fleur.'}},
  {term:{es:'Lana de roca (Rockwool)', en:'Rockwool', de:'Steinwolle', fr:'Laine de roche'}, def:{es:'Sustrato inerte de roca volcánica fundida e hilada — buena retención de agua y aireación; requiere pre-acondicionamiento de pH porque es naturalmente alcalina.', en:'An inert substrate made from melted and spun volcanic rock — good water retention and aeration; requires pH pre-conditioning because it is naturally alkaline.', de:'Ein inertes Substrat aus geschmolzenem und versponnenem vulkanischem Gestein — gute Wasserretention und Belüftung; erfordert eine pH-Vorkonditionierung, da es von Natur aus alkalisch ist.', fr:'Substrat inerte fabriqué à partir de roche volcanique fondue et filée — bonne rétention d’eau et aération ; nécessite un préconditionnement du pH car il est naturellement alcalin.'}},
  {term:{es:'Landrace', en:'Landrace', de:'Landrasse', fr:'Landrace'}, def:{es:'Una variedad tradicional, adaptada durante generaciones a una región específica, sin cruces modernos.', en:'A traditional variety, adapted over generations to a specific region, without modern crossbreeding.', de:'Eine traditionelle Sorte, die über Generationen an eine bestimmte Region angepasst wurde, ohne moderne Kreuzungen.', fr:'Une variété traditionnelle, adaptée au fil des générations à une région spécifique, sans croisements modernes.'}},
  {term:{es:'LEC (Cerámica de emisión luminosa)', en:'LEC (Light Emitting Ceramic)', de:'LEC (Lichtemittierende Keramik)', fr:'LEC (Céramique électroluminescente)'}, def:{es:'Nombre comercial (marca de Sun System) para la misma tecnología que el CMH; ambos términos se usan indistintamente en la industria.', en:'A commercial name (a Sun System brand) for the same technology as CMH; both terms are used interchangeably in the industry.', de:'Ein Markenname (von Sun System) für dieselbe Technologie wie CMH; beide Begriffe werden in der Branche synonym verwendet.', fr:'Nom commercial (marque de Sun System) pour la même technologie que le CMH ; les deux termes sont utilisés indifféremment dans l’industrie.'}},
  {term:{es:'LED', en:'LED', de:'LED', fr:'LED'}, def:{es:'Diodo emisor de luz, tecnología de estado sólido, estándar dominante en cultivo indoor por eficiencia energética y ajuste de espectro.', en:'Light-emitting diode, a solid-state technology, the dominant standard in indoor cultivation for its energy efficiency and spectrum tunability.', de:'Leuchtdiode, eine Festkörpertechnologie, der dominierende Standard im Indoor-Anbau aufgrund ihrer Energieeffizienz und Spektrumsanpassung.', fr:'Diode électroluminescente, technologie à semi-conducteurs, norme dominante en culture indoor pour son efficacité énergétique et son spectre ajustable.'}},
  {term:{es:'Limoneno', en:'Limonene', de:'Limonen', fr:'Limonène'}, def:{es:'Aroma cítrico. Evidencia preclínica sugiere propiedades ansiolíticas y antioxidantes.', en:'Citrus aroma. Preclinical evidence suggests anxiolytic and antioxidant properties.', de:'Zitrusartiges Aroma. Präklinische Hinweise deuten auf angstlösende und antioxidative Eigenschaften hin.', fr:'Arôme d’agrumes. Des données précliniques suggèrent des propriétés anxiolytiques et antioxydantes.'}},
  {term:{es:'Linalool', en:'Linalool', de:'Linalool', fr:'Linalol'}, def:{es:'Aroma floral (también en lavanda), el más estudiado en propiedades relajantes/sedantes y como posible antinociceptivo.', en:'Floral aroma (also found in lavender), the most studied for relaxing/sedative properties and as a possible antinociceptive.', de:'Blumiges Aroma (auch in Lavendel enthalten), am besten erforscht hinsichtlich entspannender/beruhigender Eigenschaften und als möglicher Antinozizeptivum.', fr:'Arôme floral (également présent dans la lavande), le plus étudié pour ses propriétés relaxantes/sédatives et comme antinociceptif potentiel.'}},
  {term:{es:'Línea de secado (Drying line)', en:'Drying line', de:'Trockenleine (Drying line)', fr:'Ligne de séchage (Drying line)'}, def:{es:'Cuerda tendida horizontalmente de la que se cuelgan ramas completas — típico del "hang dry".', en:'A horizontally strung line from which whole branches are hung — typical of "hang drying."', de:'Eine horizontal gespannte Leine, an der ganze Zweige aufgehängt werden — typisch für das "Hang Drying".', fr:'Corde tendue horizontalement à laquelle sont suspendues des branches entières — typique du « hang dry ».'}},
  {term:{es:'Línea genética de semillas (Seed line)', en:'Seed line', de:'Samenlinie', fr:'Lignée de graines'}, def:{es:'Un linaje de semillas mantenido y desarrollado por un breeder, con historial documentado.', en:'A seed lineage maintained and developed by a breeder, with a documented history.', de:'Eine Samenlinie, die von einem Züchter gepflegt und entwickelt wird, mit dokumentierter Geschichte.', fr:'Une lignée de graines entretenue et développée par un sélectionneur, avec un historique documenté.'}},
  {term:{es:'Live resin', en:'Live resin', de:'Live Resin', fr:'Live resin'}, def:{es:'Concentrado hecho con planta fresca congelada, nunca secada ni curada.', en:'A concentrate made from freshly frozen plant material, never dried or cured.', de:'Ein Konzentrat aus frisch gefrorenem Pflanzenmaterial, nie getrocknet oder gereift.', fr:'Concentré fabriqué à partir de plante fraîche congelée, jamais séchée ni affinée.'}},
  {term:{es:'Lollipopping', en:'Lollipopping', de:'Lollipopping', fr:'Lollipopping'}, def:{es:'Remover follaje y ramas de la parte inferior de la planta, concentrando energía en las colas superiores.', en:'Removing foliage and branches from the lower part of the plant, concentrating energy in the upper colas.', de:'Entfernen von Laub und Zweigen im unteren Bereich der Pflanze, um die Energie auf die oberen Colas zu konzentrieren.', fr:'Retirer le feuillage et les branches de la partie inférieure de la plante, concentrant l’énergie sur les colas supérieures.'}},
  {term:{es:'LST (Entrenamiento de bajo estrés)', en:'LST (Low-Stress Training)', de:'LST (Low-Stress Training)', fr:'LST (Entraînement à faible stress)'}, def:{es:'Técnicas de doblado y atado de ramas sin cortes, para un dosel plano y uniforme sin dañar tejido.', en:'Bending and tying techniques for branches without cutting, to create a flat, even canopy without damaging tissue.', de:'Biege- und Bindetechniken für Zweige ohne Schnitte, um ein flaches, gleichmäßiges Blätterdach ohne Gewebeschäden zu erzeugen.', fr:'Techniques de courbure et d’attache des branches sans coupe, pour obtenir une canopée plate et uniforme sans endommager les tissus.'}},
  {term:{es:'Luz de cultivo (Grow light)', en:'Grow light', de:'Wachstumslicht (Grow Light)', fr:'Lampe de culture (Grow light)'}, def:{es:'Término general para cualquier fuente de luz artificial diseñada para suplementar o reemplazar la luz solar en el crecimiento de plantas.', en:'A general term for any artificial light source designed to supplement or replace sunlight in plant growth.', de:'Ein allgemeiner Begriff für jede künstliche Lichtquelle, die dazu dient, Sonnenlicht beim Pflanzenwachstum zu ergänzen oder zu ersetzen.', fr:'Terme général désignant toute source de lumière artificielle conçue pour compléter ou remplacer la lumière du soleil dans la croissance des plantes.'}},
  {term:{es:'Luz mixta (Mixed-light)', en:'Mixed-light', de:'Mischlicht', fr:'Lumière mixte'}, def:{es:'Sistema que combina luz solar natural con suplementación artificial, para extender horas de luz o mantener intensidad en días nublados.', en:'A system that combines natural sunlight with artificial supplementation, to extend light hours or maintain intensity on cloudy days.', de:'Ein System, das natürliches Sonnenlicht mit künstlicher Zusatzbeleuchtung kombiniert, um die Lichtstunden zu verlängern oder die Intensität an bewölkten Tagen aufrechtzuerhalten.', fr:'Système combinant la lumière solaire naturelle à un éclairage artificiel d’appoint, afin de prolonger les heures de lumière ou de maintenir l’intensité les jours nuageux.'}},
  {term:{es:'Macho', en:'Male plant', de:'Männliche Pflanze', fr:'Plante mâle'}, def:{es:'Planta que produce polen — necesaria para la reproducción sexual pero generalmente eliminada en cultivos de flor comercial para evitar polinización no deseada.', en:'A plant that produces pollen — necessary for sexual reproduction but generally removed from commercial flower crops to prevent unwanted pollination.', de:'Eine Pflanze, die Pollen produziert — notwendig für die sexuelle Fortpflanzung, wird aber in kommerziellen Blütenkulturen meist entfernt, um unerwünschte Bestäubung zu vermeiden.', fr:'Plante qui produit du pollen — nécessaire à la reproduction sexuée, mais généralement éliminée des cultures de fleurs commerciales pour éviter une pollinisation indésirable.'}},
  {term:{es:'Macronutrientes', en:'Macronutrients', de:'Makronährstoffe', fr:'Macronutriments'}, def:{es:'Elementos que la planta requiere en cantidades relativamente grandes: nitrógeno, fósforo, potasio (primarios) y calcio, magnesio, azufre (secundarios).', en:'Elements the plant requires in relatively large amounts: nitrogen, phosphorus, potassium (primary) and calcium, magnesium, sulfur (secondary).', de:'Elemente, die die Pflanze in relativ großen Mengen benötigt: Stickstoff, Phosphor, Kalium (primär) sowie Calcium, Magnesium, Schwefel (sekundär).', fr:'Éléments dont la plante a besoin en quantités relativement importantes : azote, phosphore, potassium (primaires) et calcium, magnésium, soufre (secondaires).'}},
  {term:{es:'Maduración (Ripening/Maturation)', en:'Ripening/Maturation', de:'Reifung (Ripening/Maturation)', fr:'Maturation (Ripening/Maturation)'}, def:{es:'La fase final de floración, donde cannabinoides y terpenos alcanzan su punto máximo y tricomas/pistilos cambian de color, señalando el momento óptimo de cosecha.', en:'The final flowering phase, where cannabinoids and terpenes reach their peak and trichomes/pistils change color, signaling the optimal harvest time.', de:'Die letzte Blütephase, in der Cannabinoide und Terpene ihren Höhepunkt erreichen und Trichome/Stempel die Farbe wechseln, was den optimalen Erntezeitpunkt anzeigt.', fr:'La phase finale de la floraison, où les cannabinoïdes et les terpènes atteignent leur pic et où les trichomes/pistils changent de couleur, signalant le moment optimal de récolte.'}},
  {term:{es:'Madurez de tricomas', en:'Trichome maturity', de:'Trichomreife', fr:'Maturité des trichomes'}, def:{es:'El indicador visual más usado para cosechar: transparente (inmaduro) → lechoso (pico de THC) → ámbar (más CBN, efecto sedante), evaluado con lupa o microscopio 60x-100x.', en:'The most widely used visual indicator for harvesting: clear (immature) → milky (THC peak) → amber (more CBN, sedating effect), assessed with a loupe or 60x-100x microscope.', de:'Der am häufigsten verwendete visuelle Erntehinweis: klar (unreif) → milchig (THC-Höhepunkt) → bernsteinfarben (mehr CBN, beruhigende Wirkung), bewertet mit einer Lupe oder einem 60x-100x-Mikroskop.', fr:'L’indicateur visuel le plus utilisé pour la récolte : transparent (immature) → laiteux (pic de THC) → ambré (plus de CBN, effet sédatif), évalué à la loupe ou au microscope 60x-100x.'}},
  {term:{es:'Magnesio (Mg)', en:'Magnesium (Mg)', de:'Magnesium (Mg)', fr:'Magnésium (Mg)'}, def:{es:'Macronutriente secundario, componente central de la clorofila — su deficiencia produce clorosis internerval en hojas viejas.', en:'A secondary macronutrient, the central component of chlorophyll — its deficiency causes interveinal chlorosis in older leaves.', de:'Ein sekundärer Makronährstoff und zentraler Bestandteil des Chlorophylls — sein Mangel verursacht interveinale Chlorose in älteren Blättern.', fr:'Macronutriment secondaire, composant central de la chlorophylle — sa carence provoque une chlorose internervaire sur les feuilles anciennes.'}},
  {term:{es:'Mainlining', en:'Mainlining', de:'Mainlining', fr:'Mainlining'}, def:{es:'Topping repetido en etapas tempranas combinado con LST, para crear una estructura simétrica de ramas ("manifold").', en:'Repeated topping at early stages combined with LST, to create a symmetrical branch structure (a "manifold").', de:'Wiederholtes Topping in frühen Stadien kombiniert mit LST, um eine symmetrische Zweigstruktur ("Manifold") zu schaffen.', fr:'Topping répété à un stade précoce combiné au LST, pour créer une structure de branches symétrique (un « manifold »).'}},
  {term:{es:'Manejo del dosel (Canopy management)', en:'Canopy management', de:'Bestandsführung (Canopy management)', fr:'Gestion de la canopée (Canopy management)'}, def:{es:'Término general para todas las técnicas dirigidas a controlar forma, densidad y uniformidad del dosel.', en:'A general term for all techniques aimed at controlling the shape, density, and uniformity of the canopy.', de:'Ein allgemeiner Begriff für alle Techniken, die darauf abzielen, Form, Dichte und Gleichmäßigkeit des Blätterdachs zu steuern.', fr:'Terme général désignant l’ensemble des techniques visant à contrôler la forme, la densité et l’uniformité de la canopée.'}},
  {term:{es:'Manganeso (Mn)', en:'Manganese (Mn)', de:'Mangan (Mn)', fr:'Manganèse (Mn)'}, def:{es:'Micronutriente involucrado en fotosíntesis y activación de enzimas.', en:'A micronutrient involved in photosynthesis and enzyme activation.', de:'Ein Mikronährstoff, der an der Photosynthese und der Enzymaktivierung beteiligt ist.', fr:'Micronutriment impliqué dans la photosynthèse et l’activation enzymatique.'}},
  {term:{es:'Manicura húmeda (Wet trim)', en:'Wet trim', de:'Nassmanikür (Wet trim)', fr:'Taille humide (Wet trim)'}, def:{es:'Manicurado inmediatamente después de la cosecha, antes de secar — hojas más fáciles de remover, pero requiere más espacio de secado.', en:'Trimming immediately after harvest, before drying — leaves are easier to remove, but requires more drying space.', de:'Trimmen unmittelbar nach der Ernte, vor der Trocknung — Blätter lassen sich leichter entfernen, erfordert jedoch mehr Trockenraum.', fr:'Taille effectuée immédiatement après la récolte, avant le séchage — les feuilles sont plus faciles à retirer, mais nécessite plus d’espace de séchage.'}},
  {term:{es:'Manicura manual (Hand trim)', en:'Hand trim', de:'Handtrimmen (Hand trim)', fr:'Taille manuelle (Hand trim)'}, def:{es:'Manicurado a mano con tijeras — mayor calidad/cuidado, pero más lento y costoso.', en:'Trimming by hand with scissors — higher quality/care, but slower and more costly.', de:'Von Hand mit einer Schere durchgeführtes Trimmen — höhere Qualität/Sorgfalt, aber langsamer und teurer.', fr:'Taille effectuée à la main aux ciseaux — meilleure qualité/soin, mais plus lente et plus coûteuse.'}},
  {term:{es:'Manicura mecánica (Machine trim)', en:'Machine trim', de:'Maschinentrimmen (Machine trim)', fr:'Taille mécanique (Machine trim)'}, def:{es:'Manicurado con máquinas especializadas — más rápido y económico, pero puede perder más tricomas.', en:'Trimming with specialized machines — faster and more economical, but can strip away more trichomes.', de:'Trimmen mit spezialisierten Maschinen — schneller und wirtschaftlicher, kann aber mehr Trichome entfernen.', fr:'Taille effectuée avec des machines spécialisées — plus rapide et économique, mais peut arracher davantage de trichomes.'}},
  {term:{es:'Manicura seca (Dry trim)', en:'Dry trim', de:'Trockenmanikür (Dry trim)', fr:'Taille sèche (Dry trim)'}, def:{es:'Manicurado después del secado completo — las hojas secas protegen la flor durante el secado, aunque el recorte es más laborioso.', en:'Trimming after drying is complete — dry leaves protect the flower during drying, though the trimming itself is more labor-intensive.', de:'Trimmen nach abgeschlossener Trocknung — trockene Blätter schützen die Blüte während der Trocknung, wobei der Trimmvorgang selbst arbeitsintensiver ist.', fr:'Taille effectuée après séchage complet — les feuilles sèches protègent la fleur pendant le séchage, bien que la coupe soit plus laborieuse.'}},
  {term:{es:'Manifolding', en:'Manifolding', de:'Manifolding', fr:'Manifolding'}, def:{es:'Esencialmente sinónimo de mainlining — se refiere a la estructura ramificada resultante.', en:'Essentially a synonym for mainlining — refers to the resulting branched structure.', de:'Im Wesentlichen ein Synonym für Mainlining — bezieht sich auf die daraus resultierende verzweigte Struktur.', fr:'Essentiellement synonyme de mainlining — désigne la structure ramifiée qui en résulte.'}},
  {term:{es:'Mano de obra de cosecha (Harvest labor)', en:'Harvest labor', de:'Erntearbeit (Harvest labor)', fr:'Main-d’œuvre de récolte (Harvest labor)'}, def:{es:'El trabajo humano requerido durante la cosecha — una de las etapas más intensivas en mano de obra del ciclo.', en:'The human labor required during harvest — one of the most labor-intensive stages of the cycle.', de:'Die während der Ernte erforderliche menschliche Arbeit — eine der arbeitsintensivsten Phasen des Zyklus.', fr:'Le travail humain requis pendant la récolte — l’une des étapes les plus intensives en main-d’œuvre du cycle.'}},
  {term:{es:'Material parental (Breeding stock)', en:'Breeding stock', de:'Zuchtmaterial', fr:'Stock de sélection'}, def:{es:'El conjunto de plantas mantenidas específicamente como base genética para un programa de mejoramiento.', en:'The set of plants kept specifically as the genetic base for a breeding program.', de:'Die Gesamtheit der Pflanzen, die gezielt als genetische Grundlage für ein Zuchtprogramm gehalten werden.', fr:'L’ensemble des plantes maintenues spécifiquement comme base génétique pour un programme de sélection.'}},
  {term:{es:'Medidor de humedad (Moisture meter)', en:'Moisture meter', de:'Feuchtigkeitsmessgerät (Moisture meter)', fr:'Humidimètre (Moisture meter)'}, def:{es:'Instrumento para medir el contenido de humedad de la flor, por sonda o capacitancia.', en:'An instrument for measuring the moisture content of flower, via probe or capacitance.', de:'Ein Instrument zur Messung des Feuchtigkeitsgehalts der Blüte, per Sonde oder Kapazitätsmessung.', fr:'Instrument permettant de mesurer la teneur en humidité de la fleur, par sonde ou par capacité.'}},
  {term:{es:'Medio de cultivo (Growing medium)', en:'Growing medium', de:'Anzuchtmedium (Growing medium)', fr:'Milieu de culture (Growing medium)'}, def:{es:'Sinónimo de "sustrato" — el material físico que sostiene a la planta y su sistema radicular.', en:'A synonym for "substrate" — the physical material that supports the plant and its root system.', de:'Ein Synonym für "Substrat" — das physische Material, das die Pflanze und ihr Wurzelsystem trägt.', fr:'Synonyme de « substrat » — le matériau physique qui soutient la plante et son système racinaire.'}},
  {term:{es:'Medio de enraizamiento (Rooting media)', en:'Rooting media', de:'Bewurzelungsmedium', fr:'Substrat d’enracinement'}, def:{es:'El sustrato específico donde se coloca un esqueje mientras enraíza.', en:'The specific substrate a cutting is placed in while it roots.', de:'Das spezifische Substrat, in das ein Steckling während der Bewurzelung gesetzt wird.', fr:'Le substrat spécifique dans lequel une bouture est placée pendant son enracinement.'}},
  {term:{es:'Mejoramiento genético (Breeding)', en:'Breeding', de:'Züchtung', fr:'Sélection variétale'}, def:{es:'La práctica deliberada de seleccionar y cruzar plantas para desarrollar nuevas variedades con características específicas (potencia, resistencia, morfología, perfil terpénico).', en:'The deliberate practice of selecting and crossing plants to develop new varieties with specific traits (potency, resistance, morphology, terpene profile).', de:'Die gezielte Praxis, Pflanzen auszuwählen und zu kreuzen, um neue Sorten mit bestimmten Eigenschaften zu entwickeln (Potenz, Resistenz, Morphologie, Terpenprofil).', fr:'La pratique délibérée de sélectionner et de croiser des plantes pour développer de nouvelles variétés aux caractéristiques spécifiques (puissance, résistance, morphologie, profil terpénique).'}},
  {term:{es:'Meristemo apical', en:'Apical meristem', de:'Apikales Meristem', fr:'Méristème apical'}, def:{es:'Tejido de crecimiento activo en la punta de tallos y raíces, responsable de la elongación y la formación de nuevos órganos.', en:'The actively growing tissue at the tip of stems and roots, responsible for elongation and the formation of new organs.', de:'Das aktiv wachsende Gewebe an der Spitze von Stängeln und Wurzeln, verantwortlich für die Streckung und die Bildung neuer Organe.', fr:'Tissu de croissance active à l’extrémité des tiges et des racines, responsable de l’élongation et de la formation de nouveaux organes.'}},
  {term:{es:'Metabolismo de primer paso', en:'First-pass metabolism', de:'First-Pass-Metabolismus', fr:'Métabolisme de premier passage'}, def:{es:'El procesamiento hepático que reduce la potencia real de lo que se ingiere por vía oral.', en:'The liver processing that reduces the real potency of what is ingested orally.', de:'Die Leberverarbeitung, die die tatsächliche Potenz von oral Eingenommenem verringert.', fr:'Le traitement hépatique qui réduit la puissance réelle de ce qui est ingéré par voie orale.'}},
  {term:{es:'MH (Halogenuro metálico)', en:'MH (Metal Halide)', de:'MH (Halogen-Metalldampflampe)', fr:'MH (Halogénure métallique)'}, def:{es:'Tecnología de descarga de gas con espectro más azul/frío, tradicionalmente usada en vegetativo.', en:'A gas-discharge technology with a bluer/cooler spectrum, traditionally used during the vegetative stage.', de:'Eine Gasentladungstechnologie mit blauerem/kühlerem Spektrum, traditionell in der vegetativen Phase eingesetzt.', fr:'Technologie à décharge de gaz au spectre plus bleu/froid, traditionnellement utilisée en phase végétative.'}},
  {term:{es:'Microcultivo (Microgrow)', en:'Microgrow', de:'Mikroanbau (Microgrow)', fr:'Microculture (Microgrow)'}, def:{es:'Operación de muy pequeña escala, típicamente personal o artesanal.', en:'A very small-scale operation, typically personal or artisanal.', de:'Ein Betrieb in sehr kleinem Maßstab, typischerweise für den persönlichen Gebrauch oder handwerklich.', fr:'Opération de très petite échelle, typiquement personnelle ou artisanale.'}},
  {term:{es:'Micronutrientes', en:'Micronutrients', de:'Mikronährstoffe', fr:'Micronutriments'}, def:{es:'Elementos requeridos en cantidades muy pequeñas pero esenciales: hierro, manganeso, zinc, cobre, boro y molibdeno.', en:'Elements required in very small but essential amounts: iron, manganese, zinc, copper, boron, and molybdenum.', de:'Elemente, die in sehr kleinen, aber essenziellen Mengen benötigt werden: Eisen, Mangan, Zink, Kupfer, Bor und Molybdän.', fr:'Éléments requis en quantités très faibles mais essentielles : fer, manganèse, zinc, cuivre, bore et molybdène.'}},
  {term:{es:'Mildiu (Mildew)', en:'Mildew', de:'Mehltau (Mildew)', fr:'Mildiou (Mildew)'}, def:{es:'En inglés, "mildew" se usa a veces de forma imprecisa para referirse al oídio (powdery mildew). Técnicamente, "mildiu" en español corresponde al mildiu velloso (downy mildew), un organismo distinto — un oomiceto del mismo grupo que el Pythium, no un hongo verdadero como el oídio. Ver "Oídio" para el caso relevante en cannabis.', en:'In English, "mildew" is sometimes used imprecisely to mean powdery mildew. Technically, "mildew" on its own refers to downy mildew, a distinct organism — an oomycete from the same group as Pythium, not a true fungus like powdery mildew. See "Powdery mildew" for the relevant case in cannabis.', de:'Im Englischen wird "mildew" manchmal ungenau für den Echten Mehltau (powdery mildew) verwendet. Technisch bezeichnet "mildew" allein den Falschen Mehltau (downy mildew), einen anderen Organismus — ein Oomycet aus derselben Gruppe wie Pythium, kein echter Pilz wie der Echte Mehltau. Siehe "Echter Mehltau" für den relevanten Fall bei Cannabis.', fr:'En anglais, « mildew » est parfois utilisé de façon imprécise pour désigner l’oïdium (powdery mildew). Techniquement, « mildew » seul désigne le mildiou (downy mildew), un organisme distinct — un oomycète du même groupe que le Pythium, et non un vrai champignon comme l’oïdium. Voir « Oïdium » pour le cas pertinent chez le cannabis.'}},
  {term:{es:'Mirceno', en:'Myrcene', de:'Myrcen', fr:'Myrcène'}, def:{es:'El terpeno más abundante en la mayoría de variedades, aroma terroso/almizclado. Evidencia preclínica sugiere propiedades analgésicas y sedantes; su posible rol facilitando el paso de compuestos por la barrera hematoencefálica sigue en investigación activa.', en:'The most abundant terpene in most varieties, with an earthy/musky aroma. Preclinical evidence suggests analgesic and sedative properties; its possible role in facilitating compounds crossing the blood-brain barrier remains under active investigation.', de:'Das in den meisten Sorten am häufigsten vorkommende Terpen, mit erdigem/moschusartigem Aroma. Präklinische Hinweise deuten auf schmerzlindernde und sedierende Eigenschaften hin; seine mögliche Rolle beim Durchtritt von Verbindungen durch die Blut-Hirn-Schranke wird weiterhin aktiv erforscht.', fr:'Le terpène le plus abondant dans la plupart des variétés, à l’arôme terreux/musqué. Des données précliniques suggèrent des propriétés analgésiques et sédatives ; son rôle possible dans le passage de composés à travers la barrière hémato-encéphalique fait toujours l’objet de recherches actives.'}},
  {term:{es:'Moho (Mold)', en:'Mold', de:'Schimmel (Mold)', fr:'Moisissure (Mold)'}, def:{es:'Término general para hongos filamentosos sobre materia orgánica — preocupación tanto en planta (Botrytis) como en producto curado mal almacenado.', en:'A general term for filamentous fungi on organic matter — a concern both on the living plant (Botrytis) and in poorly stored cured product.', de:'Ein allgemeiner Begriff für fadenförmige Pilze auf organischem Material — ein Problem sowohl an der lebenden Pflanze (Botrytis) als auch bei schlecht gelagertem, ausgehärtetem Produkt.', fr:'Terme général pour les champignons filamenteux sur matière organique — préoccupation aussi bien sur la plante (Botrytis) que sur le produit affiné mal stocké.'}},
  {term:{es:'Molibdeno (Mo)', en:'Molybdenum (Mo)', de:'Molybdän (Mo)', fr:'Molybdène (Mo)'}, def:{es:'Micronutriente esencial en el metabolismo del nitrógeno, particularmente en conversión de nitratos.', en:'A micronutrient essential in nitrogen metabolism, particularly in nitrate conversion.', de:'Ein Mikronährstoff, der für den Stickstoffwechsel essenziell ist, insbesondere bei der Nitratumwandlung.', fr:'Micronutriment essentiel au métabolisme de l’azote, en particulier dans la conversion des nitrates.'}},
  {term:{es:'Monitoreo ambiental', en:'Environmental monitoring', de:'Umweltüberwachung', fr:'Surveillance environnementale'}, def:{es:'El seguimiento continuo de las variables ambientales, manual o automatizado.', en:'The continuous tracking of environmental variables, either manual or automated.', de:'Die kontinuierliche Verfolgung von Umweltvariablen, manuell oder automatisiert.', fr:'Le suivi continu des variables environnementales, manuel ou automatisé.'}},
  {term:{es:'Monitoreo de plagas (Pest scouting)', en:'Pest scouting', de:'Schädlingsmonitoring (Pest scouting)', fr:'Surveillance des nuisibles (Pest scouting)'}, def:{es:'Inspección regular y sistemática del cultivo para detectar tempranamente plagas o patógenos.', en:'A regular, systematic inspection of the crop to detect pests or pathogens early.', de:'Eine regelmäßige, systematische Inspektion der Kultur, um Schädlinge oder Krankheitserreger frühzeitig zu erkennen.', fr:'Inspection régulière et systématique de la culture pour détecter précocement des nuisibles ou des pathogènes.'}},
  {term:{es:'Mosca blanca', en:'Whitefly', de:'Weiße Fliege', fr:'Aleurode (mouche blanche)'}, def:{es:'Insecto de alas blancas que se alimenta de savia y puede transmitir virus; se encuentra en el envés de las hojas.', en:'A white-winged insect that feeds on sap and can transmit viruses; found on the underside of leaves.', de:'Ein weißflügeliges Insekt, das sich von Saft ernährt und Viren übertragen kann; findet sich auf der Blattunterseite.', fr:'Insecte aux ailes blanches qui se nourrit de sève et peut transmettre des virus ; se trouve sous les feuilles.'}},
  {term:{es:'Mosquito de los hongos (Fungus gnat)', en:'Fungus gnat', de:'Trauermücke (Fungus gnat)', fr:'Moucheron des champignons (Fungus gnat)'}, def:{es:'Insecto cuyas larvas se desarrollan en sustratos húmedos — su presencia indica exceso de humedad.', en:'An insect whose larvae develop in damp substrates — its presence indicates excess moisture.', de:'Ein Insekt, dessen Larven sich in feuchten Substraten entwickeln — sein Auftreten weist auf übermäßige Feuchtigkeit hin.', fr:'Insecte dont les larves se développent dans des substrats humides — sa présence indique un excès d’humidité.'}},
  {term:{es:'Nanoemulsión', en:'Nanoemulsion', de:'Nanoemulsion', fr:'Nanoémulsion'}, def:{es:'Técnica que reduce partículas de cannabinoide a escala nanométrica para disolverlas en líquidos.', en:'A technique that reduces cannabinoid particles to nanoscale so they dissolve in liquids.', de:'Eine Technik, die Cannabinoidpartikel auf Nanogröße reduziert, damit sie sich in Flüssigkeiten lösen.', fr:'Technique réduisant les particules de cannabinoïde à l’échelle nanométrique pour les dissoudre dans des liquides.'}},
  {term:{es:'Nerolidol', en:'Nerolidol', de:'Nerolidol', fr:'Nérolidol'}, def:{es:'Aroma floral/leñoso con notas cítricas. Estudiado por aumentar la permeabilidad de la piel (interés para formulaciones tópicas) y posibles propiedades sedantes.', en:'Floral/woody aroma with citrus notes. Studied for increasing skin permeability (of interest for topical formulations) and possible sedative properties.', de:'Blumig-holziges Aroma mit Zitrusnoten. Untersucht wegen erhöhter Hautdurchlässigkeit (von Interesse für topische Formulierungen) und möglicher sedierender Eigenschaften.', fr:'Arôme floral/boisé aux notes d’agrumes. Étudié pour l’augmentation de la perméabilité cutanée (intéressant pour les formulations topiques) et ses propriétés sédatives potentielles.'}},
  {term:{es:'Nitrógeno (N)', en:'Nitrogen (N)', de:'Stickstoff (N)', fr:'Azote (N)'}, def:{es:'Macronutriente primario esencial para crecimiento vegetativo, clave en clorofila y proteínas — su deficiencia amarillea primero las hojas viejas.', en:'A primary macronutrient essential for vegetative growth, key in chlorophyll and proteins — its deficiency yellows the older leaves first.', de:'Ein primärer Makronährstoff, der für das vegetative Wachstum essenziell ist und eine Schlüsselrolle in Chlorophyll und Proteinen spielt — sein Mangel lässt zuerst die älteren Blätter vergilben.', fr:'Macronutriment primaire essentiel à la croissance végétative, clé dans la chlorophylle et les protéines — sa carence jaunit d’abord les feuilles les plus anciennes.'}},
  {term:{es:'Nudo (Node)', en:'Node', de:'Knoten', fr:'Nœud'}, def:{es:'Punto del tallo donde emergen hojas, ramas o brotes florales.', en:'The point on the stem where leaves, branches, or floral shoots emerge.', de:'Der Punkt am Stängel, an dem Blätter, Äste oder Blütentriebe entspringen.', fr:'Point de la tige d’où émergent les feuilles, les branches ou les pousses florales.'}},
  {term:{es:'Ocimeno', en:'Ocimene', de:'Ocimen', fr:'Ocimène'}, def:{es:'Aroma dulce/herbal, en menor concentración — menos estudiado individualmente.', en:'Sweet/herbal aroma, present in lower concentration — less studied individually.', de:'Süßliches/krautiges Aroma, in geringerer Konzentration vorhanden — einzeln weniger erforscht.', fr:'Arôme sucré/herbacé, présent en plus faible concentration — moins étudié individuellement.'}},
  {term:{es:'Oídio (Powdery Mildew)', en:'Powdery mildew', de:'Echter Mehltau (Powdery Mildew)', fr:'Oïdium (Powdery Mildew)'}, def:{es:'Enfermedad fúngica con polvo blanco superficial sobre hojas y flores — muy común y de fácil propagación por esporas transportadas por aire.', en:'A fungal disease with a superficial white powder on leaves and flowers — very common and easily spread by airborne spores.', de:'Eine Pilzkrankheit mit oberflächlichem weißem Belag auf Blättern und Blüten — sehr verbreitet und leicht durch luftübertragene Sporen verbreitet.', fr:'Maladie fongique se manifestant par une poudre blanche superficielle sur les feuilles et les fleurs — très courante et se propageant facilement par des spores transportées par l’air.'}},
  {term:{es:'Oruga', en:'Caterpillar', de:'Raupe', fr:'Chenille'}, def:{es:'Larva de mariposa/polilla que se alimenta de hojas y puede perforar flores, elevando el riesgo de moho.', en:'The larva of a butterfly/moth that feeds on leaves and can bore into flowers, raising the risk of mold.', de:'Die Larve eines Schmetterlings/einer Motte, die sich von Blättern ernährt und in Blüten bohren kann, was das Schimmelrisiko erhöht.', fr:'Larve de papillon (diurne ou nocturne) qui se nourrit de feuilles et peut perforer les fleurs, augmentant le risque de moisissure.'}},
  {term:{es:'Óxido de cariofileno', en:'Caryophyllene oxide', de:'Caryophyllenoxid', fr:'Oxyde de caryophyllène'}, def:{es:'Forma oxidada del beta-cariofileno — pierde la capacidad de unión directa al CB2 que sí tiene el cariofileno original.', en:'The oxidized form of beta-caryophyllene — it loses the direct CB2 binding capacity that the original caryophyllene has.', de:'Die oxidierte Form von Beta-Caryophyllen — sie verliert die direkte CB2-Bindungsfähigkeit, die das ursprüngliche Caryophyllen besitzt.', fr:'Forme oxydée du bêta-caryophyllène — perd la capacité de liaison directe au CB2 que possède le caryophyllène d’origine.'}},
  {term:{es:'PAR (Radiación fotosintéticamente activa)', en:'PAR (Photosynthetically Active Radiation)', de:'PAR (Photosynthetisch aktive Strahlung)', fr:'PAR (Rayonnement photosynthétiquement actif)'}, def:{es:'El rango de luz (~400-700nm) que las plantas usan para fotosíntesis.', en:'The range of light (~400-700nm) that plants use for photosynthesis.', de:'Der Lichtbereich (~400-700nm), den Pflanzen für die Photosynthese nutzen.', fr:'La plage de lumière (~400-700 nm) que les plantes utilisent pour la photosynthèse.'}},
  {term:{es:'Parasitoide', en:'Parasitoid', de:'Parasitoid', fr:'Parasitoïde'}, def:{es:'Organismo (generalmente avispas diminutas) cuyas larvas se desarrollan dentro/sobre un huésped, matándolo — distinto del parásito clásico porque el desenlace siempre es la muerte del huésped.', en:'An organism (usually tiny wasps) whose larvae develop inside/on a host, killing it — distinct from a classic parasite because the outcome is always the host’s death.', de:'Ein Organismus (meist winzige Wespen), dessen Larven sich im/am Wirt entwickeln und ihn dabei töten — im Unterschied zum klassischen Parasiten endet dies stets mit dem Tod des Wirts.', fr:'Organisme (généralement de minuscules guêpes) dont les larves se développent à l’intérieur/sur un hôte, le tuant — distinct du parasite classique car l’issue est toujours la mort de l’hôte.'}},
  {term:{es:'Partes por millón (PPM)', en:'Parts per million (PPM)', de:'Teile pro Million (PPM)', fr:'Parties par million (PPM)'}, def:{es:'Unidad de concentración (equivalente a mg/L) usada para expresar la fuerza de una solución nutritiva o los TDS.', en:'A unit of concentration (equivalent to mg/L) used to express the strength of a nutrient solution or TDS.', de:'Eine Konzentrationseinheit (entspricht mg/L), die verwendet wird, um die Stärke einer Nährlösung oder den TDS-Wert auszudrücken.', fr:'Unité de concentration (équivalente à mg/L) utilisée pour exprimer la force d’une solution nutritive ou les TDS.'}},
  {term:{es:'Patógeno', en:'Pathogen', de:'Pathogen (Krankheitserreger)', fr:'Pathogène'}, def:{es:'Cualquier organismo (hongo, bacteria, virus, viroide) capaz de causar enfermedad en la planta.', en:'Any organism (fungus, bacterium, virus, viroid) capable of causing disease in the plant.', de:'Jeder Organismus (Pilz, Bakterium, Virus, Viroid), der bei der Pflanze eine Krankheit verursachen kann.', fr:'Tout organisme (champignon, bactérie, virus, viroïde) capable de provoquer une maladie chez la plante.'}},
  {term:{es:'Perfil de terpenos', en:'Terpene profile', de:'Terpenprofil', fr:'Profil terpénique'}, def:{es:'El conjunto y proporciones de terpenos presentes en una variedad — junto al perfil de cannabinoides, uno de los dos ejes de clasificación por quimiovar.', en:'The set and proportions of terpenes present in a variety — along with the cannabinoid profile, one of the two classification axes for chemovar.', de:'Die Zusammensetzung und die Anteile der in einer Sorte vorhandenen Terpene — neben dem Cannabinoidprofil eine der beiden Klassifizierungsachsen für den Chemovar.', fr:'L’ensemble et les proportions des terpènes présents dans une variété — avec le profil cannabinoïde, l’un des deux axes de classification du chimiovar.'}},
  {term:{es:'Perlita', en:'Perlite', de:'Perlit', fr:'Perlite'}, def:{es:'Mineral volcánico expandido con calor, usado como aditivo de sustrato para mejorar drenaje y aireación de las raíces — no retiene nutrientes por sí mismo.', en:'A volcanic mineral expanded with heat, used as a substrate additive to improve drainage and root aeration — it does not retain nutrients on its own.', de:'Ein mit Hitze aufgeblähtes vulkanisches Mineral, das als Substratzusatz zur Verbesserung von Drainage und Wurzelbelüftung verwendet wird — es speichert selbst keine Nährstoffe.', fr:'Minéral volcanique expansé à la chaleur, utilisé comme additif de substrat pour améliorer le drainage et l’aération des racines — il ne retient pas les nutriments par lui-même.'}},
  {term:{es:'Peso fresco (Fresh weight)', en:'Fresh weight', de:'Frischgewicht', fr:'Poids frais'}, def:{es:'Sinónimo directo de "Peso húmedo" — el peso del material vegetal recién cosechado, sin deshidratar.', en:'A direct synonym for "Wet weight" — the weight of freshly harvested plant material, not yet dehydrated.', de:'Ein direktes Synonym für "Nassgewicht" — das Gewicht des frisch geernteten Pflanzenmaterials, noch nicht dehydriert.', fr:'Synonyme direct de « Poids humide » — le poids du matériel végétal fraîchement récolté, non encore déshydraté.'}},
  {term:{es:'Peso húmedo (Wet weight)', en:'Wet weight', de:'Nassgewicht', fr:'Poids humide'}, def:{es:'El peso de la planta/flor inmediatamente después de la cosecha, antes de secar — referencia inicial, no representa el rendimiento final.', en:'The weight of the plant/flower immediately after harvest, before drying — an initial reference, not representative of final yield.', de:'Das Gewicht der Pflanze/Blüte unmittelbar nach der Ernte, vor der Trocknung — ein erster Referenzwert, der nicht den endgültigen Ertrag darstellt.', fr:'Le poids de la plante/fleur immédiatement après la récolte, avant séchage — référence initiale, ne représentant pas le rendement final.'}},
  {term:{es:'Peso seco (Dry weight)', en:'Dry weight', de:'Trockengewicht', fr:'Poids sec'}, def:{es:'El peso de la flor después de completar el secado — la métrica estándar de la industria para reportar rendimiento.', en:'The weight of the flower after drying is complete — the industry-standard metric for reporting yield.', de:'Das Gewicht der Blüte nach abgeschlossener Trocknung — die branchenübliche Kennzahl zur Ertragsangabe.', fr:'Le poids de la fleur une fois le séchage terminé — la mesure standard de l’industrie pour communiquer le rendement.'}},
  {term:{es:'pH', en:'pH', de:'pH-Wert', fr:'pH'}, def:{es:'Medida de acidez/alcalinidad en escala 0-14, determina la disponibilidad de nutrientes — rango óptimo ~5.5-6.5 en hidroponía, ~6.0-7.0 en sustrato con tierra.', en:'A measure of acidity/alkalinity on a 0-14 scale, determining nutrient availability — optimal range ~5.5-6.5 in hydroponics, ~6.0-7.0 in soil-based substrate.', de:'Ein Maß für Säure/Basizität auf einer Skala von 0-14, das die Nährstoffverfügbarkeit bestimmt — optimaler Bereich ~5,5-6,5 in Hydroponik, ~6,0-7,0 in erdhaltigem Substrat.', fr:'Mesure de l’acidité/alcalinité sur une échelle de 0 à 14, déterminant la disponibilité des nutriments — plage optimale ~5,5-6,5 en hydroponie, ~6,0-7,0 en substrat terreux.'}},
  {term:{es:'Pistilo', en:'Pistil', de:'Pistill', fr:'Pistil'}, def:{es:'Estructura reproductiva femenina completa (ovario + estigmas). Popularmente se usa solo para los pelos visibles, aunque técnicamente incluye toda la estructura.', en:'The complete female reproductive structure (ovary + stigmas). Colloquially it’s used just for the visible hairs, though technically it includes the whole structure.', de:'Die vollständige weibliche Fortpflanzungsstruktur (Fruchtknoten + Narben). Umgangssprachlich wird der Begriff nur für die sichtbaren Härchen verwendet, obwohl er technisch die gesamte Struktur umfasst.', fr:'Structure reproductive femelle complète (ovaire + stigmates). Dans le langage courant, on l’emploie seulement pour les poils visibles, bien que techniquement il inclue toute la structure.'}},
  {term:{es:'Plaga (Pest)', en:'Pest', de:'Schädling (Pest)', fr:'Nuisible (Pest)'}, def:{es:'Cualquier organismo que causa daño económico o fisiológico significativo a un cultivo.', en:'Any organism that causes significant economic or physiological damage to a crop.', de:'Jeder Organismus, der einer Kultur einen erheblichen wirtschaftlichen oder physiologischen Schaden zufügt.', fr:'Tout organisme causant un dommage économique ou physiologique significatif à une culture.'}},
  {term:{es:'Planta madre', en:'Mother plant', de:'Mutterpflanze', fr:'Plante mère'}, def:{es:'Planta mantenida en fase vegetativa indefinida específicamente para producir clones genéticamente idénticos.', en:'A plant kept in indefinite vegetative phase specifically to produce genetically identical clones.', de:'Eine Pflanze, die gezielt dauerhaft in der vegetativen Phase gehalten wird, um genetisch identische Klone zu produzieren.', fr:'Plante maintenue en phase végétative indéfinie spécifiquement pour produire des clones génétiquement identiques.'}},
  {term:{es:'Planta parental (Parent plant)', en:'Parent plant', de:'Elternpflanze', fr:'Plante parentale'}, def:{es:'Cualquier planta usada como progenitor (macho o hembra) en un cruce.', en:'Any plant used as a parent (male or female) in a cross.', de:'Jede Pflanze, die als Elternteil (männlich oder weiblich) bei einer Kreuzung verwendet wird.', fr:'Toute plante utilisée comme géniteur (mâle ou femelle) dans un croisement.'}},
  {term:{es:'Poda (Pruning)', en:'Pruning', de:'Beschneiden (Pruning)', fr:'Taille (Pruning)'}, def:{es:'Remoción selectiva de partes de la planta para dirigir crecimiento, mejorar circulación de aire o penetración de luz.', en:'The selective removal of plant parts to direct growth, improve air circulation, or light penetration.', de:'Das selektive Entfernen von Pflanzenteilen, um das Wachstum zu lenken sowie die Luftzirkulation oder das Eindringen von Licht zu verbessern.', fr:'Retrait sélectif de parties de la plante pour orienter la croissance, améliorer la circulation de l’air ou la pénétration de la lumière.'}},
  {term:{es:'Polinización', en:'Pollination', de:'Bestäubung', fr:'Pollinisation'}, def:{es:'El proceso de transferencia de polen desde la estructura masculina al estigma de la flor femenina.', en:'The process of transferring pollen from the male structure to the stigma of the female flower.', de:'Der Prozess der Pollenübertragung von der männlichen Struktur zur Narbe der weiblichen Blüte.', fr:'Le processus de transfert du pollen de la structure mâle vers le stigmate de la fleur femelle.'}},
  {term:{es:'Potasio (K)', en:'Potassium (K)', de:'Kalium (K)', fr:'Potassium (K)'}, def:{es:'Macronutriente primario que regula apertura estomática, balance hídrico y activación de enzimas.', en:'A primary macronutrient that regulates stomatal opening, water balance, and enzyme activation.', de:'Ein primärer Makronährstoff, der die Spaltöffnung, den Wasserhaushalt und die Enzymaktivierung reguliert.', fr:'Macronutriment primaire qui régule l’ouverture stomatique, l’équilibre hydrique et l’activation enzymatique.'}},
  {term:{es:'PPF (Flujo de fotones fotosintéticos)', en:'PPF (Photosynthetic Photon Flux)', de:'PPF (Photosynthetischer Photonenfluss)', fr:'PPF (Flux de photons photosynthétiques)'}, def:{es:'La cantidad total de luz PAR que emite una fuente por segundo (μmol/s) — distinto de PPFD, que mide intensidad por área.', en:'The total amount of PAR light a source emits per second (μmol/s) — distinct from PPFD, which measures intensity per area.', de:'Die Gesamtmenge an PAR-Licht, die eine Quelle pro Sekunde abgibt (μmol/s) — im Unterschied zu PPFD, das die Intensität pro Fläche misst.', fr:'La quantité totale de lumière PAR émise par une source par seconde (μmol/s) — à distinguer du PPFD, qui mesure l’intensité par surface.'}},
  {term:{es:'PPFD', en:'PPFD', de:'PPFD', fr:'PPFD'}, def:{es:'La intensidad de luz fotosintéticamente útil que llega a la planta en un instante.', en:'The intensity of photosynthetically useful light reaching the plant at a given instant.', de:'Die Intensität des photosynthetisch nutzbaren Lichts, das die Pflanze in einem Moment erreicht.', fr:'L’intensité de lumière utile à la photosynthèse atteignant la plante à un instant donné.'}},
  {term:{es:'Preflor (Pre-flower)', en:'Pre-flower', de:'Vorblüte (Pre-flower)', fr:'Préfleur (Pre-flower)'}, def:{es:'Las primeras estructuras reproductivas visibles en los nudos superiores — su morfología determina el sexo de una planta de semilla.', en:'The first visible reproductive structures at the upper nodes — their morphology determines the sex of a seed-grown plant.', de:'Die ersten sichtbaren Fortpflanzungsstrukturen an den oberen Knoten — ihre Morphologie bestimmt das Geschlecht einer aus Samen gezogenen Pflanze.', fr:'Les premières structures reproductives visibles au niveau des nœuds supérieurs — leur morphologie détermine le sexe d’une plante issue de graine.'}},
  {term:{es:'Privación de luz (Light deprivation)', en:'Light deprivation', de:'Lichtdeprivation', fr:'Privation de lumière'}, def:{es:'Técnica en invernaderos donde se cubre la estructura con material opaco para inducir floración fuera de su ciclo natural.', en:'A greenhouse technique where the structure is covered with opaque material to induce flowering outside its natural cycle.', de:'Eine Technik in Gewächshäusern, bei der die Struktur mit lichtundurchlässigem Material abgedeckt wird, um die Blüte außerhalb ihres natürlichen Zyklus auszulösen.', fr:'Technique utilisée en serre consistant à couvrir la structure avec un matériau opaque pour induire la floraison en dehors de son cycle naturel.'}},
  {term:{es:'Propagación', en:'Propagation', de:'Vermehrung', fr:'Propagation'}, def:{es:'El proceso general de multiplicar plantas, sexualmente (por semilla) o asexualmente (por clones/esquejes).', en:'The general process of multiplying plants, either sexually (by seed) or asexually (by clones/cuttings).', de:'Der allgemeine Prozess der Pflanzenvermehrung, entweder geschlechtlich (durch Samen) oder ungeschlechtlich (durch Klone/Stecklinge).', fr:'Le processus général de multiplication des plantes, de manière sexuée (par graine) ou asexuée (par clones/boutures).'}},
  {term:{es:'Propagación por cultivo de tejidos', en:'Tissue culture propagation', de:'Vermehrung durch Gewebekultur', fr:'Propagation par culture de tissus'}, def:{es:'El proceso de multiplicar plantas mediante cultivo de tejidos, generando plántulas genéticamente idénticas.', en:'The process of multiplying plants through tissue culture, producing genetically identical plantlets.', de:'Der Prozess der Pflanzenvermehrung durch Gewebekultur, bei dem genetisch identische Jungpflanzen entstehen.', fr:'Le processus de multiplication des plantes par culture de tissus, produisant des plantules génétiquement identiques.'}},
  {term:{es:'Propagación vegetativa', en:'Vegetative propagation', de:'Vegetative Vermehrung', fr:'Propagation végétative'}, def:{es:'Reproducción asexual desde tejido vegetativo — genéticamente idéntica al progenitor.', en:'Asexual reproduction from vegetative tissue — genetically identical to the parent.', de:'Ungeschlechtliche Vermehrung aus vegetativem Gewebe — genetisch identisch mit der Elternpflanze.', fr:'Reproduction asexuée à partir de tissu végétatif — génétiquement identique au parent.'}},
  {term:{es:'Protocolo de sanitización', en:'Sanitization protocol', de:'Sanitierungsprotokoll', fr:'Protocole d’assainissement'}, def:{es:'El conjunto documentado de pasos de limpieza/desinfección a seguir en una instalación, por ejemplo entre plantas para prevenir HLVd.', en:'The documented set of cleaning/disinfection steps to follow in a facility, for example between plants to prevent HLVd.', de:'Die dokumentierte Abfolge von Reinigungs-/Desinfektionsschritten, die in einer Anlage einzuhalten ist, zum Beispiel zwischen Pflanzen zur Vorbeugung von HLVd.', fr:'Ensemble documenté d’étapes de nettoyage/désinfection à suivre dans une installation, par exemple entre les plantes pour prévenir le HLVd.'}},
  {term:{es:'Prueba genética (Genetic testing)', en:'Genetic testing', de:'Gentest', fr:'Test génétique'}, def:{es:'Análisis de laboratorio del ADN para identificar rasgos, verificar linaje o detectar patógenos.', en:'Laboratory analysis of DNA to identify traits, verify lineage, or detect pathogens.', de:'Laboranalyse der DNA zur Identifizierung von Merkmalen, Überprüfung der Abstammung oder zum Nachweis von Krankheitserregern.', fr:'Analyse en laboratoire de l’ADN pour identifier des caractères, vérifier une lignée ou détecter des pathogènes.'}},
  {term:{es:'Pudrición radicular (Root rot)', en:'Root rot', de:'Wurzelfäule', fr:'Pourriture racinaire'}, def:{es:'Descomposición del tejido radicular por patógenos como Pythium o Fusarium — raíces marrones y blandas vs. sanas (blancas y firmes).', en:'Decomposition of root tissue by pathogens like Pythium or Fusarium — brown, mushy roots vs. healthy ones (white and firm).', de:'Zersetzung des Wurzelgewebes durch Krankheitserreger wie Pythium oder Fusarium — braune, weiche Wurzeln im Gegensatz zu gesunden (weißen und festen).', fr:'Décomposition du tissu racinaire par des pathogènes comme Pythium ou Fusarium — racines brunes et molles contre racines saines (blanches et fermes).'}},
  {term:{es:'Pulgón radicular (Root aphid)', en:'Root aphid', de:'Wurzellaus', fr:'Puceron des racines'}, def:{es:'Variante de áfido que infesta el sistema radicular — más difícil de detectar tempranamente.', en:'A variant of aphid that infests the root system — harder to detect early.', de:'Eine Blattlaus-Variante, die das Wurzelsystem befällt — schwerer frühzeitig zu erkennen.', fr:'Variante du puceron qui infeste le système racinaire — plus difficile à détecter précocement.'}},
  {term:{es:'Punto de consigna (Setpoint)', en:'Setpoint', de:'Sollwert (Setpoint)', fr:'Point de consigne (Setpoint)'}, def:{es:'El valor objetivo programado en un controlador (ej. 24°C, 60% RH) que el sistema intenta mantener automáticamente.', en:'The target value programmed into a controller (e.g., 24°C, 60% RH) that the system automatically tries to maintain.', de:'Der in einem Controller programmierte Zielwert (z. B. 24°C, 60% RH), den das System automatisch aufrechtzuerhalten versucht.', fr:'La valeur cible programmée dans un contrôleur (par ex. 24°C, 60 % RH) que le système tente de maintenir automatiquement.'}},
  {term:{es:'Punto de rocío (Dew point)', en:'Dew point', de:'Taupunkt (Dew point)', fr:'Point de rosée (Dew point)'}, def:{es:'La temperatura a la que el aire alcanza 100% de humedad relativa y el vapor comienza a condensarse — importante para prevenir moho.', en:'The temperature at which air reaches 100% relative humidity and vapor begins to condense — important for preventing mold.', de:'Die Temperatur, bei der die Luft 100 % relative Luftfeuchtigkeit erreicht und der Dampf zu kondensieren beginnt — wichtig zur Schimmelvorbeugung.', fr:'La température à laquelle l’air atteint 100 % d’humidité relative et où la vapeur commence à se condenser — importante pour prévenir la moisissure.'}},
  {term:{es:'Pythium', en:'Pythium', de:'Pythium', fr:'Pythium'}, def:{es:'Oomiceto (no un hongo verdadero, aunque se trata como tal en la práctica) que prospera en exceso de humedad y baja oxigenación, causando pudrición de raíces.', en:'An oomycete (not a true fungus, though treated as one in practice) that thrives in excess moisture and low oxygenation, causing root rot.', de:'Ein Oomycet (kein echter Pilz, wird in der Praxis aber so behandelt), das bei übermäßiger Feuchtigkeit und geringer Sauerstoffversorgung gedeiht und Wurzelfäule verursacht.', fr:'Oomycète (pas un vrai champignon, bien que traité comme tel en pratique) qui prospère en cas d’excès d’humidité et de faible oxygénation, causant la pourriture des racines.'}},
  {term:{es:'Quelación (Chelation)', en:'Chelation', de:'Chelatbildung (Chelation)', fr:'Chélation'}, def:{es:'Proceso donde un ion metálico se une a una molécula orgánica que lo mantiene disponible para absorción, incluso en pH no ideal.', en:'A process in which a metal ion binds to an organic molecule that keeps it available for absorption, even at non-ideal pH.', de:'Ein Prozess, bei dem sich ein Metallion an ein organisches Molekül bindet, das es auch bei nicht idealem pH-Wert für die Aufnahme verfügbar hält.', fr:'Processus au cours duquel un ion métallique se lie à une molécule organique qui le maintient disponible pour l’absorption, même à un pH non idéal.'}},
  {term:{es:'Quemadura por luz', en:'Light burn', de:'Lichtverbrennung', fr:'Brûlure lumineuse'}, def:{es:'Daño tisular visible por exceso de intensidad o calor — necrosis amarilla-blanquecina localizada.', en:'Visible tissue damage from excess intensity or heat — localized yellowish-white necrosis.', de:'Sichtbare Gewebeschädigung durch übermäßige Intensität oder Hitze — lokalisierte gelblich-weiße Nekrose.', fr:'Dommage tissulaire visible dû à un excès d’intensité ou de chaleur — nécrose jaunâtre-blanchâtre localisée.'}},
  {term:{es:'Quemadura por nutrientes (Nutrient burn)', en:'Nutrient burn', de:'Nährstoffverbrennung (Nutrient burn)', fr:'Brûlure nutritive (Nutrient burn)'}, def:{es:'Daño en puntas y bordes de hojas por concentración excesiva de nutrientes en la solución.', en:'Damage to leaf tips and edges caused by an excessive concentration of nutrients in the solution.', de:'Schäden an Blattspitzen und -rändern durch eine übermäßige Nährstoffkonzentration in der Lösung.', fr:'Dommages aux pointes et aux bords des feuilles causés par une concentration excessive de nutriments dans la solution.'}},
  {term:{es:'Quimiotipo', en:'Chemotype', de:'Chemotyp', fr:'Chimiotype'}, def:{es:'Clasificación del cannabis por su perfil químico (THC/CBD), no por su forma de planta.', en:'Cannabis classification by chemical profile (THC/CBD), not by plant shape.', de:'Cannabis-Klassifizierung nach chemischem Profil (THC/CBD), nicht nach Pflanzenform.', fr:'Classification du cannabis selon son profil chimique (THC/CBD), pas selon la forme de la plante.'}},
  {term:{es:'Quimiovar (Chemovar)', en:'Chemovar', de:'Chemovar', fr:'Chimiovar'}, def:{es:'Clasificación basada en el perfil combinado de cannabinoides y terpenos (1–2 cannabinoides dominantes, 2–4 terpenos dominantes), propuesta por el investigador Arno Hazekamp. Distinto del "Quimiotipo", que solo considera la relación THC:CBD.', en:'A classification based on the combined cannabinoid + terpene profile (1–2 dominant cannabinoids, 2–4 dominant terpenes), proposed by researcher Arno Hazekamp. Distinct from "Chemotype," which only considers the THC:CBD ratio.', de:'Eine Klassifizierung, die auf dem kombinierten Cannabinoid- und Terpenprofil basiert (1–2 dominante Cannabinoide, 2–4 dominante Terpene), vorgeschlagen vom Forscher Arno Hazekamp. Zu unterscheiden vom "Chemotyp", der nur das THC:CBD-Verhältnis berücksichtigt.', fr:'Classification basée sur le profil combiné de cannabinoïdes et de terpènes (1–2 cannabinoïdes dominants, 2–4 terpènes dominants), proposée par le chercheur Arno Hazekamp. Distincte du « chimiotype », qui ne considère que le rapport THC:CBD.'}},
  {term:{es:'Rack de secado (Drying rack)', en:'Drying rack', de:'Trockengestell (Drying rack)', fr:'Grille de séchage (Drying rack)'}, def:{es:'Estructura con niveles de bandejas/mallas donde se seca la flor ya separada, permitiendo buena circulación de aire.', en:'A structure with tiers of trays/screens where already-separated flower is dried, allowing good air circulation.', de:'Eine Struktur mit gestapelten Ablagen/Gittern, auf denen bereits abgetrennte Blüten getrocknet werden, mit guter Luftzirkulation.', fr:'Structure à plusieurs niveaux de plateaux/grilles où sèche la fleur déjà séparée, permettant une bonne circulation de l’air.'}},
  {term:{es:'Raíz pivotante (Taproot)', en:'Taproot', de:'Pfahlwurzel', fr:'Racine pivotante'}, def:{es:'La raíz principal, vertical, que crece desde la semilla germinada hacia abajo.', en:'The main, vertical root that grows downward from the germinated seed.', de:'Die vertikale Hauptwurzel, die vom gekeimten Samen aus nach unten wächst.', fr:'La racine principale, verticale, qui pousse vers le bas depuis la graine germée.'}},
  {term:{es:'Ramificación (Branching)', en:'Branching', de:'Verzweigung (Branching)', fr:'Ramification (Branching)'}, def:{es:'Desarrollo de ramas laterales, influenciado por genética y técnicas de entrenamiento.', en:'The development of lateral branches, influenced by genetics and training techniques.', de:'Die Entwicklung seitlicher Zweige, beeinflusst durch Genetik und Trainingstechniken.', fr:'Le développement de branches latérales, influencé par la génétique et les techniques d’entraînement.'}},
  {term:{es:'Rapid Rooter', en:'Rapid Rooter', de:'Rapid Rooter', fr:'Rapid Rooter'}, def:{es:'Medio de propagación comercial de General Hydroponics, hecho de fibra vegetal compostada — alternativa orgánica a la lana de roca.', en:'A commercial propagation medium from General Hydroponics, made from composted plant fiber — an organic alternative to rockwool.', de:'Ein kommerzielles Vermehrungsmedium von General Hydroponics aus kompostierter Pflanzenfaser — eine organische Alternative zu Steinwolle.', fr:'Milieu de propagation commercial de General Hydroponics, fabriqué à partir de fibre végétale compostée — alternative organique à la laine de roche.'}},
  {term:{es:'Rasgo (Trait)', en:'Trait', de:'Merkmal', fr:'Caractère'}, def:{es:'Una característica específica y heredable de la planta.', en:'A specific, heritable characteristic of the plant.', de:'Ein spezifisches, vererbbares Merkmal der Pflanze.', fr:'Une caractéristique spécifique et héréditaire de la plante.'}},
  {term:{es:'Rasgo dominante', en:'Dominant trait', de:'Dominantes Merkmal', fr:'Caractère dominant'}, def:{es:'Un rasgo que se expresa con al menos una copia del alelo correspondiente.', en:'A trait that expresses with at least one copy of the corresponding allele.', de:'Ein Merkmal, das sich mit mindestens einer Kopie des entsprechenden Allels ausprägt.', fr:'Un caractère qui s’exprime avec au moins une copie de l’allèle correspondant.'}},
  {term:{es:'Rasgo recesivo', en:'Recessive trait', de:'Rezessives Merkmal', fr:'Caractère récessif'}, def:{es:'Un rasgo que solo se expresa con dos copias idénticas del alelo (homocigota).', en:'A trait that only expresses with two identical copies of the allele (homozygous).', de:'Ein Merkmal, das sich nur mit zwei identischen Kopien des Allels (homozygot) ausprägt.', fr:'Un caractère qui ne s’exprime qu’avec deux copies identiques de l’allèle (homozygote).'}},
  {term:{es:'Registrador de datos (Data logger)', en:'Data logger', de:'Datenlogger', fr:'Enregistreur de données (Data logger)'}, def:{es:'Dispositivo que registra lecturas de sensores a lo largo del tiempo, para analizar tendencias históricas.', en:'A device that records sensor readings over time, to analyze historical trends.', de:'Ein Gerät, das Sensormesswerte über die Zeit aufzeichnet, um historische Trends zu analysieren.', fr:'Dispositif qui enregistre les relevés des capteurs dans le temps, afin d’analyser les tendances historiques.'}},
  {term:{es:'Reporte de monitoreo (Scouting report)', en:'Scouting report', de:'Monitoringbericht (Scouting report)', fr:'Rapport de surveillance (Scouting report)'}, def:{es:'Registro de lo observado durante el monitoreo, para seguimiento de tendencias y evaluación de medidas de control.', en:'A record of what was observed during scouting, used to track trends and evaluate control measures.', de:'Eine Aufzeichnung der beim Monitoring beobachteten Befunde, zur Trendverfolgung und Bewertung von Kontrollmaßnahmen.', fr:'Enregistrement des observations faites lors de la surveillance, utilisé pour suivre les tendances et évaluer les mesures de contrôle.'}},
  {term:{es:'Retrocruce (Backcross/BX)', en:'Backcross (BX)', de:'Rückkreuzung (BX)', fr:'Rétrocroisement (BX)'}, def:{es:'El cruce de un híbrido con una de sus líneas parentales originales — técnica para reforzar/fijar rasgos específicos.', en:'The cross of a hybrid with one of its original parent lines — a technique used to reinforce/fix specific traits.', de:'Die Kreuzung eines Hybriden mit einer seiner ursprünglichen Elternlinien — eine Technik zur Verstärkung bzw. Fixierung bestimmter Merkmale.', fr:'Le croisement d’un hybride avec l’une de ses lignées parentales d’origine — technique utilisée pour renforcer/fixer des caractères spécifiques.'}},
  {term:{es:'Riego por goteo (Drip irrigation)', en:'Drip irrigation', de:'Tröpfchenbewässerung (Drip irrigation)', fr:'Irrigation goutte à goutte (Drip irrigation)'}, def:{es:'Sistema donde la solución nutritiva se administra en pequeñas cantidades, gota a gota, directamente en la base de cada planta a través de emisores/goteros — uno de los métodos más comunes en cultivo comercial por su precisión y escalabilidad.', en:'A system where nutrient solution is delivered in small amounts, drop by drop, directly to the base of each plant through emitters/drippers — one of the most common methods in commercial cultivation for its precision and scalability.', de:'Ein System, bei dem die Nährlösung in kleinen Mengen, Tropfen für Tropfen, direkt an die Basis jeder Pflanze über Tropfer/Emitter abgegeben wird — eine der gängigsten Methoden im kommerziellen Anbau wegen ihrer Präzision und Skalierbarkeit.', fr:'Système dans lequel la solution nutritive est administrée en petites quantités, goutte à goutte, directement à la base de chaque plante via des goutteurs/émetteurs — l’une des méthodes les plus courantes en culture commerciale pour sa précision et son évolutivité.'}},
  {term:{es:'Riesgo de moho (Mold risk)', en:'Mold risk', de:'Schimmelrisiko (Mold risk)', fr:'Risque de moisissure (Mold risk)'}, def:{es:'La probabilidad de desarrollo de moho, determinada por humedad, actividad de agua y condiciones ambientales.', en:'The likelihood of mold development, determined by moisture, water activity, and environmental conditions.', de:'Die Wahrscheinlichkeit einer Schimmelbildung, bestimmt durch Feuchtigkeit, Wasseraktivität und Umweltbedingungen.', fr:'La probabilité de développement de moisissure, déterminée par l’humidité, l’activité de l’eau et les conditions environnementales.'}},
  {term:{es:'Ritmo circadiano', en:'Circadian rhythm', de:'Zirkadianer Rhythmus', fr:'Rythme circadien'}, def:{es:'Ciclo biológico interno de aproximadamente 24 horas que regula procesos fisiológicos de la planta, distinto del fotoperiodo (la señal externa de luz/oscuridad).', en:'An internal biological cycle of roughly 24 hours that regulates the plant’s physiological processes, distinct from photoperiod (the external light/dark signal).', de:'Ein interner biologischer Zyklus von etwa 24 Stunden, der die physiologischen Prozesse der Pflanze reguliert — zu unterscheiden von der Photoperiode (dem äußeren Licht-/Dunkelsignal).', fr:'Cycle biologique interne d’environ 24 heures qui régule les processus physiologiques de la plante, distinct de la photopériode (le signal externe de lumière/obscurité).'}},
  {term:{es:'Rojo lejano (Far-red)', en:'Far-red', de:'Dunkelrot (Far-red)', fr:'Rouge lointain (Far-red)'}, def:{es:'Luz ~700-750nm, influye en morfología vía fitocromos, usado para acelerar floración.', en:'Light at ~700-750nm, influences morphology via phytochromes, used to accelerate flowering.', de:'Licht bei ~700-750nm, beeinflusst über Phytochrome die Morphologie und wird zur Beschleunigung der Blüte eingesetzt.', fr:'Lumière ~700-750 nm, influence la morphologie via les phytochromes, utilisée pour accélérer la floraison.'}},
  {term:{es:'Rosin', en:'Rosin', de:'Rosin', fr:'Rosin'}, def:{es:'Concentrado hecho con calor y presión mecánica, sin solventes.', en:'A concentrate made with heat and mechanical pressure, no solvents.', de:'Ein Konzentrat, hergestellt mit Hitze und mechanischem Druck, ohne Lösungsmittel.', fr:'Concentré fabriqué avec chaleur et pression mécanique, sans solvant.'}},
  {term:{es:'Sala de clones (Clone room)', en:'Clone room', de:'Klonraum', fr:'Salle de clonage'}, def:{es:'Espacio para el enraizamiento y desarrollo temprano de esquejes, con alta humedad controlada.', en:'A space for rooting and early development of cuttings, with controlled high humidity.', de:'Ein Raum zur Bewurzelung und frühen Entwicklung von Stecklingen, mit kontrollierter hoher Luftfeuchtigkeit.', fr:'Espace destiné à l’enracinement et au développement précoce des boutures, avec une humidité élevée contrôlée.'}},
  {term:{es:'Sala de curado (Curing room)', en:'Curing room', de:'Reiferaum (Curing room)', fr:'Salle d’affinage (Curing room)'}, def:{es:'Espacio dedicado al almacenamiento de flor ya seca durante el curado, con condiciones más estables.', en:'A space dedicated to storing already-dried flower during curing, with more stable conditions.', de:'Ein Raum, der der Lagerung bereits getrockneter Blüten während der Reifung dient, mit stabileren Bedingungen.', fr:'Espace dédié au stockage de la fleur déjà séchée pendant l’affinage, avec des conditions plus stables.'}},
  {term:{es:'Sala de madres (Mother room)', en:'Mother room', de:'Mutterpflanzenraum', fr:'Salle des mères'}, def:{es:'Espacio dedicado al mantenimiento de plantas madre en vegetativo, típicamente bajo 18-24h de luz.', en:'A space dedicated to keeping mother plants in vegetative growth, typically under 18-24 hours of light.', de:'Ein Raum, der der Erhaltung von Mutterpflanzen in der vegetativen Phase dient, typischerweise unter 18-24 Stunden Licht.', fr:'Espace dédié au maintien des plantes mères en croissance végétative, généralement sous 18 à 24 h de lumière.'}},
  {term:{es:'Sala de propagación (Propagation room)', en:'Propagation room', de:'Vermehrungsraum', fr:'Salle de propagation'}, def:{es:'Espacio que abarca germinación y enraizamiento — término más general.', en:'A space that covers both germination and rooting — a more general term.', de:'Ein Raum, der sowohl Keimung als auch Bewurzelung umfasst — ein allgemeinerer Begriff.', fr:'Espace couvrant à la fois la germination et l’enracinement — terme plus général.'}},
  {term:{es:'Sala de secado (Dry room)', en:'Dry room', de:'Trockenraum (Dry room)', fr:'Salle de séchage (Dry room)'}, def:{es:'Espacio dedicado al secado con control de temperatura, humedad relativa y oscuridad.', en:'A space dedicated to drying with control over temperature, relative humidity, and darkness.', de:'Ein dem Trocknen gewidmeter Raum mit Kontrolle über Temperatur, relative Luftfeuchtigkeit und Dunkelheit.', fr:'Espace dédié au séchage avec contrôle de la température, de l’humidité relative et de l’obscurité.'}},
  {term:{es:'Sala limpia (Clean room)', en:'Clean room', de:'Reinraum (Clean room)', fr:'Salle blanche (Clean room)'}, def:{es:'Espacio con protocolos estrictos de sanitización y control de acceso, usado en propagación o cultivo de tejidos.', en:'A space with strict sanitization protocols and access control, used in propagation or tissue culture.', de:'Ein Raum mit strengen Sanitierungsprotokollen und Zutrittskontrolle, eingesetzt bei der Vermehrung oder Gewebekultur.', fr:'Espace soumis à des protocoles stricts d’assainissement et de contrôle d’accès, utilisé en propagation ou en culture de tissus.'}},
  {term:{es:'Sanitización', en:'Sanitization', de:'Sanitisierung (Hygienemaßnahmen)', fr:'Assainissement (Sanitization)'}, def:{es:'Prácticas para reducir microorganismos, plagas y contaminantes a niveles seguros — incluye limpieza, desinfección y bioseguridad.', en:'Practices to reduce microorganisms, pests, and contaminants to safe levels — includes cleaning, disinfection, and biosecurity.', de:'Maßnahmen zur Reduzierung von Mikroorganismen, Schädlingen und Kontaminanten auf ein sicheres Niveau — umfasst Reinigung, Desinfektion und Biosicherheit.', fr:'Pratiques visant à réduire les micro-organismes, les nuisibles et les contaminants à des niveaux sûrs — inclut le nettoyage, la désinfection et la biosécurité.'}},
  {term:{es:'ScroG (Screen of Green)', en:'ScroG (Screen of Green)', de:'ScroG (Screen of Green)', fr:'ScroG (Screen of Green)'}, def:{es:'Malla horizontal a través de la cual se entrelazan las ramas, creando un dosel uniforme.', en:'A horizontal screen through which branches are woven, creating an even canopy.', de:'Ein horizontales Netz, durch das die Zweige geflochten werden, um ein gleichmäßiges Blätterdach zu erzeugen.', fr:'Un filet horizontal à travers lequel les branches sont entrelacées, créant une canopée uniforme.'}},
  {term:{es:'Secado (Drying)', en:'Drying', de:'Trocknung', fr:'Séchage'}, def:{es:'Reducir gradualmente el contenido de humedad de la flor recién cosechada, hasta un nivel seguro — típicamente 7-14 días.', en:'Gradually reducing the moisture content of freshly harvested flower to a safe level — typically 7-14 days.', de:'Der Feuchtigkeitsgehalt der frisch geernteten Blüte wird schrittweise auf ein sicheres Niveau gesenkt — typischerweise 7-14 Tage.', fr:'Réduire progressivement la teneur en humidité de la fleur fraîchement récoltée jusqu’à un niveau sûr — typiquement 7 à 14 jours.'}},
  {term:{es:'Secado colgado (Hang dry)', en:'Hang dry', de:'Hängetrocknung (Hang dry)', fr:'Séchage suspendu (Hang dry)'}, def:{es:'Ramas o plantas enteras colgadas boca abajo — secado más lento y uniforme por la mayor masa conectada.', en:'Whole branches or plants hung upside down — slower, more even drying due to the greater connected mass.', de:'Ganze Zweige oder Pflanzen werden kopfüber aufgehängt — durch die größere zusammenhängende Masse langsamere, gleichmäßigere Trocknung.', fr:'Branches ou plantes entières suspendues la tête en bas — séchage plus lent et plus uniforme grâce à la masse connectée plus importante.'}},
  {term:{es:'Secado lento (Slow dry)', en:'Slow dry', de:'Langsame Trocknung (Slow dry)', fr:'Séchage lent (Slow dry)'}, def:{es:'Deshidratación gradual (mayor HR ambiental, ~55-62%, temperaturas más bajas) — mejor preservación de terpenos.', en:'Gradual dehydration (higher ambient RH, ~55-62%, lower temperatures) — better terpene preservation.', de:'Schrittweise Dehydrierung (höhere Umgebungs-RH, ~55-62%, niedrigere Temperaturen) — bessere Terpenerhaltung.', fr:'Déshydratation progressive (RH ambiante plus élevée, ~55-62 %, températures plus basses) — meilleure préservation des terpènes.'}},
  {term:{es:'Senescencia', en:'Senescence', de:'Seneszenz', fr:'Sénescence'}, def:{es:'Proceso natural de envejecimiento y muerte programada de tejidos vegetales — parte normal de la maduración, no necesariamente una enfermedad.', en:'The natural process of aging and programmed death of plant tissue — a normal part of maturation, not necessarily disease.', de:'Der natürliche Prozess der Alterung und des programmierten Absterbens von Pflanzengewebe — ein normaler Teil der Reifung, nicht zwangsläufig eine Krankheit.', fr:'Processus naturel de vieillissement et de mort programmée des tissus végétaux — partie normale de la maturation, pas nécessairement une maladie.'}},
  {term:{es:'Sensor', en:'Sensor', de:'Sensor', fr:'Capteur'}, def:{es:'Dispositivo que mide una variable ambiental específica y transmite la lectura a un sistema de monitoreo o control.', en:'A device that measures a specific environmental variable and transmits the reading to a monitoring or control system.', de:'Ein Gerät, das eine bestimmte Umweltvariable misst und den Messwert an ein Überwachungs- oder Steuerungssystem übermittelt.', fr:'Dispositif qui mesure une variable environnementale spécifique et transmet la lecture à un système de surveillance ou de contrôle.'}},
  {term:{es:'Sistema endocannabinoide', en:'Endocannabinoid system', de:'Endocannabinoid-System', fr:'Système endocannabinoïde'}, def:{es:'La red de receptores del cuerpo (CB1, CB2) con la que interactúan los cannabinoides.', en:'The body’s network of receptors (CB1, CB2) that cannabinoids interact with.', de:'Das körpereigene Rezeptornetzwerk (CB1, CB2), mit dem Cannabinoide interagieren.', fr:'Le réseau de récepteurs du corps (CB1, CB2) avec lequel interagissent les cannabinoïdes.'}},
  {term:{es:'Sobresecado (Overdry)', en:'Overdry', de:'Übertrocknung (Overdry)', fr:'Surséchage (Overdry)'}, def:{es:'Flor con más humedad perdida de la deseada — textura quebradiza, pérdida de terpenos, generalmente irreversible.', en:'Flower that has lost more moisture than desired — brittle texture, terpene loss, generally irreversible.', de:'Blüte, die mehr Feuchtigkeit verloren hat als erwünscht — brüchige Textur, Terpenverlust, in der Regel irreversibel.', fr:'Fleur ayant perdu plus d’humidité que souhaité — texture cassante, perte de terpènes, généralement irréversible.'}},
  {term:{es:'SOG (Sea of Green)', en:'SOG (Sea of Green)', de:'SOG (Sea of Green)', fr:'SOG (Sea of Green)'}, def:{es:'Alta densidad de plantas pequeñas, cada una con una sola cola central, maximizando rendimiento por m².', en:'A high density of small plants, each with a single central cola, maximizing yield per square meter.', de:'Eine hohe Dichte kleiner Pflanzen, jede mit einer einzigen zentralen Cola, um den Ertrag pro Quadratmeter zu maximieren.', fr:'Forte densité de petites plantes, chacune avec une seule cola centrale, maximisant le rendement par m².'}},
  {term:{es:'Sol completo (Full sun)', en:'Full sun', de:'Volle Sonne', fr:'Plein soleil'}, def:{es:'Exposición solar directa y sin sombreado durante todo el ciclo de luz.', en:'Direct, unshaded sun exposure throughout the entire light cycle.', de:'Direkte, unbeschattete Sonneneinstrahlung während des gesamten Lichtzyklus.', fr:'Exposition solaire directe et sans ombrage pendant tout le cycle de lumière.'}},
  {term:{es:'Sólidos disueltos totales (TDS)', en:'Total dissolved solids (TDS)', de:'Gesamtgelöste Feststoffe (TDS)', fr:'Solides dissous totaux (TDS)'}, def:{es:'Medida alternativa a la EC, en ppm — la conversión entre EC y TDS varía según la escala del medidor (500 o 700), causando confusión frecuente entre cultivadores.', en:'An alternative measure to EC, in ppm — the conversion between EC and TDS varies depending on the meter’s scale (500 or 700), causing frequent confusion among growers.', de:'Ein alternatives Maß zur EC, in ppm — die Umrechnung zwischen EC und TDS variiert je nach Skala des Messgeräts (500 oder 700), was bei Growern häufig zu Verwirrung führt.', fr:'Mesure alternative à l’EC, en ppm — la conversion entre EC et TDS varie selon l’échelle de l’appareil de mesure (500 ou 700), ce qui cause une confusion fréquente chez les cultivateurs.'}},
  {term:{es:'Solución nutritiva', en:'Nutrient solution', de:'Nährlösung', fr:'Solution nutritive'}, def:{es:'Mezcla de agua con fertilizantes disueltos, formulada para aportar macro y micronutrientes en proporciones adecuadas.', en:'A mixture of water with dissolved fertilizers, formulated to supply macro- and micronutrients in appropriate proportions.', de:'Eine Mischung aus Wasser mit gelösten Düngemitteln, formuliert, um Makro- und Mikronährstoffe in geeigneten Verhältnissen bereitzustellen.', fr:'Mélange d’eau et d’engrais dissous, formulé pour apporter les macro- et micronutriments dans des proportions adéquates.'}},
  {term:{es:'SOP (Procedimiento Operativo Estándar)', en:'SOP (Standard Operating Procedure)', de:'SOP (Standardarbeitsanweisung)', fr:'SOP (Procédure opératoire standard)'}, def:{es:'Documento que detalla paso a paso cómo realizar una tarea de forma consistente, para reproducibilidad y cumplimiento normativo.', en:'A document detailing step by step how to perform a task consistently, for reproducibility and regulatory compliance.', de:'Ein Dokument, das Schritt für Schritt beschreibt, wie eine Aufgabe konsistent durchzuführen ist, zwecks Reproduzierbarkeit und behördlicher Konformität.', fr:'Document détaillant étape par étape comment réaliser une tâche de manière constante, pour la reproductibilité et la conformité réglementaire.'}},
  {term:{es:'Suelo vivo (Living soil)', en:'Living soil', de:'Lebendige Erde (Living soil)', fr:'Sol vivant (Living soil)'}, def:{es:'Sistema de cultivo en suelo que mantiene un ecosistema biológico activo (microorganismos, hongos micorrízicos, materia orgánica en descomposición) que cicla nutrientes de forma natural, reduciendo o eliminando la necesidad de fertirriego sintético.', en:'A soil-based growing system that maintains an active biological ecosystem (microorganisms, mycorrhizal fungi, decomposing organic matter) that cycles nutrients naturally, reducing or eliminating the need for synthetic fertigation.', de:'Ein bodenbasiertes Anbausystem, das ein aktives biologisches Ökosystem (Mikroorganismen, Mykorrhizapilze, zersetzende organische Substanz) aufrechterhält, das Nährstoffe auf natürliche Weise kreisführt und den Bedarf an synthetischer Fertigation verringert oder eliminiert.', fr:'Système de culture en sol qui maintient un écosystème biologique actif (micro-organismes, champignons mycorhiziens, matière organique en décomposition) qui recycle naturellement les nutriments, réduisant ou éliminant le besoin de fertigation synthétique.'}},
  {term:{es:'Supercropping', en:'Supercropping', de:'Supercropping', fr:'Supercropping'}, def:{es:'Doblar y aplastar suavemente el tallo sin cortar, dañando tejidos internos — la planta refuerza esa zona.', en:'Gently bending and crushing the stem without cutting it, damaging internal tissue — the plant reinforces that area.', de:'Sanftes Biegen und Quetschen des Stängels ohne Schnitt, wodurch inneres Gewebe beschädigt wird — die Pflanze verstärkt diesen Bereich.', fr:'Plier et écraser doucement la tige sans la couper, endommageant les tissus internes — la plante renforce cette zone.'}},
  {term:{es:'Sustrato (Substrate)', en:'Substrate', de:'Substrat', fr:'Substrat'}, def:{es:'Término general para cualquier medio físico (con o sin contenido nutricional propio) donde se desarrollan las raíces de una planta.', en:'A general term for any physical medium (with or without inherent nutrient content) in which a plant’s roots develop.', de:'Ein allgemeiner Begriff für jedes physische Medium (mit oder ohne eigenen Nährstoffgehalt), in dem sich die Wurzeln einer Pflanze entwickeln.', fr:'Terme général désignant tout milieu physique (avec ou sans teneur nutritive propre) dans lequel se développent les racines d’une plante.'}},
  {term:{es:'Sustrato sin suelo (Soil-less media)', en:'Soil-less media', de:'Bodenloses Substrat (Soil-less media)', fr:'Substrat sans sol (Soil-less media)'}, def:{es:'Cualquier medio de cultivo que no contiene tierra mineral natural (ej. fibra de coco, lana de roca, turba, perlita) — término paraguas que engloba la mayoría de sustratos usados en cultivo hidropónico y semi-hidropónico.', en:'Any growing medium that does not contain natural mineral soil (e.g., coco coir, rockwool, peat moss, perlite) — an umbrella term covering most substrates used in hydroponic and semi-hydroponic cultivation.', de:'Jedes Anbaumedium, das keine natürliche mineralische Erde enthält (z. B. Kokosfaser, Steinwolle, Torfmoos, Perlit) — ein Oberbegriff, der die meisten in der hydroponischen und semi-hydroponischen Kultivierung verwendeten Substrate umfasst.', fr:'Tout milieu de culture ne contenant pas de terre minérale naturelle (ex. fibre de coco, laine de roche, tourbe, perlite) — terme générique englobant la plupart des substrats utilisés en culture hydroponique et semi-hydroponique.'}},
  {term:{es:'Taco/Plug de propagación', en:'Propagation plug', de:'Vermehrungswürfel (Plug)', fr:'Plug de propagation'}, def:{es:'Bloque pequeño de sustrato diseñado para un esqueje o semilla individual.', en:'A small block of substrate designed for a single cutting or seed.', de:'Ein kleiner Substratblock, der für einen einzelnen Steckling oder Samen ausgelegt ist.', fr:'Petit bloc de substrat conçu pour une bouture ou une graine individuelle.'}},
  {term:{es:'Tallo (Stem/Stalk)', en:'Stem / stalk', de:'Stängel', fr:'Tige'}, def:{es:'Estructura principal de soporte, que transporta agua, nutrientes y azúcares entre raíces y follaje.', en:'The main support structure, which transports water, nutrients, and sugars between the roots and the foliage.', de:'Die zentrale Stützstruktur, die Wasser, Nährstoffe und Zucker zwischen Wurzeln und Laub transportiert.', fr:'Structure principale de soutien, qui transporte l’eau, les nutriments et les sucres entre les racines et le feuillage.'}},
  {term:{es:'Tasa de germinación', en:'Germination rate', de:'Keimrate', fr:'Taux de germination'}, def:{es:'El porcentaje de semillas de un lote que germinan exitosamente.', en:'The percentage of seeds in a batch that germinate successfully.', de:'Der Prozentsatz der Samen einer Charge, die erfolgreich keimen.', fr:'Le pourcentage de graines d’un lot qui germent avec succès.'}},
  {term:{es:'Técnica de película nutritiva (NFT)', en:'Nutrient Film Technique (NFT)', de:'Nutrient Film Technique (NFT)', fr:'Technique du film nutritif (NFT)'}, def:{es:'Sistema hidropónico donde una fina película de solución nutritiva fluye continuamente sobre las raíces, que están expuestas parcialmente al aire dentro de un canal inclinado.', en:'A hydroponic system where a thin film of nutrient solution flows continuously over the roots, which are partially exposed to air inside a sloped channel.', de:'Ein hydroponisches System, bei dem ein dünner Film aus Nährlösung kontinuierlich über die Wurzeln fließt, die in einem geneigten Kanal teilweise der Luft ausgesetzt sind.', fr:'Système hydroponique où un mince film de solution nutritive s’écoule en continu sur les racines, partiellement exposées à l’air à l’intérieur d’un canal incliné.'}},
  {term:{es:'Temperatura', en:'Temperature', de:'Temperatur', fr:'Température'}, def:{es:'Medida del calor ambiental, variable central que afecta fotosíntesis, transpiración y desarrollo.', en:'A measure of ambient heat, a central variable affecting photosynthesis, transpiration, and development.', de:'Ein Maß für die Umgebungswärme, eine zentrale Variable, die Photosynthese, Transpiration und Entwicklung beeinflusst.', fr:'Mesure de la chaleur ambiante, variable centrale qui affecte la photosynthèse, la transpiration et le développement.'}},
  {term:{es:'Temperatura del aire', en:'Air temperature', de:'Lufttemperatur', fr:'Température de l’air'}, def:{es:'La temperatura del ambiente que rodea a la planta, distinta de la temperatura de la hoja misma.', en:'The temperature of the environment surrounding the plant, distinct from the temperature of the leaf itself.', de:'Die Temperatur der Umgebung, die die Pflanze umgibt — zu unterscheiden von der Temperatur des Blattes selbst.', fr:'La température de l’environnement entourant la plante, distincte de la température de la feuille elle-même.'}},
  {term:{es:'Temperatura foliar', en:'Leaf temperature', de:'Blatttemperatur', fr:'Température foliaire'}, def:{es:'La temperatura específica de la superficie de la hoja, que puede diferir del aire por transpiración y luz directa — relevante para el VPD de hoja vs. de aire.', en:'The specific temperature of the leaf surface, which can differ from the air due to transpiration and direct light — relevant for leaf VPD vs. air VPD.', de:'Die spezifische Temperatur der Blattoberfläche, die sich aufgrund von Transpiration und direktem Licht von der Lufttemperatur unterscheiden kann — relevant für den Blatt-VPD im Vergleich zum Luft-VPD.', fr:'La température spécifique de la surface de la feuille, qui peut différer de celle de l’air en raison de la transpiration et de la lumière directe — pertinente pour le VPD foliaire par rapport au VPD de l’air.'}},
  {term:{es:'Terpeno', en:'Terpene', de:'Terpen', fr:'Terpène'}, def:{es:'Compuesto aromático de la planta que también puede modular el efecto de los cannabinoides.', en:'An aromatic plant compound that can also modulate the effect of cannabinoids.', de:'Eine aromatische Pflanzenverbindung, die auch die Wirkung von Cannabinoiden modulieren kann.', fr:'Composé aromatique de la plante pouvant aussi moduler l’effet des cannabinoïdes.'}},
  {term:{es:'Terpenoide', en:'Terpenoid', de:'Terpenoid', fr:'Terpénoïde'}, def:{es:'Terpeno modificado químicamente (típicamente por oxidación), a diferencia de un terpeno "puro" — ambos términos se usan a menudo indistintamente en la industria.', en:'A chemically modified terpene (typically via oxidation), as distinct from a "pure" terpene — both terms are often used interchangeably in the industry.', de:'Ein chemisch modifiziertes Terpen (typischerweise durch Oxidation), im Unterschied zu einem "reinen" Terpen — beide Begriffe werden in der Branche oft synonym verwendet.', fr:'Terpène chimiquement modifié (typiquement par oxydation), à distinguer d’un terpène « pur » — les deux termes sont souvent utilisés indifféremment dans l’industrie.'}},
  {term:{es:'Terpinoleno', en:'Terpinolene', de:'Terpinolen', fr:'Terpinolène'}, def:{es:'Aroma complejo (floral/herbal/cítrico), asociado por reportes de usuarios a efecto más estimulante — evidencia preclínica de propiedades antioxidantes.', en:'A complex aroma (floral/herbal/citrus), associated in user reports with a more stimulating effect — preclinical evidence of antioxidant properties.', de:'Ein komplexes Aroma (blumig/krautig/zitrusartig), das in Nutzerberichten mit einer eher anregenden Wirkung assoziiert wird — präklinische Hinweise auf antioxidative Eigenschaften.', fr:'Arôme complexe (floral/herbacé/agrumes), associé dans les retours d’utilisateurs à un effet plus stimulant — données précliniques de propriétés antioxydantes.'}},
  {term:{es:'THC (Tetrahidrocannabinol)', en:'THC (Tetrahydrocannabinol)', de:'THC (Tetrahydrocannabinol)', fr:'THC (Tétrahydrocannabinol)'}, def:{es:'El cannabinoide psicoactivo principal, responsable del efecto "high".', en:'The main psychoactive cannabinoid, responsible for the "high" effect.', de:'Das wichtigste psychoaktive Cannabinoid, verantwortlich für den "High"-Effekt.', fr:'Le principal cannabinoïde psychoactif, responsable de l’effet « high ».'}},
  {term:{es:'THCA / CBDA', en:'THCA / CBDA', de:'THCA / CBDA', fr:'THCA / CBDA'}, def:{es:'Las formas ácidas y no psicoactivas de THC y CBD, presentes en la planta fresca antes de la decarboxilación.', en:'The acidic, non-psychoactive forms of THC and CBD, present in fresh plant material before decarboxylation.', de:'Die sauren, nicht-psychoaktiven Formen von THC und CBD, vorhanden in frischem Pflanzenmaterial vor der Decarboxylierung.', fr:'Les formes acides et non psychoactives du THC et du CBD, présentes dans la plante fraîche avant décarboxylation.'}},
  {term:{es:'THCP (Tetrahidrocannabiforol)', en:'THCP (Tetrahydrocannabiphorol)', de:'THCP (Tetrahydrocannabiphorol)', fr:'THCP (Tétrahydrocannabiphorol)'}, def:{es:'Descubierto en 2019 (Citti, Cannazza et al., Universidad de Módena) en la variedad "FM2", homólogo del THC con cadena de 7 carbonos en vez de 5. Mayor afinidad in vitro al CB1 que el Δ9-THC — pero esto no confirma proporcionalmente mayor efecto psicoactivo real, ya que afinidad de unión y potencia farmacológica no son equivalentes.', en:'Discovered in 2019 (Citti, Cannazza et al., University of Modena) in the "FM2" variety, a THC homolog with a 7-carbon chain instead of 5. Shows higher in vitro CB1 affinity than Δ9-THC — but this doesn’t proportionally confirm a greater real psychoactive effect, since binding affinity and pharmacological potency aren’t equivalent.', de:'2019 entdeckt (Citti, Cannazza et al., Universität Modena) in der Sorte "FM2", ein THC-Homolog mit einer 7-Kohlenstoff-Kette statt 5. Zeigt in vitro eine höhere CB1-Affinität als Δ9-THC — das bestätigt jedoch nicht proportional eine stärkere reale psychoaktive Wirkung, da Bindungsaffinität und pharmakologische Potenz nicht gleichbedeutend sind.', fr:'Découvert en 2019 (Citti, Cannazza et al., Université de Modène) dans la variété « FM2 », homologue du THC à chaîne de 7 carbones au lieu de 5. Présente une affinité in vitro plus élevée pour le CB1 que le Δ9-THC — mais cela ne confirme pas proportionnellement un effet psychoactif réel plus fort, l’affinité de liaison et la puissance pharmacologique n’étant pas équivalentes.'}},
  {term:{es:'THCV (Tetrahidrocannabivarina)', en:'THCV (Tetrahydrocannabivarin)', de:'THCV (Tetrahydrocannabivarin)', fr:'THCV (Tétrahydrocannabivarine)'}, def:{es:'Análogo del THC de cadena más corta, apodado "la weed dietética" — leve en dosis altas, efecto más claro en dosis bajas.', en:'A shorter-chain THC analog, nicknamed "diet weed" — mild at high doses, a clearer effect at low doses.', de:'Ein THC-Analog mit kürzerer Kette, im Volksmund "Diät-Weed" genannt — bei hohen Dosen mild, bei niedrigen Dosen klarerer Effekt.', fr:'Un analogue du THC à chaîne plus courte, surnommé « la weed diététique » — léger à forte dose, effet plus clair à faible dose.'}},
  {term:{es:'Toxicidad', en:'Toxicity', de:'Toxizität', fr:'Toxicité'}, def:{es:'Cuando la planta recibe una cantidad excesiva de un nutriente, causando daño fisiológico.', en:'When a plant receives an excessive amount of a nutrient, causing physiological damage.', de:'Wenn eine Pflanze eine übermäßige Menge eines Nährstoffs erhält, was physiologische Schäden verursacht.', fr:'Lorsque la plante reçoit une quantité excessive d’un nutriment, provoquant des dommages physiologiques.'}},
  {term:{es:'Transición', en:'Transition', de:'Übergangsphase', fr:'Transition'}, def:{es:'El período intermedio entre vegetativo y floración plena, con señales de cambio hormonal pero sin flores maduras aún.', en:'The intermediate period between vegetative growth and full flowering, with signs of hormonal change but no mature flowers yet.', de:'Der Übergangszeitraum zwischen vegetativem Wachstum und voller Blüte, mit Anzeichen hormoneller Veränderung, aber noch ohne reife Blüten.', fr:'La période intermédiaire entre la croissance végétative et la pleine floraison, avec des signes de changement hormonal mais sans fleurs matures encore.'}},
  {term:{es:'Trasplante', en:'Transplanting', de:'Umtopfen', fr:'Repiquage'}, def:{es:'El proceso de mover una planta a un contenedor más grande.', en:'The process of moving a plant to a larger container.', de:'Der Prozess, eine Pflanze in ein größeres Gefäß umzusetzen.', fr:'Le processus consistant à déplacer une plante dans un contenant plus grand.'}},
  {term:{es:'Trastorno por uso de cannabis (CUD)', en:'Cannabis Use Disorder (CUD)', de:'Cannabiskonsumstörung (CUD)', fr:'Trouble lié à l’usage du cannabis (CUD)'}, def:{es:'El diagnóstico clínico reconocido para la dependencia problemática al cannabis.', en:'The clinically recognized diagnosis for problematic cannabis dependence.', de:'Die klinisch anerkannte Diagnose für problematische Cannabisabhängigkeit.', fr:'Le diagnostic cliniquement reconnu pour la dépendance problématique au cannabis.'}},
  {term:{es:'Tricoma', en:'Trichome', de:'Trichom', fr:'Trichome'}, def:{es:'Las glándulas microscópicas donde se concentran los cannabinoides y terpenos.', en:'The microscopic glands where cannabinoids and terpenes are concentrated.', de:'Die mikroskopischen Drüsen, in denen sich Cannabinoide und Terpene konzentrieren.', fr:'Les glandes microscopiques où se concentrent cannabinoïdes et terpènes.'}},
  {term:{es:'Trips', en:'Thrips', de:'Thripse', fr:'Thrips'}, def:{es:'Insecto que se alimenta raspando células vegetales, causando manchas plateadas o punteado; algunas especies transmiten virus.', en:'An insect that feeds by rasping plant cells, causing silvery patches or stippling; some species transmit viruses.', de:'Ein Insekt, das sich durch das Aufraspeln von Pflanzenzellen ernährt und dabei silbrige Flecken oder Sprenkelungen verursacht; einige Arten übertragen Viren.', fr:'Insecte qui se nourrit en raclant les cellules végétales, causant des taches argentées ou un maculage ; certaines espèces transmettent des virus.'}},
  {term:{es:'Túnel alto (High tunnel)', en:'High tunnel', de:'Hochtunnel', fr:'Tunnel haut (High tunnel)'}, def:{es:'Similar al hoop house pero de mayor altura, permite paso de personas y maquinaria.', en:'Similar to a hoop house but taller, allowing people and machinery to move through it.', de:'Ähnlich wie ein Folientunnel, aber höher, sodass Personen und Maschinen hindurchgehen können.', fr:'Similaire à la serre tunnel mais plus haute, permettant le passage de personnes et de machines.'}},
  {term:{es:'Turba (Peat moss)', en:'Peat moss', de:'Torfmoos (Peat moss)', fr:'Tourbe (Peat moss)'}, def:{es:'Sustrato orgánico formado por musgo de turbera parcialmente descompuesto — buena retención de agua, naturalmente ácido, y muy usado en mezclas de sustrato para siembra y trasplante.', en:'An organic substrate formed from partially decomposed bog moss — good water retention, naturally acidic, and widely used in substrate mixes for seeding and transplanting.', de:'Ein organisches Substrat aus teilweise zersetztem Moormoos — gute Wasserspeicherung, von Natur aus sauer und weit verbreitet in Substratmischungen für Aussaat und Umtopfen.', fr:'Substrat organique formé de mousse de tourbière partiellement décomposée — bonne rétention d’eau, naturellement acide, largement utilisé dans les mélanges de substrat pour le semis et le repiquage.'}},
  {term:{es:'Ultravioleta (UV)', en:'Ultraviolet (UV)', de:'Ultraviolett (UV)', fr:'Ultraviolet (UV)'}, def:{es:'Radiación por debajo de ~400nm, estudiada por su rol en tricomas y flavonoides, con nivel de evidencia variable según el estudio.', en:'Radiation below ~400nm, studied for its role in trichomes and flavonoids, with a variable level of evidence depending on the study.', de:'Strahlung unterhalb von ~400nm, untersucht wegen ihrer Rolle bei Trichomen und Flavonoiden, mit je nach Studie unterschiedlichem Evidenzgrad.', fr:'Rayonnement en dessous de ~400 nm, étudié pour son rôle dans les trichomes et les flavonoïdes, avec un niveau de preuve variable selon les études.'}},
  {term:{es:'Umbral de alarma', en:'Alarm threshold', de:'Alarmschwelle', fr:'Seuil d’alarme'}, def:{es:'El valor límite que, al excederse, dispara una notificación o alerta al operador.', en:'The limit value that, when exceeded, triggers a notification or alert to the operator.', de:'Der Grenzwert, der bei Überschreitung eine Benachrichtigung oder einen Alarm an den Bediener auslöst.', fr:'La valeur limite qui, une fois dépassée, déclenche une notification ou une alerte pour l’opérateur.'}},
  {term:{es:'Uso de mallas (Netting)', en:'Netting', de:'Netzverwendung (Netting)', fr:'Utilisation de filets (Netting)'}, def:{es:'Aplicación específica de malla como soporte o herramienta de entrenamiento del dosel.', en:'The specific application of mesh netting as support or as a canopy-training tool.', de:'Der gezielte Einsatz von Netzgewebe als Stütze oder als Werkzeug zum Trainieren des Blätterdachs.', fr:'Application spécifique d’un filet comme support ou comme outil d’entraînement de la canopée.'}},
  {term:{es:'Variedad', en:'Variety', de:'Sorte', fr:'Variété'}, def:{es:'Adaptación natural de la planta a su entorno, como una landrace.', en:'The plant’s natural adaptation to its environment, like a landrace.', de:'Die natürliche Anpassung der Pflanze an ihre Umgebung, wie eine Landrasse.', fr:'Adaptation naturelle de la plante à son environnement, comme une landrace.'}},
  {term:{es:'Ventana de cosecha (Harvest window)', en:'Harvest window', de:'Erntefenster (Harvest window)', fr:'Fenêtre de récolte (Harvest window)'}, def:{es:'El rango de tiempo en que la planta está en su punto óptimo de madurez, según el efecto deseado (eufórico vs. sedante).', en:'The time range during which the plant is at its optimal point of maturity, depending on the desired effect (euphoric vs. sedating).', de:'Der Zeitraum, in dem sich die Pflanze am optimalen Reifepunkt befindet, je nach gewünschter Wirkung (euphorisierend vs. beruhigend).', fr:'La plage de temps pendant laquelle la plante est à son point optimal de maturité, selon l’effet recherché (euphorisant vs. sédatif).'}},
  {term:{es:'Vermiculita', en:'Vermiculite', de:'Vermiculit', fr:'Vermiculite'}, def:{es:'Mineral en capas expandido con calor, usado como aditivo de sustrato — a diferencia de la perlita, retiene más agua y algo de nutrientes, mejorando la capacidad de retención de humedad del sustrato.', en:'A layered mineral expanded with heat, used as a substrate additive — unlike perlite, it retains more water and some nutrients, improving the substrate’s moisture retention capacity.', de:'Ein geschichtetes, mit Hitze aufgeblähtes Mineral, das als Substratzusatz verwendet wird — im Gegensatz zu Perlit speichert es mehr Wasser und einige Nährstoffe und verbessert so die Feuchtigkeitsspeicherfähigkeit des Substrats.', fr:'Minéral en couches expansé à la chaleur, utilisé comme additif de substrat — contrairement à la perlite, il retient plus d’eau et quelques nutriments, améliorant la capacité de rétention d’humidité du substrat.'}},
  {term:{es:'Viabilidad de semillas', en:'Seed viability', de:'Samenkeimfähigkeit', fr:'Viabilité des graines'}, def:{es:'La capacidad de una semilla para germinar exitosamente, afectada por edad, almacenamiento y salud genética.', en:'A seed’s ability to germinate successfully, affected by age, storage, and genetic health.', de:'Die Fähigkeit eines Samens, erfolgreich zu keimen, beeinflusst durch Alter, Lagerung und genetische Gesundheit.', fr:'La capacité d’une graine à germer avec succès, influencée par son âge, son stockage et sa santé génétique.'}},
  {term:{es:'Viroide', en:'Viroid', de:'Viroid', fr:'Viroïde'}, def:{es:'Categoría de patógeno compuesto únicamente por ARN circular infeccioso, sin cápside proteica — los agentes infecciosos más pequeños conocidos.', en:'A category of pathogen made up solely of infectious circular RNA, with no protein coat — the smallest known infectious agents.', de:'Eine Pathogenkategorie, die ausschließlich aus infektiöser zirkulärer RNA ohne Proteinhülle besteht — die kleinsten bekannten Infektionserreger.', fr:'Catégorie de pathogène composée uniquement d’ARN circulaire infectieux, sans capside protéique — les plus petits agents infectieux connus.'}},
  {term:{es:'Virus', en:'Virus', de:'Virus', fr:'Virus'}, def:{es:'Patógeno microscópico de material genético rodeado de cápside proteica, que requiere infectar células vivas para replicarse.', en:'A microscopic pathogen consisting of genetic material surrounded by a protein coat, which requires infecting living cells to replicate.', de:'Ein mikroskopisch kleiner Krankheitserreger aus genetischem Material, umgeben von einer Proteinhülle, der zur Vermehrung lebende Zellen infizieren muss.', fr:'Pathogène microscopique constitué de matériel génétique entouré d’une capside protéique, qui doit infecter des cellules vivantes pour se répliquer.'}},
  {term:{es:'VPD (déficit de presión de vapor)', en:'VPD (vapor pressure deficit)', de:'VPD (Dampfdruckdefizit)', fr:'VPD (déficit de pression de vapeur)'}, def:{es:'La medida que indica cuánta humedad puede absorber el aire, clave para el cultivo.', en:'The measure of how much moisture the air can absorb, key for cultivation.', de:'Das Maß dafür, wie viel Feuchtigkeit die Luft aufnehmen kann, entscheidend für den Anbau.', fr:'La mesure de la quantité d’humidité que l’air peut absorber, essentielle pour la culture.'}},
  {term:{es:'Winterización', en:'Winterization', de:'Winterisierung', fr:'Winterisation'}, def:{es:'Paso de purificación en la extracción con solvente donde el extracto se congela y filtra para eliminar grasas y ceras vegetales indeseadas.', en:'A purification step in solvent extraction where the extract is frozen and filtered to remove unwanted plant fats and waxes.', de:'Ein Reinigungsschritt bei der Lösungsmittelextraktion, bei dem der Extrakt eingefroren und gefiltert wird, um unerwünschte Pflanzenfette und -wachse zu entfernen.', fr:'Une étape de purification dans l’extraction par solvant où l’extrait est congelé et filtré pour éliminer les graisses et cires végétales indésirables.'}},
  {term:{es:'Zinc (Zn)', en:'Zinc (Zn)', de:'Zink (Zn)', fr:'Zinc (Zn)'}, def:{es:'Micronutriente que participa en síntesis de auxinas y sistemas enzimáticos.', en:'A micronutrient that participates in auxin synthesis and enzyme systems.', de:'Ein Mikronährstoff, der an der Auxinsynthese und an Enzymsystemen beteiligt ist.', fr:'Micronutriment qui participe à la synthèse des auxines et aux systèmes enzymatiques.'}},
  {term:{es:'Zona limpia (Clean zone)', en:'Clean zone', de:'Reinzone (Clean zone)', fr:'Zone propre (Clean zone)'}, def:{es:'Área con protocolos de sanitización elevados y acceso restringido, para proteger material de contaminación cruzada.', en:'An area with elevated sanitization protocols and restricted access, to protect material from cross-contamination.', de:'Ein Bereich mit erhöhten Sanitierungsprotokollen und eingeschränktem Zutritt, um Material vor Kreuzkontamination zu schützen.', fr:'Zone soumise à des protocoles d’assainissement renforcés et à un accès restreint, afin de protéger le matériel de la contamination croisée.'}},
  {term:{es:'Zona radicular (Root zone)', en:'Root zone', de:'Wurzelzone', fr:'Zone racinaire'}, def:{es:'El volumen de sustrato donde se desarrolla el sistema radicular — área crítica en el fertirriego.', en:'The volume of substrate where the root system develops — a critical area in fertigation.', de:'Das Substratvolumen, in dem sich das Wurzelsystem entwickelt — ein kritischer Bereich bei der Fertigation.', fr:'Le volume de substrat où se développe le système racinaire — zone critique en fertirrigation.'}},
  {term:{es:'Zona sucia (Dirty zone)', en:'Dirty zone', de:'Schmutzzone (Dirty zone)', fr:'Zone sale (Dirty zone)'}, def:{es:'Área de mayor riesgo de contaminación — el diseño de flujo busca evitar movimiento directo de zona sucia a zona limpia.', en:'An area of higher contamination risk — facility flow design aims to prevent direct movement from the dirty zone to the clean zone.', de:'Ein Bereich mit höherem Kontaminationsrisiko — die Ablaufgestaltung zielt darauf ab, eine direkte Bewegung von der Schmutzzone in die Reinzone zu verhindern.', fr:'Zone à risque de contamination plus élevé — la conception des flux vise à éviter un déplacement direct de la zone sale vers la zone propre.'}},
];
