function wrapForGating(gate){
  const el = document.getElementById(gate.id);
  if(!el || el.dataset.gated) return;
  const wrapper = document.createElement('div');
  wrapper.className = 'full-gate-inner';
  while(el.firstChild){ wrapper.appendChild(el.firstChild); }
  el.appendChild(wrapper);
  el.classList.add('gate-wrap');
  el.dataset.gated = '1';
  el.dataset.gateTitleKey = gate.titleKey;
  el.dataset.gateDescKey = gate.descKey;
}
FULL_GATES.forEach(wrapForGating);

function setFullGate(el, locked){
  if(!el) return;
  const inner = el.querySelector('.full-gate-inner');
  let overlay = el.querySelector('.gate-cta');
  if(locked){
    inner.classList.add('blur-gate');
    if(overlay) overlay.remove();
    overlay = document.createElement('div');
    overlay.className = 'gate-cta';
    overlay.innerHTML = `<div class="gate-card">${LOCK_SVG}<h4>${t(el.dataset.gateTitleKey)}</h4><p>${t(el.dataset.gateDescKey)}</p><button class="gate-btn">${t('gateUnlockBtn')}</button></div>`;
    el.appendChild(overlay);
  } else {
    inner.classList.remove('blur-gate');
    if(overlay) overlay.remove();
  }
}

function gateGrid(containerEl, cardSelector, visibleCount, teaserTitleKey, teaserDescKey){
  if(!containerEl) return;
  const cards = Array.from(containerEl.querySelectorAll(cardSelector));
  cards.forEach((c,i)=>{ c.style.display = (!isPremium && i>=visibleCount) ? 'none' : ''; });
  const existingTeaser = containerEl.querySelector('.teaser-card');
  if(existingTeaser) existingTeaser.remove();
  if(!isPremium && cards.length>visibleCount){
    const teaser = document.createElement('div');
    teaser.className = 'teaser-card';
    teaser.innerHTML = `${LOCK_SVG}<h4>${t(teaserTitleKey)}</h4><p>${t(teaserDescKey)}</p>`;
    containerEl.appendChild(teaser);
  }
}

