function buildSearchIndex(){
  const fromCountries = countries.map(c=>({title:c.name, cat:'País', screen:'legal', countryRef:c.name}));
  const fromCultivars = cultivars.map(c=>({title:c.name, cat:'Cultivar', screen:'variedades'}));
  return [...searchIndexStatic, ...fromCountries, ...fromCultivars];
}
function openSearch(){
  document.getElementById('searchModal').classList.add('active');
  document.getElementById('searchInput').value = '';
  document.getElementById('searchResults').innerHTML = '';
  setTimeout(()=> document.getElementById('searchInput').focus(), 50);
}
function closeSearch(){ document.getElementById('searchModal').classList.remove('active'); }

/* ===================== ONBOARDING ===================== */
function getOnboardSlides(){
  return [
    {title:t('ob1Title'), body:t('ob1Body')},
    {title:t('ob2Title'), body:t('ob2Body')},
    {title:t('ob4Title'), body:t('ob4Body')},
    {title:t('ob3Title'), body:t('ob3Body')}
  ];
}
let onboardStep = 0;
function renderOnboardSlide(){
  const s = getOnboardSlides()[onboardStep];
  document.getElementById('onboardSlides').innerHTML = `<h2 style="font-family:'Manrope',sans-serif; font-weight:500; font-size:24px; margin-bottom:12px;">${s.title}</h2><p style="font-size:14px; color:var(--ink-soft); line-height:1.6;">${s.body}</p>`;
  document.querySelectorAll('.ob-dot').forEach((d,i)=> d.classList.toggle('on', i===onboardStep));
  document.getElementById('onboardNextBtn').textContent = onboardStep===3 ? t('obEmpezar') : t('obSiguiente');
}
function onboardNext(){
  if(onboardStep < 3){ onboardStep++; renderOnboardSlide(); }
  else onboardFinish();
}
async function onboardFinish(){
  document.getElementById('onboardModal').classList.remove('active');
  try{ await window.storage.set('onboarding-seen', 'true', false); }catch(e){}
}
async function ageGateConfirm(isAdult){
  if(isAdult){
    try{ localStorage.setItem('age-verified', 'true'); }catch(e){}
    document.getElementById('ageGateModal').classList.remove('active');
    maybeShowOnboarding();
  } else {
    document.getElementById('ageGateQuestion').style.display = 'none';
    document.getElementById('ageGateBlocked').style.display = 'block';
  }
}
async function checkAgeGate(){
  try{
    if(localStorage.getItem('age-verified') === 'true'){
      document.getElementById('ageGateModal').classList.remove('active');
      maybeShowOnboarding();
      return;
    }
  }catch(e){}
  // No verificado todavía: el modal ya está visible por defecto (clase 'active' en el HTML), no se llama a maybeShowOnboarding() hasta resolver esto.
}
checkAgeGate();
populateBuscarPaisSelect();
populateBuscarVetSelect();
async function maybeShowOnboarding(){
  try{
    const res = await window.storage.get('onboarding-seen', false);
    if(res && res.value === 'true') return;
  }catch(e){}
  onboardStep = 0;
  renderOnboardSlide();
  document.getElementById('onboardModal').classList.add('active');
}

function renderCuenta(){
  const authCard = document.getElementById('cuentaAuthCard');
  const loggedInWrap = document.getElementById('cuentaLoggedInOnly');
  const estadoEl = document.getElementById('cuentaEstadoTexto');
  const btnEl = document.getElementById('cuentaBtnAccion');
  if(!estadoEl) return;
  const user = window.mvCurrentUser;
  if(authCard) authCard.style.display = user ? 'none' : '';
  if(loggedInWrap) loggedInWrap.style.display = user ? '' : 'none';
  if(!user) return;
  if(isPremium){
    estadoEl.innerHTML = `<b style="color:var(--moss-deep);">${t('cuentaPremiumActivo')}</b>`;
    btnEl.textContent = t('cuentaGestionarBtn');
    btnEl.onclick = ()=> alert(t('cuentaGestionarAlert'));
  } else {
    estadoEl.innerHTML = `<b style="color:var(--resin);">${t('cuentaPlanGratis')}</b>`;
    btnEl.textContent = t('cuentaSuscribirBtn');
    btnEl.onclick = openPremium;
  }
  const profile = window.mvCurrentProfile;
  const nombreEl = document.getElementById('cuentaNombreInput');
  const correoEl = document.getElementById('cuentaCorreoInput');
  if(nombreEl && document.activeElement !== nombreEl) nombreEl.value = profile?.display_name || '';
  if(correoEl && document.activeElement !== correoEl) correoEl.value = profile?.contact_email || '';
  const idiomaEl = document.getElementById('cuentaIdiomaActual');
  if(idiomaEl){
    const nombres = {es:'Español', en:'English', de:'Deutsch', fr:'Français'};
    idiomaEl.textContent = nombres[currentLang];
  }
}

