function filterEducacion(){
  const pais = document.getElementById('eduFiltroPais')?.value || '';
  const esp = document.getElementById('eduFiltroEsp')?.value || '';
  const cards = document.querySelectorAll('.edu-card');
  let visible = 0;
  cards.forEach(c => {
    const matchPais = !pais || c.dataset.pais === pais;
    const matchEsp = !esp || c.dataset.esp === esp;
    const show = matchPais && matchEsp;
    c.style.display = show ? '' : 'none';
    if(show) visible++;
  });
  const countEl = document.getElementById('eduResultCount');
  if(countEl) countEl.textContent = visible + ' ' + t('eduResultados');
}
